import type { UsCatalogSeed } from "./n64UsCatalog";
export const usCatalog: UsCatalogSeed[] = [{"id":"god-of-war","title":"God of War","year":2005,"genres":["Action","Adventure"],"description":"This action/adventure/combat game makes powerful use of the darkly imaginative world of Ancient Greek mythology, where the realms of the mortal and the divine collide in a pervasive atmosphere of brute force and violence. Playing as Kratos, throughout the game players will wield double blades bound to his body by long chains, weapons symbolic of this vicious world to which he is bound and the fate from which he seeks to escape. Featuring an hour of cinematic sequences and a deep combat system incorporating context-sensitive actions and an extensive range of combos, GOD OF WAR takes players through various environments that will have them fighting fierce enemies, swinging on ropes, scaling mountain cliffs, swimming through rivers and sliding down zip lines. The result is a unique and thrilling adventure through Greek mythology.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/26","developer":"SCE Santa Monica Studio","coverName":"God of War (USA)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"M - Mature","rating":{"score":4.51,"count":668}},{"id":"god-of-war-ii","title":"God of War II","year":2007,"genres":["Action","Adventure"],"description":"Kratos is now the God of War, having defeated the Olympian god Ares. Shunned by the other gods and still haunted by nightmares from his past, Kratos decides to join an army of Spartans in an attack on the city of Rhodes. Kratos also ignores a warning from the goddess Athena that his lust for revenge is alienating the other gods.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/88","developer":"SCE Studio Santa Monica","coverName":"God of War II (USA)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"M - Mature","rating":{"score":4.59,"count":543}},{"id":"grand-theft-auto-san-andreas","title":"Grand Theft Auto: San Andreas","year":2004,"genres":["Adventure","Racing","Sandbox","Shooter"],"description":"Five years ago Carl Johnson escaped from the pressures of life in Los Santos, San Andreas...a city tearing itself apart with gang trouble, drugs and corruption. Where filmstars and millionaires do their best to avoid the dealers and gangbangers.\nNow, it's the early 90s. Carl's got to go home. His mother has been murdered, his family has fallen apart and his childhood friends are all heading towards disaster.\n\nOn his return to the neighborhood, a couple of corrupt cops frame him for homicide. CJ is forced on a journey that takes him across the entire state of San Andreas, to save his family and to take control of the streets.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3930","developer":"Rockstar North","coverName":"Grand Theft Auto - San Andreas (USA) (v1.03)","players":"2","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.62,"count":465}},{"id":"dragon-ball-z-budokai-tenkaichi-3","title":"Dragon Ball Z: Budokai Tenkaichi 3","year":2007,"genres":["Fighting"],"description":"An extreme 3D fighting experience, improving upon last year's game with over 150 playable characters, enhanced fighting techniques, beautifully refined effects and shading techniques, making each character's effects more realistic, and over 20 battle stages. This is the ultimate chapter in Budokai Tenkaichi series with over 20 new characters that have never been seen in any other DBZ video games such as Nail, King Cold and King Vegeta and battle stages that fans will love.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7224","developer":"Spike","coverName":"Dragon Ball Z - Budokai Tenkaichi 3 (USA) (En,Ja)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":4.47,"count":459}},{"id":"gran-turismo-4","title":"Gran Turismo 4","year":2004,"genres":["Racing"],"description":"Gran Turismo is back and there is a huge variety of cars, including the Model T Ford, Jay Leno's Tank Car, and some of the famous Le Mans cars from down the years. GT4 has brand new tracks, including the famous Nürburgring, and tracks set in famous locations such as Paris, the Grand Canyon, and many more. There is a new Photo mode in GT4 where you can take photographs of a saved replays or in photo mode, and save them to your memory card, or a USB storage device. There is also a new B-Spec mode where become race manager, in other words you let the computer do the work, so it's useful if your doing a endurance race.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3929","developer":"Polyphony Digital","coverName":"Gran Turismo 4 (USA) (v1.01)","players":"6","publisher":"Sony Computer Entertainment Europe","esrb":"E - Everyone","rating":{"score":4.53,"count":403}},{"id":"shadow-of-the-colossus","title":"Shadow of the Colossus","year":2005,"genres":["Action","Adventure"],"description":"Tales speak of a distant place where creatures the size of mountains roam free. Bound to the land, these beasts hold the key to a mystical power - a power capable of bringing the departed back from the other side. Spurred by love, yet armed only with sword and bow, one man faces an extraordinary challenge - a solitary quest to find and slay opponents so immense they seem to possess no weakness. But in this desolate, beautiful land, very little is ever as it seems. And the journey is only just beginning...","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/2240","developer":"Team ICO","coverName":"Shadow of the Colossus (USA)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.58,"count":383}},{"id":"kingdom-hearts","title":"Kingdom Hearts","year":2002,"genres":["Action","Adventure","Platformer","RPG"],"description":"For the first time ever, Disney films come together in one game, but it's up to you make it their world the happiest place on Earth. Kingdom Hearts follows Sora in his quest to find his friends and Court Wizard Donald and Captain Goofy as they set out to find the missing King Mickey. The three searchers meet and embark on a magnificent, but dangerous, journey across familiar Disney worlds filled with monsters. Over 100 characters appear in the game including Jafar, Tarzan, and Hercules.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/2559","developer":"Square","coverName":"Kingdom Hearts (USA)","players":"1","publisher":"Square Enix","esrb":"E - Everyone","rating":{"score":4.46,"count":355}},{"id":"burnout-3-takedown","title":"Burnout 3: Takedown","year":2004,"genres":["Racing"],"description":"Burnout 3: Takedown is a racing game which encourages aggressive driving and lets you use your vehicle to smash your way to the finish line by taking out your rivals and causing massive multi-car pileups. The more cars you take out, damage you inflict, the more events and cars you can unlock. Burnout 3 also has a \"crash\" mode which puts your vehicle at a variety of traffic junctions jam-packed with moving vehicles and pickups to see just how much monetary damage you can inflict.\n\nBurnout 3: Takedown continues the racing series with more cars, more tracks, a more detailed crash engine, and a multitude of new gameplay modes for single players, multiple players on one system, and online play.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4158","developer":"Criterion Software","coverName":"Burnout 3 - Takedown (USA)","players":"6","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.48,"count":334}},{"id":"silent-hill-2","title":"Silent Hill 2","year":2001,"genres":["Action","Horror"],"description":"Silent Hill 2 is not a direct sequel to the events and characters of the first Silent Hill game. Instead, it centers on James Sunderland, who enters the town after receiving a letter written by his deceased wife, saying she is waiting for him in their \"special place\" in Silent Hill. Joined by Maria who resembles her except for a more provocative outfit and personality, he searches for her and discovers the truth about her death. Additional material in re-releases and ports included Born from a Wish, a sub-scenario which focuses on Maria before she and James meet.\n\nSilent Hill 2 uses a third-person perspective and gameplay places a greater emphasis on finding items and solving riddles than combat, similar to the first Silent Hill. Psychological aspects such as the gradual disappearance of Mary's letter were added to the game. More humanoid than their counterparts in the preceding game, some of the monsters were designed as a reflection of James' subconscious. Real-life references to history, films and literary works can also be found in the game.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4793","developer":"Team Silent","coverName":"Silent Hill 2 (USA) (En,Ja) (v1.20)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.64,"count":324}},{"id":"final-fantasy-x","title":"Final Fantasy X","year":2001,"genres":["RPG"],"description":"There are seven main playable characters in Final Fantasy X. Tidus is a cheerful young teenager and the star blitzball player for the Zanarkand Abes. He has long resented his father, a renowned blitzball player who disappeared during Tidus's youth. Yuna is the daughter of the High Summoner Braska, who defeated Sin to bring about the Calm, a time of peace. Yuna embarks on a pilgrimage to obtain the final aeon and defeat Sin. Kimahri Ronso is a young warrior of the Ronso tribe who watched over Yuna during her childhood. Wakka is a blitzball player and devout follower of the Yevon order. Lulu is a stoic and self-possessed, but well-meaning Black Mage. Auron is a taciturn former warrior monk, and finally Rikku is a perky Al Bhed girl with extensive knowledge of machinery. The primary antagonists of the game are Maester Seymour Guado and the other maesters of the Yevon religion, while the enormous whale-like monster Sin serves as the primary source of conflict.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/20","developer":"Square","coverName":"Final Fantasy X (USA)","players":"1","publisher":"Square","esrb":"T - Teen","rating":{"score":4.52,"count":287}},{"id":"resident-evil-4","title":"Resident Evil 4","year":2005,"genres":["Horror","Shooter"],"description":"Picking up six years after Resident Evil 2, the fourth game in the series follows former cop (now US agent) Leon S. Kennedy to Europe on a top secret mission to investigate the disappearance of the president's daughter Ashley. As Leon encounters unimaginable horrors, he must find out who or what is behind everything. Old friends...and enemies...lurk around every corner as Leon attempts to find out who is truly behind the kidnapping of the president's daughter.\n\nResident Evil 4 is a major change from the previous installments. Instead of a fixed third person perspective, the game features a new \"behind the back\" movement camera angle and an \"over the shoulder\" aiming feature that allows players to control their gun movement for specific body part hits. It features a brand new AI system and more open environments that allow enemies to work together to capture and corner Leon. Enemies are now humans, which allows them to climb up ladders, open doors, and use weapons throughout the game.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3928","developer":"Capcom Production Studio 4","coverName":"Resident Evil 4 (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.56,"count":279}},{"id":"ratchet-clank","title":"Ratchet & Clank","year":2002,"genres":["Action","Adventure","Platformer"],"description":"Ratchet & Clank is a platform/adventure game in a similar vein to the 3D versions of the Rayman, Sonic, Mario, or other games. It involves the two protagonists Ratchet, a furry alien creature, and Clank, a nerdy little robot, going on a quest to find Captain Qwark and ultimately to help save the galaxy.\n\nRatchet & Clank includes many of the best features of previous similar games, but makes itself unique in a number of ways. Firstly each of the game's levels are huge sweeping vistas with extremely detailed buildings which are visible at all times (i.e. there is no distance fog). This means that a building on the horizon is not just a \"backdrop\"; in all likelihood Ratchet will be exploring it in a few moments time. Secondly, the game includes a number of sub-games, such as a space fight sequence and a number of turret shoot-outs which are akin to Missile Command in the first person.\n\nThe game has over twenty levels (planets) and includes as many real-time cut-scenes which tell the story. Also of note is that the story is non-linear, requiring the player to return to previous levels to complete objectives and to choose between multiple paths forward. There is also a respectable array of weapons, gadgets, and accessories to find or buy as the game progresses, which offer some unique gameplay features.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7797","developer":"Insomniac Games","coverName":"Ratchet _ Clank (USA) (En,Fr,De,Es,It)","players":"1","publisher":"Sony Computer Entertainment","esrb":"T - Teen","rating":{"score":4.27,"count":279}},{"id":"tekken-5","title":"Tekken 5","year":2005,"genres":["Fighting"],"description":"Loved across the world for its amazing characters, explosive graphics and lightning-fast gameplay, Tekken 5 promises to deliver the next generation of blistered fingers and bleary eyes as it brings players the ultimate, most visually stunning fighting experience ever seen in a Tekken game.\nTekken 5 brings back the popular cast of characters from the previous games along with three new characters for a total of 20 default characters to start, with even more to unlock as you progress in the game. The game allows players to use fight money to customize their character with various accessories such as hats, glasses and an assortment of different costumes. Each of the new characters is equipped with a variety of deadly techniques, and the returning characters have been updated with new moves and combos. New to Tekken 5 is a bonus action adventure game that unfolds a side story to the action-packed fighting sequences.\nAfter the completion of The King of Iron Fist Tournament 4, a fierce battle between father and son unfolded at Mishima Zaibatsu headquarters. Jin emerges as the victor in this battle and continues to defeat Heihachi, his grandfather - but spares both Kazuya and Heihachi's lives in honour of his mother who loved peace. Soon after Jin's departure, a swarm of Jacks arrive at Honmaru and begin to attack Heihachi and Kazuya - and in order to escape, Kazuya thrusts Heihachi into the swarm of Jacks. A great explosion destroys Honmaru, and a man watching from afar reports, \"Heihachi Mishima is dead.\" While many presume the death of Heihachi Mishima will end the reign of Mishima Zaibatsu, an announcement is made for the fifth King of Iron Fist Tournament, with an unknown replacement to Heihachi leading the organization. The fight begins once again.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3753","developer":"Namco","coverName":"Tekken 5 (USA)","players":"2","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.48,"count":276}},{"id":"grand-theft-auto-iii","title":"Grand Theft Auto III","year":2001,"genres":["Sandbox"],"description":"Grand Theft Auto III is a 2001 action-adventure game developed by DMA Design and published by Rockstar Games. It was the first 3D game in the Grand Theft Auto series. Set in Liberty City, loosely based on New York City, the story follows Claude, a silent protagonist who becomes entangled in a world of crime, drugs, gang warfare and corruption. The game is played from a third-person perspective and its world is navigated on foot or by vehicle. Its open world design lets players freely roam Liberty City.\n\nDevelopment was shared between DMA Design, based in Edinburgh, and Rockstar, based in New York City. Development involved transforming popular Grand Theft Auto elements into a fully 3D world for the first time. The game was delayed following the September 11 attacks to allow the team to change references and gameplay deemed inappropriate. Grand Theft Auto III was released in October 2001 for the PlayStation 2, in May 2002 for Windows, and in November 2003 for the Xbox. Mobile ports were released for the tenth anniversary in 2011, followed by a remastered version for the twentieth in 2021.\n\nGrand Theft Auto III received acclaim for its concept, gameplay, sound design, and visual fidelity, but generated controversies for its violence and sex. It received year-end accolades from several gaming publications, and it is considered a landmark game in the open world concept, one of the most significant games of the sixth generation of consoles, and among the best video games. It was the best-selling video game of 2001 and among the best-selling PlayStation 2 games with over 11.6 million copies sold; it has sold over 14.5 million copies overall. The game was followed by Grand Theft Auto: Vice City (2002) and two prequels, Advance (2004) and Liberty City Stories (2005).","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4165","developer":"Rockstar North","coverName":"Grand Theft Auto III (USA)","players":"1","publisher":"Rockstar Games","esrb":"M - Mature","rating":{"score":4.37,"count":274}},{"id":"hack-fragment","title":".hack//fragment","year":2005,"genres":["Action","Adventure","MMO","RPG"],"description":".hack//frägment is a multiplayer online game based on the fictional MMORPG, The World. It was released only in Japan on November 23, 2005 and online service ended on January 18, 2007, after being extended two months because of its popularity. Famitsu Weekly gave .hack//frägment a cumulative score of 29 out of 40 over four reviews, much like its reviews of the main series. Designer Hiroshi Matsuyama described the game as a way to see how players would react to online play. The game uses the same game engine as the .hack video game series and thus, its gameplay is identical, with the exception of online mode. Players explore areas and fight monsters in real time. A major difference is that during online play, the action does not pause when the menu is opened. Players may still use the skill \"Data Drain\" to weaken monsters and collect rare items. The user interface and control scheme are otherwise unchanged.\n\nPlayers may create their characters based on a number of preset body shapes and color schemes and may choose a class (such as Wavemaster or Twin Blade) and character name. In online mode, players may enter a lobby and search for a maximum of two other players to join them on an adventure. The game includes an expanded communication interface that allows players to chat, send e-mail, post to an in-game Bulletin Board System, and receive server news updates. It is possible to establish ad-hoc chat rooms separate from the public-access ones. Guilds are permanent, exclusive chat rooms for members. In offline mode, players may level up, obtain items, and learn new skills as one of their online mode characters without the need for an Internet connection. Players may invite characters from the .hack games, .hack//Sign, and .hack//Legend of the Twilight into their party. The \"story mode\" of .hack//frägment is identical to that of the .hack games, with the player's created character replacing Kite. While offline, players may use a PC utility called \"HackServer\" to create areas and dungeons and release them online. The creators of the most popular areas are given the ability to add strong monsters for players to defeat.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/20772","developer":"Cyberconnect2","coverName":"","players":"3","publisher":"Bandai","esrb":"Not Rated","rating":{"score":3.47,"count":271}},{"id":"jak-and-daxter-the-precursor-legacy","title":"Jak and Daxter: The Precursor Legacy","year":2001,"genres":["Action","Platformer"],"description":"Enter a new world of magic and adventure, exploration and discovery where enormous vistas and exotic characters lead you to places beyond your imagination. Test your wits and your skills as you embark on a journey to reverse your best friend's transformation into a furry... Ottsel? ...even as he entangles you in his amusing antics. Discover Precursor secrets, dazzling artifacts, and a sinister plot by twisted minds wanting to unleash Dark Eco, the most dangerous element in the universe.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4865","developer":"Naughty Dog","coverName":"Jak and Daxter - The Precursor Legacy (USA) (Cingular Wireless Demo)","players":"1","publisher":"Sony Computer Entertainment","esrb":"E - Everyone","rating":{"score":4.32,"count":269}},{"id":"metal-gear-solid-3-subsistence","title":"Metal Gear Solid 3: Subsistence","year":2005,"genres":["Shooter","Stealth"],"description":"Metal Gear Solid 3: Subsistence continues the Metal Gear Solid series tradition of follow-up enhanced, international version releases.\nSubsistence's online multiplayer component, titled Metal Gear Online, consists of five tournament-style game modes, each with a capacity of up to eight players. This mode pits players, each playing as a generic soldier against each other in deathmatch battles and variations of capture the flag, using stages, items, maneuvers, and units (such as the KGB, GRU or Ocelot Unit) from the main game.\n\nDisc 1 Subsistence is the original Metal Gear Solid 3 with new features such as improved camera controls.\nDisc 2 Persistence includes the Metal Gear Online and Duel mode which is boss fights.\nDisc 3 Existence is cinematics","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/6378","developer":"Konami Computer Entertainment Japan","coverName":"Metal Gear Solid 3 - Subsistence (USA) (En,Es) (Disc 1) (Subsistence)","players":"8","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.76,"count":254}},{"id":"bully","title":"Bully","year":2006,"genres":["Action"],"description":"The Rockstar tradition of ground-breaking, original gameplay and humorous tongue-in-cheek storytelling invades an entirely new setting: the schoolyard. \n\nAs a mischievous schoolboy, you’ll stand up to bullies, get picked on by teachers, play pranks, win or lose the girl, and ultimately learn to navigate the obstacles of the worst school around, Bullworth Academy - a corrupt and crumbling prep school with an uptight facade. \n\nThe story follows Jimmy Hopkins, a teenager who’s been expelled from every school he’s ever attended. Left to fend for himself after his mother abandons him at Bullworth to go on her fifth honeymoon, Jimmy has a whole year at Bullworth ahead of him, working his way up the social ladder of this demented institution of supposed learning, standing up for what he thinks is right and taking on the liars, cheats and snobs who are the most popular members of the student body and faculty. If Jimmy can survive the school year and outsmart his rivals, he could rule the school.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3931","developer":"Rockstar Vancouver","coverName":"Bully (USA)","players":"1","publisher":"Rockstar Games","esrb":"T - Teen","rating":{"score":4.41,"count":248}},{"id":"devil-may-cry","title":"Devil May Cry","year":2001,"genres":["Action"],"description":"Half Man. Half Demon. Pure Vengeance. Legends tell of two millennia ago, in the darkest reaches of Hell, a demon swordsman named Sparda awoke to justice and a rebelled against the devil to wage a one-man war to save the human world from damnation. Now, 2000 years later, a dark figure named Dante finds clues that the Devil is rallying to rise up again against mankind. Who was Sparda and how does Dante fit into this gothic puzzle? Deep within Dante's blood lies the power of ancient demons and the key to defeat the hordes of the dark realm. Somewhere between a man and a demon lies our only chance for salvation. If he succeeds, even the Devil May Cry.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/15","developer":"Capcom","coverName":"Devil May Cry (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.23,"count":239}},{"id":"dragon-quest-viii-journey-of-the-cursed-king","title":"Dragon Quest VIII: Journey of the Cursed King","year":2006,"genres":["RPG"],"description":"A mysterious jester. A forbidden scepter. A fiendish curse. A once idyllic kingdom lies entangled in a web of enchanted vines, its king and princess hideously transformed, its castle and subjects frozen in time. Only one person has survived this horror unscathed: you!\n\nOnly you can save your king and country by lifting the shadow of the evil jester's curse... But it won't be easy. An epic tale of friendship, bravery, and adventure awaits you on the grassy fields, snow-capped mountains, and restless seas of Dragon Quest VIII!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7226","developer":"Level-5","coverName":"Dragon Quest VIII - Journey of the Cursed King (USA)","players":"1","publisher":"Square Enix","esrb":"T - Teen","rating":{"score":4.39,"count":237}},{"id":"silent-hill-3","title":"Silent Hill 3","year":2003,"genres":["Action","Horror"],"description":"Silent Hill 3 continues the series' trademark brand of psychological horror and terrifying gameplay. As a teenage girl named Heather, you'll explore and unravel the mysterious connection between the godforsaken town and her inner fears. Along the way, you'll encounter many strange characters you're not sure are trustworthy. Silent Hill 3 also features enhanced graphical detail, a more complex storyline, new items and weapons, and even more grotesque monsters than the previous games. Step into this world of nightmares and fight to survive.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4794","developer":"Team Silent","coverName":"Silent Hill 3 (USA) (En,Ja,Fr,De,Es,It,Ko)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.4,"count":234}},{"id":"shin-megami-tensei-persona-3-fes","title":"Shin Megami Tensei: Persona 3 FES","year":2008,"genres":["RPG"],"description":"Lead a group of high school students with a dangerous extracurricular activity: exploring the mysterious tower Tartarus and fighting the sinister Shadows during the Dark Hour, a frozen span of time imperceptible to all but a select few. However, the end of their quest is no longer the end of the story--witness for the first time the aftermath of the final battle and the students' struggle to find meaning in their new lives.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9327","developer":"Atlus","coverName":"Shin Megami Tensei - Persona 3 FES (USA)","players":"1","publisher":"Atlus","esrb":"M - Mature","rating":{"score":4.58,"count":233}},{"id":"the-simpsons-hit-run","title":"The Simpsons: Hit & Run","year":2003,"genres":["Action","Platformer","Racing","Sandbox"],"description":"Strange wasp-shaped spy cameras, shady black vans lingering about, and a brand new flavor of Buzz Cola that everyone seems a bit too excited about. What could it all mean? In this timeless action-adventure game, you can work to uncover the conspiracy taking place in Springfield while playing as these beloved characters.\n\nThe Simpsons: Hit & Run features seven levels over three separate maps, each with missions and a sub-plot. The player can control one specific character in each level: Homer Simpson, Bart Simpson, Lisa Simpson, Marge Simpson, and Apu Nahasapeemapetilon. The game's driving missions are also similar to those of Grand Theft Auto III. The game has a sandbox-style format that emphasises driving, and the player controls their character from a third-person view. The character can perform certain acts of violence, punching, such as attacking pedestrians, blowing up vehicles, and destroying the environment.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5420","developer":"Radical Entertainment","coverName":"Simpsons, The - Hit _ Run (USA)","players":"1","publisher":"Vivendi Universal Games","esrb":"T - Teen","rating":{"score":4.36,"count":230}},{"id":"def-jam-fight-for-ny","title":"Def Jam: Fight for NY","year":2004,"genres":["Fighting"],"description":"Survive the gritty reality of the urban underworld in Def Jam: Fight for NY, the only fighting game featuring five intense fighting styles, hardcore hip hop music, more than 40 hip hop artists and celebrities, and urban venues. Develop your fighting skills, get down with a crew, and battle for control of the underworld. A new fighting engine challenges you to master multiple fighting disciplines, take advantage of interactive environments, and utilize dozens of weapons to make a name for yourself. It’s going to take more than 90 fights in 20 venues to win control of the streets.\n\nLook for appearances by Busta Rymes, Carmen Electra, Fat Joe, Flava Flav, Freeway, Ghostface, Ice-T, Joe Budden, Kimora Lee Simmons, Lil’ Kim, Ludacris, Method Man, Redman, Sean Paul, Slick Rick, Snoop Dogg, Xzibit, and many more.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7205","developer":"AKI","coverName":"Def Jam - Fight for NY (USA)","players":"4","publisher":"Electronic Arts","esrb":"M - Mature","rating":{"score":4.46,"count":226}},{"id":"final-fantasy-xii","title":"Final Fantasy XII","year":2006,"genres":["RPG"],"description":"The game takes place in the fictional location of Ivalice, where the empires of Archadia and Rozarria are waging an endless war. Dalmasca, a small kingdom, is caught between the warring nations. When Dalmasca becomes annexed by Archadia, its princess, Ashe, creates a resistance movement. During the struggle, she meets Vaan, a young adventurer who dreams of commanding an airship. They are quickly joined by a band of allies; together, they rally against the tyranny of the Archadian Empire.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/87","developer":"Square Enix","coverName":"Final Fantasy XII (USA)","players":"1","publisher":"Square Enix","esrb":"T - Teen","rating":{"score":4.32,"count":220}},{"id":"metal-gear-solid-2-substance","title":"Metal Gear Solid 2: Substance","year":2002,"genres":["Action","Adventure","Shooter","Stealth"],"description":"Solid Snake returns in Metal Gear Solid 2: Substance, the expanded edition of Metal Gear Solid 2: Sons Of Liberty with all-new game modes, hidden characters and storylines. Top-secret weapons technology is being mysteriously transported under cover of an oil tanker to an unknown destination. Armed with an arsenal of new weapons, supplies and stealth maneuvers, it's up to Snake to infiltrate the transport and keep this deadly weapon of mass destruction from falling into the wrong hands!\nSUBSTANTIAL FEATURES:\n• 350+ VR missions and 150+ alternative missions... Substance Exclusive!\n• Play through 5 new Snake Tales involving Solid Snake... Substance Exclusive!\n• Unlock new playable characters and game modes... Substance Exclusive!\n• Contains the entire Metal Gear Solid 2: Sons Of Liberty game plus the debut of the Casting Theater and Boss Survival Mode... Substance Exclusive!\n• Utilize stealth and infiltration methods, such as diving somersaults, hanging from ledges and using disguises\n• Powerful musical score composed by Harry Gregson-Williams (Armageddon, The Rock)","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7367","developer":"Konami Computer Entertainment Japan","coverName":"Metal Gear Solid 2 - Substance (USA)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.59,"count":219}},{"id":"kingdom-hearts-ii","title":"Kingdom Hearts II","year":2006,"genres":["Action","RPG"],"description":"After last being seen chasing Pluto across a large plain at the end of Kingdom Hearts; Sora, Donald Duck, Goofy, and Jiminy Cricket wake up in a mysterious white room a year older and with only a note scribbled into Jiminy's Journal \"Thank Namine.\" With only that clue to go on, the foursome learn that Disney worlds both past and new are under threat from a new terror; a group of figures in black robes calling themselves Organization XIII, who are accompanied by an army Nobodies and are releasing Heartless to cause mayhem for an unknown goal. With Riku still missing, King Mickey traveling incognito, and the worlds at threat once more; Sora, Donald, and Goofy set out to find their friends, uncover what the Organization are planning, save the universe once again, and maybe learn why the Organization keeps referring to Sora as Roxas.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/1903","developer":"Square Enix","coverName":"Kingdom Hearts II (USA)","players":"1","publisher":"Square Enix","esrb":"E10+ - Everyone 10+","rating":{"score":4.6,"count":217}},{"id":"crash-bandicoot-the-wrath-of-cortex","title":"Crash Bandicoot: The Wrath of Cortex","year":2001,"genres":["Action","Platformer"],"description":"Crash Bandicoot: The Wrath of Cortex is the first Crash Bandicoot game for a system other than the original PlayStation. The story is set some time after Warped: Dr. Cortex wants revenge after being defeated by Crash (again). For this purpose, he creates Crunch, a super-bandicoot who can destroy everything that crosses his way. So Crash needs to defeat Crunch (and in the end, Dr. Cortex).\n\nThe game is a typical jump and run, with some other action passages, like air combat and a sequence where Crash is trapped inside a giant sphere rolling around in some sort of rollercoaster. All graphics are in 3D, and the sound is typical for cartoon games like this. The whole game is pretty straightforward in design, getting stuck on a puzzle is not really possible.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/8322","developer":"Traveller's Tales (UK)","coverName":"Crash Bandicoot - The Wrath of Cortex (USA) (v1.00)","players":"1","publisher":"Konami","esrb":"E - Everyone","rating":{"score":4.0,"count":217}},{"id":"need-for-speed-underground-2","title":"Need for Speed: Underground 2","year":2004,"genres":["Racing"],"description":"Need For Speed Underground 2 takes place in Bayview after the events of Need for Speed: Underground. The prologue begins with the player driving in a Nissan Skyline R34 in Olympic City (though the racing scenes are actually in Bayview), the setting of NFS:UG. He then receives a race challenge from a rather ominous personality who offers him a spot on his crew, but \"won't take 'no' for an answer.\" The player races off — despite Samantha's warnings — only to be ambushed by a mysterious driver in a rage that totals his Skyline. The driver, who has a unique scythe tattoo, makes a call confirming the accident, and the flashback fades out.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4813","developer":"Electronic Arts Black Box","coverName":"Need for Speed - Underground 2 (USA)","players":"6","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.44,"count":216}},{"id":"gran-turismo-3-a-spec","title":"Gran Turismo 3: A-Spec","year":2001,"genres":["Racing"],"description":"The third game in the Gran Turismo series of racing games for PlayStation and PlayStation 2.\n\nThis time with an even more realistic driving experience. Lighting now has an effect on the game, such as buildings blocking the sunlight. There are now smoke effects caused by skidding. Now there is even heat rising from the road.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7285","developer":"Polyphony Digital","coverName":"Gran Turismo 3 - A-Spec (USA) (v1.00)","players":"6","publisher":"Sony Computer Entertainment","esrb":"E - Everyone","rating":{"score":4.4,"count":215}},{"id":"black","title":"Black","year":2006,"genres":["Shooter"],"description":"Sgt. J. Keller is a Black Op and he has just failed his operation - badly. He has been incarcerated and is interrogated to reveal his mission and to find out what went wrong. The player goes through Keller's failed operation in eight areas, wasting enemy soldiers and trying to stay alive. There are primary and secondary objectives, such as reaching a rendezvous point and gathering intel.\n\nBlack is a traditional first-person shooter with variety of weapons and interactive scenery - interactive meaning destructible in this case. Enemy soldiers can be killed by destroying a nearby fuel tank for example, and weak shelter, like a wooden fence, can be shot to pieces in order to expose the enemy.\n\nThe game can be played in four difficulty levels: easy, normal, hard, and black ops. In easy mode, only the primary objective is required. In normal and hard modes, some of the secondary objectives are required. In black ops mode - unlocked after completing the game on hard - all objectives must be reached. New weapons are also unlocked after finishing a level.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3942","developer":"Criterion Games","coverName":"Black (USA)","players":"1","publisher":"Electronic Arts","esrb":"M - Mature","rating":{"score":4.24,"count":214}},{"id":"ico","title":"ICO","year":2001,"genres":["Adventure","Puzzle"],"description":"The game's main protagonist is Ico, a young boy with a pair of horns on his head—considered a bad omen by his village. As part of the village's tradition, he is taken by a group of warriors to a castle surrounded by water and locked inside one of the sarcophagi in a crypt. Some time after the warriors depart, a tremor runs through the castle, and Ico is able to take advantage of it to escape his confines. As he searches the castle, he comes across Yorda, a captive girl who speaks in an unknown language. Ico helps Yorda escape, but finds that she is hunted by shadow-like creatures (the souls of other horned children sacrificed to the fortress) that attempt to drag her body into the portals from which they emerged. Though Ico cannot be harmed by the shadows and is able to drive them away from Yorda, he finds he cannot defeat the enemies with his simple weapons. The pair make their way through the abandoned castle, eventually arriving at the bridge leading to land. As they cross, the Queen, ruler of the fortress and Yorda's mother, appears and tells Yorda that as her daughter she cannot leave the castle. Ico and Yorda attempt to flee, but the Queen destroys part of the bridge in their path; although Yorda tries to save him, Ico falls off the bridge and loses consciousness.\n\nCo-Op Info: This mode is only available after completing the game. One player control Ico while the other controls Yorda. Only player 1 has control of the camera.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/2239","developer":"Team ICO","coverName":"Ico (USA)","players":"2","publisher":"Sony","esrb":"T - Teen","rating":{"score":4.35,"count":208}},{"id":"metal-gear-solid-2-sons-of-liberty","title":"Metal Gear Solid 2: Sons of Liberty","year":2001,"genres":["Action","Adventure","Shooter","Stealth"],"description":"Solid Snake is back in th latest installment of the critically acclaimed series from director, Hideo Kojima. Top-secret weapons technology is being mysteriously transported under cover of an oil tanker to an unknown destination. Armed with an aresnal of new weapons, supplies, and steal manuevers, it's up to Snake to infiltrate the transport and keep this deadly weapon of mass destruction from falling into the wrong hands!\n\nFeatures:\n- New moves and infiltration methods, such as diving summersaults, hanging from ledges, and using disguises.\n- Battle new, highly skilled opponents, as well as some returning vengeful foes.\n- Fully interactive environment where bullets pierce steam pipes, smoke reveals laser beams and wet shoes leave footprints.\n- Powerful musical score composed by Harry Gregson-Williams (Enemy of the State, Armageddon, The Rock).","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3854","developer":"Konami Computer Entertainment Japan","coverName":"Metal Gear Solid 2 - Sons of Liberty (USA)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.51,"count":203}},{"id":"dragon-ball-z-budokai-3","title":"Dragon Ball Z: Budokai 3","year":2004,"genres":["Fighting"],"description":"All the power of DBZ is yours. A Hall of Fame cast of the greatest DBZ, DBGT and DBZ movie characters meet for first time for some of the fastest paced, highest intensity battles ever seen. New abilities include, for the first time on PlayStation 2, the ability to fly at will in a DBZ fighting game. Pummel your foes on the ground and in the air.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7223","developer":"Dimps","coverName":"Dragon Ball Z - Budokai 3 (USA) (Greatest Hits)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":4.26,"count":196}},{"id":"castlevania-curse-of-darkness","title":"Castlevania: Curse of Darkness","year":2005,"genres":["Action","Adventure"],"description":"The Castlevania series gets a new protagonist in the form of Hector, a Devil Forgemaster, in Castlevania: Curse of Darkness. Hector left Dracula's service to lead a normal life, leaving Dracula vulnerable to attack by the Belmonts. Now that Dracula has been vanquished, you must fight back the unholy curse that has spread across Europe. You can use your skills as a Devil Forgemaster to craft familiars that will help you during your travels. Castlevania: Curse of Darkness provides role-playing game and adventure elements, letting your character grow as he progresses through the story. \n \nVengeance Runs Deep...\nFueled by revenge for the murder of his true love, the Devil Forgemaster Hector returns to the ruins of Dracula's castle to punish those he once fought alongside, unaware of the sinister plot that has been orchestrated to lure him home.\n• Master the dark art of Devil Forgery to summon Innocent Devils as allies\n• Level up by destroying the evil creatures of the night\n• Collect evolution crystals to develop and enhance your Innocent Devils\n• Acquire a wide variety of powerful new weapons and abilities\n• Explore the biggest 3D Castlevania world yet!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5922","developer":"Konami","coverName":"Castlevania - Curse of Darkness (USA)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.04,"count":187}},{"id":"ratchet-clank-up-your-arsenal","title":"Ratchet & Clank: Up Your Arsenal","year":2004,"genres":["Action","Platformer","Shooter"],"description":"In Ratchet & Clank: Up Your Arsenal, Ratchet and Clank once again team up for an all-new adventure that combines diverse gameplay with elements of action, exploration, adventure, puzzle-solving, strategy, and role-playing into one experience. Together with the Q-Force, Ratchet and Clank set off to uncover the schemes of the sinister Dr. Nefarious and keep the galaxy safe for organic life. As one of three characters, you can now wield new weapons and gadgets, gain access to an array of vehicles, and master all-new abilities. The game also features both single-player and multiplayer (offline and online) gameplay.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7992","developer":"Insomniac Games","coverName":"Ratchet _ Clank - Up Your Arsenal (USA) (En,Fr,Es)","players":"4","publisher":"Sony Computer Entertainment America","esrb":"T - Teen","rating":{"score":4.45,"count":182}},{"id":"crash-twinsanity","title":"Crash Twinsanity","year":2004,"genres":["Platformer"],"description":"Two purple birds called the Evil Twins form a new threat to Crash's homeworld. Crash has to team up with his arch rival Dr. Neo Cortex to put a stop to this new threat.\n\nCrash Twinsanity is a classic-style Crash platform game, though this time Crash has to work together with Dr. Cortex from time to time. Crash can pick up and throw Dr. Cortex to places he can't reach himself, or use him as a hammer to slap enemies. The consistent conflict between both heroes causes many funny situations.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9646","developer":"Traveller's Tales Oxford Studio","coverName":"Crash Twinsanity (USA) (v1.00)","players":"1","publisher":"Vivendi Universal Games","esrb":"E - Everyone","rating":{"score":4.2,"count":178}},{"id":"ratchet-clank-going-commando","title":"Ratchet & Clank: Going Commando","year":2003,"genres":["Action","Platformer"],"description":"Following their previous adventure, after saving the galaxy and defeating Chairman Drek, Ratchet and Clank become celebrities, though their lives remain otherwise uneventful.\nAfter giving an interview for the holovision show Behind the Hero, the pair suddenly find themselves teleported to the Bogon galaxy by Abercrombie Fizzwidget, the founder and CEO of MegaCorp, the galaxy's largest maker of consumer goods and electronics, who requests Ratchet's help to recover a stolen biological experiment from a masked thief, while offering Clank employment in the company, both of whom agree to the opportunities offered.\nUpon completing an extensive training regime, Ratchet is tasked to travel to a flying laboratory on planet Aranos where the experiment was last seen...","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/13150","developer":"Insomniac Games","coverName":"Ratchet _ Clank - Going Commando (USA) (v1.01)","players":"1","publisher":"Sony Computer Entertainment America","esrb":"T - Teen","rating":{"score":4.38,"count":177}},{"id":"tekken-tag-tournament","title":"Tekken Tag Tournament","year":2000,"genres":["Fighting"],"description":"Forget the fancy full-motion video intros of the past. The cutting-edge gameplay that is promised in the extended intros of fighting games is finally realised in Tekken Tag Tournament. This visually stunning action game contains fully rendered 3-D characters who can execute smoothly animated martial-arts moves. With polygonal characters and texture maps this real, you will end up looking for the coin slot on your PS2.\n\nWith more than 30 characters to fight against or beside, this game allows you to pull off the ultimate human combo: tag-team fighting. By choosing two fighters who have broadly divergent skills, you can increase your threat to the other fighters greatly. Also, switching out fighters can give an overextended partner enough time to rest up his or her stamina for the next tag. See what happens when one partner throws a foe, tags, and the other partner comes in to keep the foe... uh... airborne. Tekken Tag Tournament contains 20 classic characters from other parts of the acclaimed Tekken series, as well as 12 new characters who can be unlocked during gameplay.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3770","developer":"Namco","coverName":"Tekken Tag Tournament (USA) (v1.00)","players":"4","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.41,"count":176}},{"id":"metal-gear-solid-3-snake-eater","title":"Metal Gear Solid 3: Snake Eater","year":2004,"genres":["Shooter","Stealth"],"description":"Set in the 60s and using the Cold War as its inspiration, Metal Gear Solid 3: Snake Eater forces the player to adopt a number of new skills to survive in Snake's new jungle environment. Danger lurks everywhere as Snake explores the beautifully-realised forests, encampments and rivers, with guards patrolling key routes, dangerous animals to contend with, and the uneven terrain and noisy foliage making the silent approaches the Metal Gear hero is famed for virtually impossible.\n\n    Gameplay set in Cold War era 1960's\n    Camoflage System: Use different combinations of uniform and face paints to blend into your environment\n    Food: Capture and eat animals & plants to sustain Snake's health and abilities\n    Close Quarters Combat (CQC): Take on enemies up close and personal with knives and martial arts techniques for silent kills\n    Exclusive content for the PAL version includes:\n    Duel Mode - Battle through the game's Boss Fights independently\n    Demo Theatre - Watch all the cut scenes in sequence\n    European Extreme difficulty level\n    2 New Levels in Snake Vs Monkey Mode\n    New Face Paint and Camoflage Designs not available in US or Japanese versions","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/44","developer":"Konami Computer Entertainment Japan","coverName":"Metal Gear Solid 3 - Snake Eater (USA)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.51,"count":170}},{"id":"dark-cloud","title":"Dark Cloud","year":2001,"genres":["Action","RPG"],"description":"Dark Cloud is set within a fantastic world with two moons called Terra. The world is made of two main continents referred to as the East and West. The eastern continent has a focus on technology, and the civilization is advanced whereas the western continent is less so, and its people prefer to \"live in harmony with nature\".\nOn the western continent are settlements that were sealed away by the Fairy King during the attack by the Dark Genie and where the game primarily takes place; Norune, Matataki, Brownboo, Queens, Muska Lacka and a settlement on one of Terra's moons, Yellow Drops (Brownboo and Yellow Drops being unaffected).","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7201","developer":"Level-5","coverName":"Dark Cloud (USA)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.04,"count":170}},{"id":"resident-evil-code-veronica-x","title":"Resident Evil: Code: Veronica X","year":2001,"genres":["Action","Horror"],"description":"Resident Evil Code: Veronica X (Biohazard Code: Veronica ~Complete Edition~in Japan) is an updated version of the original Resident Evil Code: Veronica released for the PlayStation 2 and Sega Dreamcast in 2001 and the Nintendo GameCube in 2003.\n\nCode: Veronica X is almost identical to the original in terms of gameplay, the only major difference being having to find a serum for Claire, if she is poisoned in the Nosferatu battle, after she is rescued with Chris in the mansion, where they later fight Alexia for the first time. It also features nine minutes of additional cut scenes spliced into the main game, as well as mild graphical changes.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4796","developer":"Capcom","coverName":"Resident Evil - Code - Veronica X (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.28,"count":169}},{"id":"shin-megami-tensei-persona-4","title":"Shin Megami Tensei: Persona 4","year":2008,"genres":["RPG"],"description":"Shortly after an urban youth begins a year-long stay in the countryside town of Inaba, the rural town's peace is shattered by a horrific murder that leaves no clues or suspects. As the lone incident develops into a series of bizarre crimes, he discovers that only he and his friends have the power to solve the baffling case, bring those responsible to justice, and restore harmony to his new home.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9328","developer":"Atlus","coverName":"Shin Megami Tensei - Persona 4 (USA)","players":"1","publisher":"Square Enix","esrb":"M - Mature","rating":{"score":4.56,"count":167}},{"id":"sly-cooper-and-the-thievius-raccoonus","title":"Sly Cooper and the Thievius Raccoonus","year":2002,"genres":["Platformer","Stealth"],"description":"Sly Cooper is the latest in a long line of master thieves. When he was a kit, a gang called the Fiendish Five killed his family and divided up their book on the art of thieving: the Thievius Raccoonus. Sly must defeat all the members of the gang to recover the book while evading Carmelita Fox, a police officer chasing him around the world to apprehend him.\n\nThis game is divided into five worlds, each themed around a particular part of the world and the villain headquartered there. Most worlds are structured as a central hub with entrances to numerous individual levels. Each of the levels has a primary goals which earns you a key. You must collect all the keys in the world to fight the world's boss.\n\nMany of the levels have a platformer structure. The objective of these worlds is to reach the location of the key. There are substantial stealth elements here as you must dodge searchlights and trips lasers which set off alarms and avoid alerting guards. In addition to the main objective, there are clue bottles to find. Finding all the clues in a level allows you to open a safe with a page from the Thievius Raccoonus which grants a new ability of some sort. After getting this, there is also a master thief sprint where you must get from the start of a level to the exit within a time limit.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9815","developer":"Sucker Punch","coverName":"Sly Cooper and the Thievius Raccoonus (USA)","players":"1","publisher":"Sony Computer Entertainment","esrb":"E - Everyone","rating":{"score":4.28,"count":167}},{"id":"god-hand","title":"God Hand","year":2006,"genres":["Beat 'em up"],"description":"GIVE DANGER A HAND!\n\n* Defy the Laws of Physics\n* Gut Pounding Action\n* Unmatched Punching Power\n\nYou play a larger than life hero who has been given the power of the GODHAND. From cool moves, to the twisted painful reactions of enemies, crushing the bad guys has never been more satisfying","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/25","developer":"Clover Studio","coverName":"God Hand (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.17,"count":165}},{"id":"soulcalibur-iii","title":"SoulCalibur III","year":2005,"genres":["Fighting"],"description":"Soulcalibur III is a fighting video game produced by Namco as a sequel to Soulcalibur II and the fourth installment in the Soulcalibur series. It was originally released for the PlayStation 2 in 2005. An improved arcade version, Soulcalibur III: Arcade Edition, was released in 2006. It was the last Soulcalibur game to receive an arcade version, as IV onwards did not have an arcade release. It is the second in the Soulcalibur series’ 1590 A.D. trilogy games, between II and IV.\n\nThe game includes new modes such as Tales of Souls, an interactive story-driven mode comparable to Edge Master Mode from Soul Edge; Character Creation, in which players can create custom characters from 13 total occupations, with multiple weapons and fighting styles; and Chronicles of the Sword, a real-time-play mode that allows players to take their created souls through adventures of their own. The game also has the largest character roster — 24 characters playable in Tales of Souls mode and an additional 18 playable in all other modes — and largest battle stage selection in Soul series history.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4788","developer":"Project Soul","coverName":"Soulcalibur III (USA)","players":"2","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.3,"count":165}},{"id":"midnight-club-3-dub-edition-remix","title":"Midnight Club 3: DUB Edition Remix","year":2006,"genres":["Racing"],"description":"Midnight Club 3: DUB Edition Remix is an update to Midnight Club 3: DUB Edition. It is available as a Greatest Hits release on PlayStation 2. It was released on March 12, 2006 or exactly eleven months after the original version's release. It was released on December 19, 2012 on PlayStation Network. However, it was removed after a passing of time due to licensing issues.\n\nThe game features all of the cities, vehicles, and music from Midnight Club 3: DUB Edition. This version of the game also allows the player to import the Midnight Club 3: DUB Edition data on their memory card to Midnight Club 3: DUB Edition Remix to make up for lost progress, thus saving the player from starting all over again.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/24524","developer":"Rockstar San Diego","coverName":"Midnight Club 3 - DUB Edition Remix (USA)","players":"2","publisher":"Rockstar Games","esrb":"E10+ - Everyone 10+","rating":{"score":4.52,"count":164}},{"id":"jak-ii","title":"Jak II","year":2003,"genres":["Action","Platformer"],"description":"The game begins with Jak and Daxter, the protagonists, and Samos, their guardian, watching as Keira, Samos’ daughter and Jak’s love interest, demonstrate the Rift Rider and Precursor Rift Gate that they found in the previous game. When activated, the Rift opens a portal, and a large ominous atmosphere and a monster appear. Jak launches the Rider through the gate, past the monster. Jak and Daxter, separated from Keira and Samos, arrive in the segregated dystopia known as Haven City. They are separated on arrival, and Jak is captured by the city's Krimzon Guard. While Jak is imprisoned, he undergoes experiments with Dark Eco under the command of the city's leader: Baron Praxis. Jak, along with previous prisoners in the city jail, were experimented on for Operation: Dark Warrior, a project that consisted of injecting prisoners with dark eco in order to give them super-human abilities to be used in Haven City's war against animalistic creatures called Metal Heads. Jak, the only prisoner to survive the experiments, is altered mentally and physically, turning him (temporarily under random and controlled spasms) into a deadly monster.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4867","developer":"Naughty Dog","coverName":"Jak II (USA) (En,Ja,Fr,De,Es,It,Ko) (v1.00)","players":"1","publisher":"Sony Computer Entertainment","esrb":"T - Teen","rating":{"score":4.19,"count":162}},{"id":"tekken-4","title":"Tekken 4","year":2002,"genres":["Fighting"],"description":"Tekken 4 picks up two years after Tekken 3. Heihachi and his scientists have captured samples of Ogre's blood and tissue to splice with Heihachi's genome and make him immortal. The experiment fails, since Heihachi lacks the necessary Devil Gene. Not willing to give up, Heihachi searches for his grandson, Jin Kazama, who does possess the Devil Gene, with Heihachi learning that the body of his son, Kazuya (who also has the Devil Gene and died twenty years ago) is stored in the labs of the Mishima Zaibatsu's main business rival, G Corporation.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4771","developer":"Namco","coverName":"Tekken 4 (USA)","players":"2","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.2,"count":160}},{"id":"ace-combat-04-shattered-skies","title":"Ace Combat 04: Shattered Skies","year":2001,"genres":["Flight","Shooter"],"description":"The continent of Usea was struck by an asteroid, causing the death of half a million people. The neighboring Erusea used this as an opportunity to invade and occupy almost all of Usea. Based on its eastern coast, the Independent States Allied Forces (ISAF) try to regain ground an engage the Eruseans in aerial battles. An elite pilot using the codename Mobius 1 is sent on a number of missions to fight Eruseans and help ISAF to win the war. While performing those missions, Mobius 1 begins to learn about the impact war has on civilians, and the pilots of the opposing side.\n\nAce Combat 04: Shattered Skies is an aerial combat simulation. It allows the player to participate in semi-realistic dog-fighting with a collection of fighter jets, including the F-22 Raptor, F-16 Fighting Falcon, F-117 Nighthawk, U-2 Dragon Lady, C-130 Hercules and SR-71 Blackbird. Eighteen missions will take the player from search-and-destroy buildings to one-on-one and all-on-all dog-fighting. Along the way it becomes possible to upgrade the fighter with defense systems, deadly weapons, and other accessories.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9620","developer":"Namco","coverName":"Ace Combat 04 - Shattered Skies (USA)","players":"2","publisher":"Namco","esrb":"E - Everyone","rating":{"score":4.1,"count":159}},{"id":"need-for-speed-underground","title":"Need for Speed: Underground","year":2003,"genres":["Racing"],"description":"Need For Speed: Underground is the seventh game in the long running Need For Speed racing series. Underground revolves around illegal nighttime street racing with heavily modified import cars and has been greatly influenced by the movie \"The Fast And The Furious\" and its sequel.. Players get the chance to build their own racing machine almost from ground up, with hundreds or real licensed parts and lots of licensed cars, including the Mazda RX-7 and the Nissan Skyline GT-R. The game also features over 100 single player races and a hiphop/hardrock soundtrack including artists such as Mystikal, Rob Zombie and The Crystal Method.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5396","developer":"Electronic Arts Black Box","coverName":"Need for Speed - Underground (USA)","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.15,"count":157}},{"id":"fatal-frame","title":"Fatal Frame","year":2001,"genres":["Action","Horror"],"description":"Miku Hinasaki is young girl with a strange sixth sense. Her brother, Mafuyu, and his mentor, Junsei Takamine, went to investigate a mansion that once was inhabited by a powerful landowner who had absolute control over the area. Unfortunately, they never returned from their investigation. Miku enters the mansion, armed with only an antique camera given to her by her deceased mother, to try to find her brother.\n\nWhile inside the mansion, Miku will encounter ghosts and other spiritual apparitions. In order to overcome these spirits and survive, she must use the magical camera to capture the ghosts on film, thereby trapping them forever. Ghosts range from invisible fragments hidden in scenery, to memories of the past that appear only for a moment before vanishing, to full body apparitions that will attempt to attack and kill Miku.\n\nIn order to defeat an aggressive ghost the Camera Obscura's shot must first be \"charged\" by keeping the ghost centered while it is visible. If Miku snaps a shot while the ghost is attacking or is vulnerable then she will drain even more energy from it, resulting in more spirit points being earned. Points can then be spent to improve her camera's attributes or give it special abilities, like slowing a ghost or pushing it away. The Camera Obscura can also reveal clues and dispel illusions, which Miku will need to utilize to solve puzzles within the mansion.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7250","developer":"Tecmo","coverName":"Fatal Frame (USA)","players":"1","publisher":"Tecmo","esrb":"T - Teen","rating":{"score":4.16,"count":156}},{"id":"tony-hawk-s-pro-skater-3","title":"Tony Hawk's Pro Skater 3","year":2001,"genres":["Sports"],"description":"This game saw the introduction of the revert, a trick that enabled vert combos to be tied together with a manual, by tapping a button when landing in a quarterpipe. This allowed for much longer combos than in the previous two games, where landing in a quarterpipe would finish a combo. The game also added hidden combos. These were variations on standard tricks that could be performed as grab, flip, lip, or grind tricks. For example, double-tapping the kickflip button would, naturally, make the character perform a double kickflip.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4772","developer":"Neversoft Entertainment","coverName":"Tony Hawk's Pro Skater 3 (USA) (Rev 1)","players":"2","publisher":"Activision","esrb":"T - Teen","rating":{"score":4.54,"count":156}},{"id":"katamari-damacy","title":"Katamari Damacy","year":2004,"genres":["Action","Puzzle"],"description":"The King of All Cosmos accidentally destroyed the stars and—having recovered—wants the prince to rebuild them. Unfortunately the prince stands a little less than half a foot tall, so recreating the stars will require some effort. Enter the Katamari, a sphere the prince can push around our world to “roll up” items increasing the Katamari’s size until it’s suitable for the King.\n\nTaking place in stylized versions of Japanese houses, cities, and environs, the prince pushes the Katamari around collecting items which adhere to it. At first, the prince can only pick up smaller items, but as the Katamari grows, the more it can collect. Push pins and paper clips cling to the Katamari increasing its size so it can roll over obstacles and pick up bigger items. Over many levels, the Katamari can eventually pick up people, cars, and other bigger items.\n\nPlayers steer the Katamari from a third-person perspective using the analog sticks on the PS2. A tutorial stage takes the player through the controls and sets up the story as well as introducing a side story about a Japanese girl who can feel the cosmos. Wanting to challenge the prince, the King sets requirements on the Katamari’s size and sets time limits on the level. Bonus missions restore constellations and have their own restrictions. \n\nThe world of Katamari Damacy is brought to life with off-beat animation and a catchy soundtrack. Players can find presents hidden in the levels that contain accessories for the prince. Two players can also battle head-to-head in a Katamari competition.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7317","developer":"Namco","coverName":"Katamari Damacy (USA)","players":"2","publisher":"Namco","esrb":"E - Everyone","rating":{"score":4.43,"count":155}},{"id":"castlevania-lament-of-innocence","title":"Castlevania: Lament of Innocence","year":2003,"genres":["Action","Adventure","Platformer"],"description":"At the dawn of the second millennium, the first Belmont makes the ultimate sacrifice. And the destiny of a bloodline is decided. From the creators of  of Castlevania Symphony of the Night and completely reinvented for its 3D debut on PlayStation 2, Castlevania Lament of Innocence reveals the true origins of the vampire-hunting Belmonts and their tireless quest for Vlad Dracula. A thousand years ago, a legend was indeed born. And the dying hasn't stopped since. \n\nYou play as Leon Belmont, a man skilled in combat, as he struggles to free his betrothed, Sara, from huge monsters. Use combos and special moves on your perilous journey to the evil castle. Immerse yourself in the enhanced graphics and mesmerizing orchestral soundtrack. Discover the true origins of Dracula and the Belmont family in this exciting first episode of the saga.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/11966","developer":"Konami","coverName":"Castlevania - Lament of Innocence (USA)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.11,"count":154}},{"id":"burnout-revenge","title":"Burnout: Revenge","year":2005,"genres":["Racing"],"description":"The sequel to 2004's award-winning Burnout 3: Takedown, Burnout Revenge lets gamers rip through rush hour traffic and lay waste to scores of rubbernecking roadhogs in over-the-top scenes of vehicular mayhem. The game is currently in development by Criterion Games for the PlayStation 2. In addition to tricked out new race, crash and road rage modes, Burnout Revenge takes the series' blistering speed and spectacular destruction to dizzying new heights with an all-new Revenge mode, challenging gamers to battle the clock and unleash their frustrations on rush hour traffic. Race through traffic across urban and countryside locations, driving on the edge of sanity to earn that all important nitros Boost. Single player, multiplayer and online modes mean the roads are never the same twice and only the ultimate drivers will prevail.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5354","developer":"Criterion Software","coverName":"Burnout Revenge (USA)","players":"2","publisher":"Electronic Arts","esrb":"E10+ - Everyone 10+","rating":{"score":4.45,"count":153}},{"id":"gradius-v","title":"Gradius V","year":2004,"genres":["Shooter"],"description":"Long ago, a destructive life form, born from the dark depths of space, was annihilated in an arduous battle with the Gradius Army. However, remnants of the life form’s cells somehow survived. Slowly but surely the cells multiplied and began to form into a new type of cell, Bacterian. Can Vic Viper, a super spatial-temporal fighter from the Gradius Army counter attack in time to save outer space from this evil empire?","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9604","developer":"Treasure","coverName":"Gradius V (USA)","players":"2","publisher":"Konami","esrb":"T - Teen","rating":{"score":4.27,"count":151}},{"id":"prince-of-persia-the-sands-of-time","title":"Prince of Persia: The Sands of Time","year":2003,"genres":["Platformer"],"description":"Prince of Persia: The Sands of Time is a 3D platformer which focuses on acrobatics and agility. Throughout much of the game, the player must attempt to traverse the palace by running across walls, ascending or descending chasms by jumping back and forth between walls, avoiding traps, climbing structures and jumping from platform to platform, making other types of well-timed leaps, solving puzzles, and using discovered objects to progress.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4805","developer":"Ubisoft","coverName":"Prince of Persia - The Sands of Time (USA) (En,Fr,Es)","players":"1","publisher":"Ubisoft","esrb":"T - Teen","rating":{"score":4.4,"count":151}},{"id":"capcom-vs-snk-2-mark-of-the-millennium-2001","title":"Capcom vs. SNK 2: Mark of the Millennium 2001","year":2001,"genres":["Fighting"],"description":"Capcom vs. SNK 2 combines characters and gameplay elements from various Capcom and SNK fighting games, mainly the Street Fighter and The King of Fighters series. Other elements, most noticeably different fighting styles, incorporated elements from other games as well, such as Street Fighter III, Garou: Mark of the Wolves, and the Samurai Shodown series.\n\nChoose from over 44 characters from an arsenal of fighters from the Capcom and SNK fighting universes and customize your fighting style with even more fighting Grooves.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4932","developer":"Capcom","coverName":"Capcom vs. SNK 2 - Mark of the Millennium 2001 (USA)","players":"2","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.45,"count":151}},{"id":"silent-hill-4-the-room","title":"Silent Hill 4: The Room","year":2004,"genres":["Adventure","Horror"],"description":"Henry Townshend is a man living in a small apartment in South Ashfield, a neighboring town of the infamous Silent Hill. On one strange night, Henry has a terrible nightmare, with recurring events: his phone is dead, his windows are sealed, and his neighbors can't hear him. He looks at his door, only to see it is blocked by several thick metal chains. A note is pinned to the door: \"Don't go out!\" It is signed only by a man named Walter. Henry explores his apartment, trying to figure out what is happening, when he spots a giant hole in the wall of his bathroom. Henry goes through the hole, only to find a portal which leads him to alternate dimensions. Hopefully, Henry will find out the truth about his apartment, Room 302, and live.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5387","developer":"Team Silent","coverName":"Silent Hill 4 - The Room (USA) (En,Ja)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.03,"count":150}},{"id":"mortal-kombat-armageddon","title":"Mortal Kombat: Armageddon","year":2006,"genres":["Fighting"],"description":"There have been many powerful warriors throughout the millennia, But ages of Mortal Kombat have begun to tear the fabric of the realms.\nThe critical point has finally been reached, It was foreseen that kombatants would one day grow too powerful and too numerous, If left unchecked, their intensifying kombat would weaken and shatter the realms and bring about the apocalypse. The Elder Gods demanded a safeguard put in place to avoid total destruction... one that would make use of the kombatants' insatiable bloodlust, Like moths to flame, they would be drawn to battle. At the apex of destruction, alliances will be broken, and old hatreds will be revived, At last, it has come to this final battle.\nArmageddon has begun.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4223","developer":"Midway Games","coverName":"Mortal Kombat - Armageddon (USA) (Premium Edition)","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":4.11,"count":149}},{"id":"marvel-vs-capcom-2-new-age-of-heroes","title":"Marvel vs. Capcom 2: New Age of Heroes","year":2003,"genres":["Fighting"],"description":"Two powerful universes collide. The game mixes characters from Capcom games with superheroes from the Marvel Universe, creating a total of 56 fighters. Assemble a team of your favorite heroes and villains for intense three-on-three tag-team matches. Each character type has an array of special attributes and, with the right team combination, you can pull off amazing super combos and special moves.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/157531","developer":"Capcom","coverName":"Marvel vs. Capcom 2 - New Age of Heroes (USA)","players":"2","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.3,"count":149}},{"id":"grand-theft-auto-vice-city-stories","title":"Grand Theft Auto: Vice City Stories","year":2007,"genres":["Action","Adventure"],"description":"Vice City Stories is a prequel to Grand Theft Auto: Vice City (2 years earlier) and it is the sequel to Grand Theft Auto: Liberty City Stories. Set in 1984, players take on the role of Vic Vance, an army soldier who loves his country, family, and himself. One bad decision turns everything around and he is kicked onto the streets of a tough city. He has to build an empire to survive, or be left to die. Together with his brother Lance, a drug addict, the siblings try to take over Vice City.\n\nJust like other GTA titles, gameplay consists of third-person shooting and driving sequences in an open environment. You will meet new enemies and gangs, and old foes. The missions require you to kill with a selection of weapons, steal vehicles such as a car, a boat, or a plane, rob to make it big, or just to have fun.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7289","developer":"Rockstar North","coverName":"Grand Theft Auto - Vice City Stories (USA)","players":"1","publisher":"Rockstar Games","esrb":"M - Mature","rating":{"score":4.11,"count":145}},{"id":"grand-theft-auto-liberty-city-stories","title":"Grand Theft Auto: Liberty City Stories","year":2006,"genres":["Racing","Sandbox","Shooter"],"description":"There are a million stories in Liberty City. This one changes everything. Once a trusted wise guy in the Leone crime family, Toni Cipriani was forced into hiding after killing a made man. Now he's back and it's time for things to be put right.\n\nThe streets of Liberty City are in turmoil. Warring mafiosi vie for control as the town begins to self-destruct under waves of political corruption, organized crime, drug trafficking and union strikes. No one can be trusted as Toni tries to clean up the mess of the city's chaotic underworld. Deranged hit men, morally depraved tycoons, cynical politicians and his own mother stand in his way as Toni tries to bring the city under Leone control.\n\nForced to fight for his life in an odyssey that will shake Liberty City to its foundations, Toni must use any means necessary to secure his place in the leadership of the Leone family in a town up for grabs.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7288","developer":"Rockstar North","coverName":"Grand Theft Auto - Liberty City Stories (USA)","players":"1","publisher":"Rockstar Games","esrb":"M - Mature","rating":{"score":3.98,"count":145}},{"id":"onimusha-warlords","title":"Onimusha: Warlords","year":2001,"genres":["Action","Horror"],"description":"Onimusha: Warlords is set in 16th century Japan during the period of the civil war dominated by Nobunaga Oda. You play Samanosuke Akechi, who dies during an attempt to stop the kidnapping of young princess Yuki, the sister to Yoshitatsu Saito. However, Akechi is given another chance at life, and is handed the gauntlet of the Ogres. \n\nWith this new power Samanosuke must fight through the monster-filled halls of Inabayama Castle. As monsters are defeated, their souls are absorbed by the gauntlet, increasing its power. Some souls restore Samanosuke's health and magic, while others can be used to power up weapons, armor, and items. Powering up weapons will increase their damage and the strength of their associated magic, and is also required to pass by special locks throughout the castle. Items will need to be found in one part of the castle to unlock doors or otherwise bypass obstacles elsewhere in the castle, and sometimes the player will take control of Samanosuke's companion Kaede while Samanosuke is incapacitated in some way. Kaede can reach some locations that are beyond Samanosuke as well as pick locks and throw kunai, but she can not absorb souls or open any lock intended for the wearer of the Ogre gauntlet.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/8780","developer":"Capcom","coverName":"Onimusha - Warlords (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.16,"count":145}},{"id":"twisted-metal-black","title":"Twisted Metal: Black","year":2001,"genres":["Racing","Shooter"],"description":"Twisted Metal: Black is a demolition derby that permits the usage of ballistic projectiles. Players choose a vehicle and an arena—or a series of arenas in the story mode—to engage in battle with opposing drivers. A variety of weapons and upgrades are obtainable by pick-ups scattered throughout the stage. The objective of the game is to be the last one standing.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7922","developer":"Incognito Entertainment","coverName":"Twisted Metal - Black (USA)","players":"4","publisher":"Sony Computer Entertainment Europe","esrb":"M - Mature","rating":{"score":3.96,"count":144}},{"id":"hack-infection-part-1","title":".hack//Infection: Part 1","year":2002,"genres":["Action","RPG"],"description":".hack//Infection is the first in a four part game series. It's a single player adventure / rpg that \"simulates\" an MMORPG (EverQuest, Ultima On-line) that has you playing the character Kite. You can get member addresses of other character and attempt to call them to in game to see if they are on-line to join you in a quest. Like standard MMORPG games, it has a LOT of side quests, lots of weapons and armor, a trading system for equipment among other character and the ability to move between different servers. You also have message boards and e-mail to communicate with other \"players\". Once you beat the game, you can still continue to play and level up your character and your character can transfer to the second game .hack//Mutation (May 2003).\n\nYour friend talks you in to trying \"The WORLD\", the most successful on-line rpg in computer history. During your first adventure in the game with your friend (showing you the ropes) you come across a strange girl being chased by a weird monster, a strange incident causes your friend to go into a coma after the attack of unknown / hacked monster and you end up with this book that upgrades your character with an unusual gauntlet that allows you to hack in the game. Your quest starts out to find out what caused your friend to go in to a coma. This involves adventuring after sightings of the strange girl and hacking in to sealed levels. There also seems to be corrupted levels and something going on that the CC Corporation (owner of “The World) is trying to hide.\n\n.hack//Infection is part of Ban Dai's dot hack project that first starts with the Anime DVD series (.hack//Sign). The game series takes place after the events of the \"Key of Twilight\" and focus's on the \"Book of Twlight\". Each game in the series has a DVD episode of the .hack//Liminality anime series that show the events going on in the real world around the same time as the game.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7218","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Bandai","esrb":"T - Teen","rating":{"score":3.78,"count":143}},{"id":"ssx-tricky","title":"SSX Tricky","year":2001,"genres":["Sports"],"description":"SSX Tricky launches you into a world of monster air, intense tracks, and death-defying tricks. Six all-new competitors plus six riders from the original SSX make up the circuit. Compete in the World Circuit, go head-to-head in the Showoff versions of nine courses on the World Circuit, or just practice in Free Ride. With all-new Garibaldi and Valdez courses, you'll have plenty of huge cliff drops to catch big air and pull off Uber tricks.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/8378","developer":"Electronic Arts Canada","coverName":"SSX Tricky (USA)","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.5,"count":141}},{"id":"sly-2-band-of-thieves","title":"Sly 2: Band of Thieves","year":2004,"genres":["Action","Adventure","Beat 'em up","Platformer"],"description":"Thief and raccoon Sly Cooper returns in a new cel-shaded platforming adventure wherein he forms a band of thieves with Bentley the turtle and Murray the purple, hippo-like creature, which each have their own role within the game.\n\nSly is the fastest, most agile member of the band of thieves and still is the character you play with the most. But certain missions require the special abilities of Bentley, who is smart and can drop bombs, as well shoot enemies from a distance. Other missions require the muscles of Murray, who can lift nearly everything, including enemies.\n\nThe main goal of the game is the retrieval of a number of clockwork pieces from different locations around the world. Each theft has to be prepared with a number of sub-missions which have to be completed before the 'real thing' can begin.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9813","developer":"Sucker Punch Productions","coverName":"Sly 2 - Band of Thieves (USA)","players":"1","publisher":"Sony Computer Entertainment","esrb":"E - Everyone","rating":{"score":4.43,"count":140}},{"id":"tony-hawk-s-pro-skater-4","title":"Tony Hawk's Pro Skater 4","year":2002,"genres":["Sports"],"description":"Drop into the ultimate challenge. In the next chapter in the Tony Hawk series, pros challenge you to make your mark in huge free-roaming levels, taking on 190 progressively harder goals with no time limits to hold you back. Decide when you're ready to take on your Pro Challenge and move into the pro ranks, where it's a whole new game. Build your skills, perform all-new tricks, play up to eight players online, and show that you've got what it takes to go Pro.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9743","developer":"Neversoft Entertainment","coverName":"Tony Hawk's Pro Skater 4 (USA) (v1.02)","players":"2","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":4.23,"count":140}},{"id":"downhill-domination","title":"Downhill Domination","year":2003,"genres":["Racing"],"description":"Downhill Domination is a video game based on a fictional racing event with fictional racers mixed with a few unlockable professional racers. The game was released exclusively for the PlayStation 2.\n\nDownhill Domination includes a very different style of gameplay that differs from standard bike racing games by having the character riding downhill almost exclusively (hence the name), due to the incline of the tracks.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/21114","developer":"Incognito Entertainment","coverName":"Downhill Domination (USA)","players":"2","publisher":"Codemasters","esrb":"T - Teen","rating":{"score":4.15,"count":139}},{"id":"devil-may-cry-3-dante-s-awakening-special-edition","title":"Devil May Cry 3: Dante's Awakening: Special Edition","year":2006,"genres":["Beat 'em up"],"description":"The Special Edition of Devil May Cry 3 included a number of gameplay changes and additional content. Most notably, players could now choose to play as Dante's twin brother, Vergil. Other changes included an added survival mode called \"Bloody Palace\" with a total of 9999 levels; a new boss fight early in the game, with optional fights later; a \"Turbo Mode\" for 20 percent faster gameplay; and a continue system which can revive the character instantly, or allow the player to restart the fight they just lost as many times as they like. The game also has rebalanced difficulty.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4930","developer":"Capcom","coverName":"","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.27,"count":137}},{"id":"the-warriors","title":"The Warriors","year":2005,"genres":["Beat 'em up"],"description":"The Warriors is based on the 1979 gang film of the same name. In the game, you'll play as the leader of a gang that is struggling to regain control of the streets of New York. You must lead a team of up to eight other gang members and fight rival gangs in locations across New York. The combat system incorporates combos, a rage mode, and trash-talking snap attacks. The game material extends beyond the movie, drawing upon the book on which the movie is based.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12509","developer":"Rockstar Toronto","coverName":"Warriors, The (USA) (En,Fr,De,Es,It)","players":"2","publisher":"Rockstar Games","esrb":"M - Mature","rating":{"score":4.36,"count":137}},{"id":"hack-g-u-vol-1-rebirth","title":".hack//G.U. Vol. 1: Rebirth","year":2006,"genres":["RPG"],"description":".hack//G.U. takes place in an alternate version of Earth in the year 2017. As depicted in the first .hack game series, the \"2nd Network Crisis\" was an incident that occurred seven years ago in which many computer systems across Japan malfunctioned. Through the efforts of those games' hero, Kite, the incident resulted in the birth of Aura, the ultimate artificial intelligence (AI), capable of making decisions for itself. Under the guidance of Aura, The World, the most popular massively multiplayer online role-playing game at the time, flourishes and the events of .hack//Legend of the Twilight occur during this four-year period","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12739","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Bandai","esrb":"T - Teen","rating":{"score":3.51,"count":136}},{"id":"jak-3","title":"Jak 3","year":2004,"genres":["Action","Platformer"],"description":"Jak 3 is set in the New World, its time frame placing it around 300 years after the events of the first game. Jak 3 largely focuses on the Wasteland, a large desert only briefly referred to in the previous entry in the series as being completely uninhabited and inhospitable.\n\nSpargus City, a large settlement within the Wasteland bordering the ocean, is where the game officially begins, and serves as a hub for the player, where new weapons and upgrades can be earned, and most missions are given out.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4872","developer":"Naughty Dog","coverName":"Jak 3 (USA) (En,Fr,De,Es,It,Pt,Ru)","players":"1","publisher":"Sony Computer Entertainment America","esrb":"T - Teen","rating":{"score":4.4,"count":135}},{"id":"ssx-3","title":"SSX 3","year":2003,"genres":["Racing","Sports"],"description":"Shred the slopes of the world's biggest mountain as you attempt to become the greatest snowboarder of all time. You must venture around the mountain, completely free to do what you wish, in order to find challenges and races to compete in.\n\nThere are a variety of events to compete in, from your usual all-on-all race through courses, scattered with obstacles and huge jumps to perform wacky tricks, plus there's a half pipe to bust tricks, and there's plenty of challenging tricks to master, and items to grind to gain bonuses. Plus, you can ride the entire mountain whenever you like, either to practice moves or learn all the bumps and corners for the big races.\n\nWith challenges and races comes rewards, and along with trophies and medals to fill up your gallery you can also win cash prizes to purchase new items, improving your board or improving your image. The more you race the more experience your chosen character receives, leveling up your abilities and improving your technique, plus even more wild tricks to perform.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3760","developer":"Electronic Arts Canada","coverName":"SSX 3 (USA)","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.46,"count":135}},{"id":"okami","title":"Ōkami","year":2006,"genres":["Action","Adventure"],"description":"The game is set in Nippon based on Japanese classic history, and begins with a flashback to events 100 years prior to the game's present, and describes how Shiranui, a pure white wolf, and Nagi, a swordsman, together fought the eight-headed demon Orochi to save Kamiki Village and the maiden Nami, Nagi's beloved. Shiranui and Nagi are unable to defeat Orochi but manage to seal the demon away. In the game's present, Susano, a descendant of Nagi and self-proclaimed greatest warrior, breaks Orochi's seal due to the fact that he does not believe in the legend, and Orochi escapes and curses the lands, sapping the life from every living being. Sakuya, the wood sprite and guardian of Kamiki Village, calls forth Amaterasu, the sun goddess, known to the villagers as the reincarnation of the white wolf Shiranui, and pleads her to remove the curse that covers the land. Accompanied by the artist Issun (an inch-high Poncle), Amaterasu is able to restore the land to its former beauty. Throughout the journey, Amaterasu is hounded by Waka, a strange but powerful individual that seems to have the gift of foresight, and further teases Amaterasu and Issun to his own mysterious ends. Additionally, Amaterasu locates several Celestial Gods who have hidden in the constellations that bestow upon the goddess powers of the Celestial Brush to aid in her quest.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/51","developer":"Clover Studio","coverName":"","players":"1","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.37,"count":134}},{"id":"007-agent-under-fire","title":"007: Agent Under Fire","year":2001,"genres":["Shooter"],"description":"CIA agent Zoe Nightshade, a mole in Identicon Corporation, based in Hong Kong, is discovered and captured. Identicon, a botanical research firm, is a possible front for a weapons-smuggling ring. James Bond infiltrates the facility in an attempt to rescue her, as well as retrieve a suspicious courier case in the same building. After freeing Nightshade from a submarine set to launch, the pair flee the facility with the courier case. Nigel Bloch, the head of Identicon, has his forces chase the agents through the streets of Hong Kong. The two steal a second case of vials from a nearby Identicon factory. They then rendezvous with R, who provides Bond with a gadget-laden BMW Z8. A limousine pulls up, as an assassin inside launches a rocket at the agents, killing Zoe, and steals the case. Bond gives chase, stopping an armored van which contained the stolen vials.\n\nThe vials contain nine blood samples, eight of which contained blood of world leaders. One contains the blood of British diplomat Reginald Griffin, serving in Romania, who is obsessed with protecting a room, outside of his jurisdiction, in the embassy. Bond investigates the embassy, finding Griffin dead, before a similar-looking man attacks him. After overcoming him, Bond finds a message from Bloch on Griffin's computer that mentions Malprave Industries, based in Switzerland. Bond takes the information from the computer and escapes.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4759","developer":"Electronic Arts Canada","coverName":"007 - Agent Under Fire (USA)","players":"4","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.91,"count":134}},{"id":"star-wars-battlefront-ii","title":"Star Wars: Battlefront II","year":2005,"genres":["Shooter"],"description":"Battlefront II features a more narrative-based campaign, retelling portions of the Star Wars story from the point of view of a veteran Imperial stormtrooper, reminiscing about his tour of duty in service of both the Galactic Republic and as part of the Galactic Empire. Gameplay additions over Battlefront include the use of Jedi, additional game modes, and objective-based space battles.\n\nTwo players can play splitscreen co-op throughout the story campaign or a strategic Galactic Conquest campaign.There is also a \"comp stomp\" configuration that supports 2 players offline, 2 players splitscreen online, or up to 16 players online.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4780","developer":"Pandemic","coverName":"Star Wars - Battlefront II (USA) (v1.01)","players":"2","publisher":"LucasArts","esrb":"T - Teen","rating":{"score":4.5,"count":133}},{"id":"fatal-frame-ii-crimson-butterfly","title":"Fatal Frame II: Crimson Butterfly","year":2003,"genres":["Adventure","Horror"],"description":"Twin sisters Mio and Mayu, while visiting a vacation spot from their childhood, become lost in a dark forest. The path disappears behind them as they enter the Lost Village, a place that vanished from the living world years ago. Ghosts of the townspeople walk the streets and search for the twins, intent on completing a dark ritual long left unfinished. Mayu begins to grow distant from Mio as well, and she begins to speak as if she were another person entirely. By chance Mio finds the Camera Obscura, and with its powers she searches for a way out get her sister and herself out of the village.\n\nFatal Frame II has mostly the same gameplay as the first game in the series, although with a few tweaks. The camera no longer has to charge up a shot, but different film types now have loading times that can leave leave Mio defenseless if she takes a picture at a bad time. Special abilities for the camera no longer require a disposable item, and are instead charged by taking good shots of attacking ghosts. The stats of the camera and special abilities are still upgraded/unlocked with spirit points, but an item must first be found and spent as well to upgrade each level of a stat.\n\nThe Xbox release of Fatal Frame II includes an additional difficulty level, an additional ending, several extra unlockable cosmetic accessories, six additional unlockable pairs of costumes for Mio and Mayu, an unlockable survival mode with an additional ghost type, and an optional first person control/view style.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7251","developer":"Tecmo","coverName":"Fatal Frame II - Crimson Butterfly (USA)","players":"1","publisher":"Tecmo","esrb":"M - Mature","rating":{"score":4.29,"count":132}},{"id":"soulcalibur-ii","title":"SoulCalibur II","year":2003,"genres":["Fighting"],"description":"Four years have passed since the spirit sword, Soulcalibur defeated the evil Soul Edge. At the end of that fateful battle, the shards of the shattered Soul Edge were scattered across the world and Soulclibur was lost to the void. Now, the evil that still resides in the scattered shards of Soul Edge threatens again to engulf the world in darkness.\n\nSoul Calibur II is a fighting game that continues the tradition set by Soul Blade and Soul Calibur with intense action and plenty of weapons to deal the massive blows. Mortal Kombat-style one-on-one fighting is one thing, but fighting with weapons is completely different. It features an exclusive character for Playstation 2: Heihachi Mishima from the Tekken series.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4789","developer":"Project Soul","coverName":"Soulcalibur II (USA)","players":"2","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.43,"count":132}},{"id":"007-from-russia-with-love","title":"007: From Russia with Love","year":2005,"genres":["Shooter"],"description":"The game begins with a standard pre-title sequence in which Elizabeth Stark, the Prime Minister of the United Kingdom's daughter, is kidnapped by OCTOPUS while attending a party. Fortunately, Bond was assigned to attend the party for just such an event, and he defeats OCTOPUS and rescues Stark.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4758","developer":"Electronic Arts Redwood Shores Studio","coverName":"007 - From Russia with Love (USA)","players":"4","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.92,"count":131}},{"id":"crash-nitro-kart","title":"Crash Nitro Kart","year":2003,"genres":["Racing"],"description":"The orange wonder from down under is back for another adventure, this time from behind the wheel of a go-kart. Inspired by 1999's hit CTR (Crash Team Racing) for the original PlayStation, Crash Nitro Kart offers four-player racing action in a variety of game modes. Players will compete in cup challenges, time trials, and an assortment of multiplayer battles. While speeding along the predominately outdoor environments, players can run over such items as wumpa fruit to increase speed, ramps to leap over chasms, and crates to acquire power-ups for offense or defense. In addition to Crash Bandicoot, featured characters include Crunch, Coco, Dingodile, Neo Cortex, and more.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/13655","developer":"Vicarious Visions","coverName":"Crash Nitro Kart (USA)","players":"4","publisher":"Universal Interactive","esrb":"E - Everyone","rating":{"score":3.6,"count":130}},{"id":"baldur-s-gate-dark-alliance","title":"Baldur's Gate: Dark Alliance","year":2001,"genres":["Action","RPG"],"description":"Baldur's Gate: Dark Alliance is a real time hack and slash Action role-playing game presented in a true 3D perspective correct rotatable third person overhead view. The battle system in the game is simplistic but flexible. Character statistics at the game's beginning are preset, and the player may only customize their character's stats through gaining experience points. Experience points are gained by winning battles, and at specific levels the character gains new ability points to spend on enhancements specific to the character class. The ability choices affect the fighting style of the character.\n\nGameplay is linear, and any current quest must be completed successfully before the story proceeds. There are also relatively few non-player characters (NPCs), of which only those who are part of a quest or side-quest may be interacted with. There are not that many sidequests available in the game, but those available - such as for Keaira and Ipswitch - help players to gain experience and level up. Weapons, armor and items are only available for purchase from one location at a time in the current region, and are increasingly valuable later in the game.\n\nThe game's ruleset is based on a limited set of 3rd Edition Dungeons & Dragons rule-set; compared to other D&D Games there are relatively few rules implemented in the game. There are four playable classes: Human Arcane Archer, Elven Sorceress, Dwarven Fighter and Drow Ranger. Gameplay strategy is different for all characters: the human relies on ranged attacks and stealth, the elf character can cast magic spells, and the dwarf is an all-around fighter. Through updating each character, the characters go to mimic characters of other classes.\n\nA local co-op mode is available, which uses a single non-split screen view. The second player can select one of the unused characters.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5898","developer":"Snowblind Studios","coverName":"Baldur's Gate - Dark Alliance (USA)","players":"2","publisher":"Interplay Entertainment","esrb":"T - Teen","rating":{"score":4.21,"count":130}},{"id":"dark-cloud-2","title":"Dark Cloud 2","year":2003,"genres":["Action","RPG"],"description":"As a young inventor, you are called upon to search the dangerous dungeons, battle evil monsters and re-claim towns and cities.\n\nBy fighting your way through the various dungeons, you must find various ores hidden away. With these ores, you can determine which parts you need to re-build a town. It is up to you to find or create the parts needed to build the various buildings of each town, as well various other parts to each town.\n\nDuring your adventure, you can also take pictures of various items. Once you have a certain amount, you can then come up with ideas for an invention that will aid you in your quest. From there, you must again find the parts needed to create the invention, and then use the invention either to help you defeat enemies or build the towns.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9649","developer":"Level-5","coverName":"Dark Cloud 2 (USA) (v1.00)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.33,"count":128}},{"id":"outrun-2006-coast-2-coast","title":"OutRun 2006: Coast 2 Coast","year":2006,"genres":["Racing"],"description":"Like its predecessors, OutRun 2006 is an old-school arcade racer, which means that your cars don't have realistic physics, don't get damaged and have insanely fast speed.\n\nSince this title is officially licensed by Ferrari, you drive with 15 original models from the DINO 246 GTS over the F430 to the all-new Enzo Ferrari. The heart of the game is the Coast 2 Coast mode in which you race against up to 5 AI players on 15 US themed tracks. In addition you have to impress different girlfriends. She tells you what she wants to see (a hard slide around a curve or a close take-over for example) and you have to perform it to win her heart.\n\nThere are 3 other game modes available in singleplayer: OutRun, Time Attack and OutRun2SP. In OutRun2SP you get access to 15 arcade tracks from the original OutRun 2. In OutRun however you need to drive your girlfriend through various checkpoints to the goal before the timer hits zero. In Time Attack you just have to beat the highscore of the current track. You can either race against the clock or against ghost cars.\n\nIn every mode you get OutRun miles after the race. These are the currency of the game and are needed to unlock new cars, upgrades and additional music-stations.\n\nIf you feel alone, even with your virtual girlfriend in the car, you can race online against 5 other players.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4809","developer":"Sumo Digital","coverName":"OutRun 2006 - Coast 2 Coast (USA) (En,Fr,Es)","players":"8","publisher":"Sega","esrb":"E - Everyone","rating":{"score":4.42,"count":127}},{"id":"spider-man-2","title":"Spider-Man 2","year":2004,"genres":["Action"],"description":"It is two years following the events of the first game. Spider-Man is trying to balance his civilian and superhero life, frequently late or absent for school, work, and leisure time with his friends. Following dinner with Mary Jane Watson, Peter thwarts an armed looting of an art museum, and tracks down an escaped robber, the Black Cat. Soon after this, he thwarts an attack in the streets of Manhattan by The Rhino. Meanwhile, Doctor Otto Octavius attempts to recreate nuclear fusion of that seen in the sun to provide an energy source for Manhattan. To control this fusion, he creates four metal arms which he can mentally control. His fusion creates a strong magnetic field, destroying the lab, killing his wife Rosie, and grafting his metal arms to his spine and giving his arms control over him. He blames Spider-Man for the incident, despite the fact that Spider-Man was not in the lab until the middle of it.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4778","developer":"Treyarch","coverName":"Spider-Man 2 (USA)","players":"1","publisher":"Activision","esrb":"T - Teen","rating":{"score":3.92,"count":126}},{"id":"ace-combat-5-the-unsung-war","title":"Ace Combat 5: The Unsung War","year":2004,"genres":["Flight","Shooter"],"description":"Ace Combat 5: The Unsung War is a first person air combat and flight simulator. Like other Ace Combat games, each mission is determined by a level briefing and objectives. There are 32 missions in the main campaign mode, while an additional \"arcade\" mode puts the player in the role of Mobius One (from Ace Combat 04: Shattered Skies) as he faces endless waves of enemy attacks. Regardless of the mode chosen, once in the air the player will have control over speed, direction, altitude, gun cannon, missiles and special weapon of their aircraft. A new feature from previous Ace Combat games, is the concept of Wingmen and being able to issue simple orders to them in the air. This allows the player to better coordinated group attacks as well as giving each wingman a personality of their own. Additionally, the player as squadron leader will be asked to make decisions (\"Yes/No\") while flying in the air. Between missions, the story is progressed through a series of cutscenes.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3912","developer":"Project Aces","coverName":"Ace Combat 5 - The Unsung War (USA) (En,Ja)","players":"2","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.28,"count":125}},{"id":"devil-may-cry-2","title":"Devil May Cry 2","year":2003,"genres":["Beat 'em up"],"description":"Devil May Cry 2, the sequel to the gothic horror classic, features bigger and more varied environments, including a modern day metropolis and an old European town. There are now two playable characters allowing you to play as Dante or a brand-new heroine, the sexy and mysterious Lucia. Dante is even more stylish and tough than before, having gained plenty of experience fighting demons. Devil May Cry 2 will track a player's skill level and adjust the enemies' difficulty according to how well players perform. Dante now has more moves and attacks, plus an enhanced Devil Trigger: Once Dante's devil trigger gauge is full he will be able to transform into a demon. This demon form features new visual effects and grants Dante a massive power boost.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3900","developer":"Capcom","coverName":"Devil May Cry 2 (USA) (Disc 1)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":3.54,"count":123}},{"id":"need-for-speed-hot-pursuit-2","title":"Need for Speed: Hot Pursuit 2","year":2002,"genres":["Racing"],"description":"The Need for Speed series returns, this time reverting back to the 'chase' arcade experience instead of a racing simulation. Top speed racing is the name of the game, where you must outchase not just the opposing drivers, but the cops.\n\nChoose from a selection of today's (and yesterday's) top sports cars, including the Ferrari F50, Porsche 911 and a range from the likes of Ford, Corvette, BMW, Lotus, Mercedes, Aston Martin, the McLaren F1 and a lot more.\n\nThe competitive race mode allows you to take on other drivers and beat them to the line. A selection of tracks allows you to not only dodge incoming traffic, but perform deadly jumps and stunts to receive points. These points, combined with the points recieved from your finishing position, can unlock new cars and tracks.\n\nThe Hot Pursuit mode combines all the major elements of the competitive mode with the chance to out run the cops. They will throw everything at you to try and stop you, including running you off the road, setting up road blocks and unleashing an attack helicopter equiped with missiles. Three busts by the cops ends the race.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7426","developer":"Black Box Games","coverName":"Need for Speed - Hot Pursuit 2 (USA)","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.18,"count":123}},{"id":"007-nightfire","title":"007: Nightfire","year":2002,"genres":["Shooter"],"description":"After a thrilling night on the streets of Paris, legendary secret agent James Bond (voiced by Maxwell Caulfield with the likeness of Pierce Brosnan) is assigned to find a missing American Defense Satellite, Nightfire. This begins a journey that will take James from Tokyo highrises to the reaches of space as James and an assortment of secret agents race to stop the end of the world at the hands of maniacal billionaire!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4757","developer":"Electronic Arts Canada","coverName":"007 - Nightfire (USA)","players":"4","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.0,"count":122}},{"id":"ape-escape-2","title":"Ape Escape 2","year":2003,"genres":["Platformer"],"description":"Ape Escape 2 is the sequel to Ape Escape. In this platform game it's your goal to catch all the apes jumping, walking and flying around the diverse levels the game has to offer.\n\nA large arsenal of gadgets can be used to make it all a little easier, with the catching net being the most important weapons of them all. Other gadgets include a RC Car, to drive over monkey's and collect objects, an Ape Radar, to detect the nearest monkey, a baseball bat, to hit monkeys unconscious, and a magnet, to move certain objects in the maps.\n\nYour quest is to catch all monkeys in the levels and to stop the evil Specter from taking over the world. All monkeys in the levels are somewhat unique with their own character abilities and their unique name. Some monkeys just sit on their place, while others attack you with projectiles or run away quickly.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9625","developer":"Japan Studio","coverName":"Ape Escape 2 (USA)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"E - Everyone","rating":{"score":4.26,"count":121}},{"id":"tony-hawk-s-underground","title":"Tony Hawk's Underground","year":2003,"genres":["Sports"],"description":"The story follows the trials and tribulations of two unknown skaters. The player, as a Custom Skater (the main character in the storyline) and the Custom Skater's friend Eric Sparrow. The story begins in their hometown in New Jersey, with the Custom Skater and Eric exploring the area and helping prepare for Chad Muska's skate demo. After the demo, the Custom Skater performs for Chad as he explores the greater New Jersey area to grab his attention. Once accomplished, he suggests to the player to earn a sponsorship from the local skateshop, and gives the player his skateboard out of respect. After impressing the local sponsored skaters, one of Custom Skater's friends, Shawn, says that the local drug dealers have stolen a skateboard from Peralta's shop. The custom skater is sent on a dangerous odyssey to retrieve it.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4774","developer":"Neversoft Entertainment","coverName":"Tony Hawk's Underground (USA)","players":"2","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":4.47,"count":121}},{"id":"wwe-smackdown-here-comes-the-pain","title":"WWE Smackdown! Here Comes the Pain","year":2003,"genres":["Fighting","Sports"],"description":"WWE SmackDown! Here Comes the Pain is a follow-up to WWE SmackDown! Shut Your Mouth, showcasing more than 55 WWE superstars (including Brock Lesnar, Scott Steiner, Rey Mysterio, Bill Goldberg, and others), as well as adding famous wrestlers of former times (\"WWE Legends\") to the roster. \n\nThe game features real-life attributes of strength, submission, technique, speed and stamina for each wrestler. These new attributes allow players to wear down their opponents and take advantage of each Superstar's unique abilities and extensive move sets, expanding the amount of stances to sixteen (as opposed to four in the previous game). The presentation has been enhanced with new camera angles, superstar voiceovers, additional animations, and new arena and crowd elements. \n\nPlayers can create, play and develop their own superstar through various storylines staged by the WWE. New match types and modes are available as well. Players can track their progress with seasonal stats, earn money to build up superstar abilities, and unlock hidden features.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/10246","developer":"Yuke's","coverName":"WWE SmackDown! Here Comes the Pain (USA)","players":"4","publisher":"THQ","esrb":"T - Teen","rating":{"score":4.54,"count":121}},{"id":"mortal-kombat-deadly-alliance","title":"Mortal Kombat: Deadly Alliance","year":2002,"genres":["Fighting"],"description":"In Deadly Alliance, the player receives information concerning the backstories of the characters and their relationships with one another mainly during Konquest mode, but also in way of biographies that can be obtained in the Krypt. The game takes place in a fantasy setting, with most of the game's events occurring on the fictional realms of the Mortal Kombat series. The story begins in the Netherealm (although this is not a playable level), and later switches to Outworld, Edenia and eventually Earthrealm.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4816","developer":"Midway Games","coverName":"Mortal Kombat - Deadly Alliance (USA)","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":3.93,"count":121}},{"id":"need-for-speed-most-wanted-black-edition","title":"Need for Speed: Most Wanted: Black Edition","year":2005,"genres":["Racing"],"description":"In Need for Speed Most Wanted, you can try to become the most notorious street racer alive. Outrun both racers and cops to increase your reputation and move up the street racing blacklist. You can choose from a variety of vehicle types and destructible urban maps featuring shortcuts, traffic, and patrolling police. Need for Speed Most Wanted also includes online play for challenging other gamers.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/28317","developer":"Electronic Arts Black Box","coverName":"Need for Speed - Most Wanted - Black Edition (USA)","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.42,"count":120}},{"id":"red-dead-revolver","title":"Red Dead Revolver","year":2004,"genres":["Shooter"],"description":"Orphaned by bandits and left for dead on the frontier, Red Harlow grew up with a scar burned into his hand and the lust for revenge burned into his heart. Surviving as a bounty hunter in the rough-and-tumble Old West, Red stays ever watchful for some clue that could lead him to the men who murdered his father and mother -- and then one day, that clue appears. Step into Red's spurred boots, and take up his mission of revenge.\n\nRed Dead Revolver features environments and artistry inspired by the classic spaghetti westerns films, mixed with third-person shooter gameplay similar to that of Max Payne. The gameplay and story proceed linearly through stages, including several levels in which you play as different characters (a British trick shooter, a female rancher, a renegade Mexican general, a stealthy native warrior, and a Buffalo Soldier). Each character has his own signature move: for instance, Red's \"Dead-Eye\" slows down time and allows you to set up targets for a rapid \"fan fire\" takedown, while General Diego's flare rifle lets you specify a target for bombardment by Diego's cannons.\n\nBeating each level will earn you reward money (and chaining together many limb shots and multiple kills will earn you bonus money). You can spend your cash on unlockable characters (for the multiplayer game), journal entries that offer backstory and character info, or an array of canonical Old West weaponry, including pistols, rifles, and shotguns of many varieties, as well as knives, molotovs, poison and dynamite.\n\nThe game features pistol dueling with certain boss characters, as a mini-game mechanic in which you time your draw to an opportune moment and prepare targets as you raise your gun. There is also a multiplayer game (split-screen only, not networked), which you can play with friends and/or AI bots. Multiplayer incorporates a wide array of power ups, an alternative dueling showdown mode, and two kinds of optional poker sub-games (based on stud or Texas Hold 'Em) that mix some strategy into the action.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5376","developer":"Rockstar San Diego","coverName":"Red Dead Revolver (USA)","players":"4","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.06,"count":119}},{"id":"resident-evil-outbreak","title":"Resident Evil: Outbreak","year":2003,"genres":["Horror","Shooter"],"description":"Resident Evil Outbreak returns you to the Umbrella Corporations disaster that consumed Racoon city. You play one of eight ordinary citizens of Racoon city attempting to survive the carnage caused by the T-Virus. \n\nThere are five different scenarios in this game. Initially only one is open to you, this is concerned with the outbreak in the city, but upon its completion further scenarios with different plots and locations become available. \n\nGameplay is similar to the previous Resident Evil games. It consists mainly of exploring, solving puzzles, finding items and of course surviving. This is also the first game of the resident evil franchise that can be played on-line, with up to four people playing cooperatively in order to survive.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3946","developer":"Capcom Production Studio 1","coverName":"Resident Evil - Outbreak (USA) (v1.01)","players":"4","publisher":"Capcom","esrb":"M - Mature","rating":{"score":3.9,"count":119}},{"id":"contra-shattered-soldier","title":"Contra: Shattered Soldier","year":2002,"genres":["Shooter"],"description":"The ultimate run'n'gun shooter is here! Contra: Shattered Soldier brings classic, fast-paced shooting action to the PlayStation 2 computer entertainment system. As an unknown alien army invades the Earth, Bill Rizer and his partner Lucia last through intense firefights in an attempt to stop the invasion and save the human race. With non-stop action, advanced weaponry and hordes of nasty aliens, Contra: Shattered Soldier blows the lid off of traditional action games!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5405","developer":"Konami Computer Entertainment Tokyo","coverName":"Contra - Shattered Soldier (USA) (En,Fr,Es)","players":"2","publisher":"Konami","esrb":"T - Teen","rating":{"score":3.94,"count":119}},{"id":"guitar-hero-iii-legends-of-rock","title":"Guitar Hero III: Legends of Rock","year":2007,"genres":["Rhythm"],"description":"Rock out to the third entry in in Red Octane's music series for guitar gods! Songs for Guitar Hero III include Barracuda by Heart, Sabotage by Beastie Boys, Rock And Roll All Nite by Kiss, and much more! In addition, players can experience an incredible number of added features and explosive content including a new multiplayer action-inspired battle mode, grueling boss battles, a bevy of exclusive unlockable content and authentic rock venues.\n\nAlso for the first time ever, Guitar Hero fans can thrash and burn with new wireless guitar controllers available for each platform. The exclusive Gibson guitars include innovative features such as removable faceplates that will allow fans to personalize their guitars and make it their own, and a new button color design that is integrated for an even greater authentic feel and rock experience.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7290","developer":"Budcat Creations","coverName":"Guitar Hero III - Legends of Rock (USA)","players":null,"publisher":"RedOctane","esrb":"T - Teen","rating":{"score":4.28,"count":118}},{"id":"metal-slug-anthology","title":"Metal Slug Anthology","year":2007,"genres":["Shooter"],"description":"One of the most successful, and fun to play side-scrolling arcade games in history, the Metal Slug series is celebrating its 10th year anniversary with the release of the Metal Slug Anthology. With the Metal Slug Anthology, you will enjoy seven arcade-perfect conversions, including the all-new Metal Slug 6.\n\nMetal Slug Anthology is the definitive collection of the intense shooter series. It includes all six of the classic games, all on one disc -- with more ammunition and firepower than ever before. You've got an incredible arsenal waiting for you, from destructive pistols & combat vehicles to a stockpile of grenades. Players' enemy-killing capabilities are upped to off more evil-doers in this 10th anniversary edition of the arcade classics. Includes Metal Slug, Metal Slug 2, Metal Slug X, Metal Slug 3, Metal Slug 4, Metal Slug 5, and Metal Slug 6.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3932","developer":"Terminal Reality","coverName":"Metal Slug Anthology (USA)","players":"2","publisher":"Ignition Entertainment","esrb":"T - Teen","rating":{"score":4.34,"count":118}},{"id":"yakuza","title":"Yakuza","year":2005,"genres":["Fighting","Sandbox"],"description":"Kiryu Kazuma was brought up in the Sunflower Orphanage, and has been protected since his childhood by a lieutenant of the Dojima Family, affiliated with the Tokyo-based Tojo Clan of the Japanese organized crime syndicate, the yakuza. His back covered with a tattoo of a dragon, Kazuma soon becomes a prominent member of the Dojima Family - until he takes the blame for the murder of its leader in order to protect his best friend, and is sent to prison.\n\nTen years later, Kazuma returns to his home town Kamurocho. He finds out that Yumi Sawamura, a young woman he grew up with in the orphanage, has disappeared. Ten billion yen has been stolen from the Tojo Clan, and various yakuza groups are searching for the money everywhere. Against his will, Kazuma becomes involved again in the struggles and intrigues of the yakuza world. \n\nYakuza is a hybrid game that contains elements of free-roaming exploration, hand-to-hand fighting, and role-playing. In the exploration mode, Kazuma explores the Kamurocho district on foot. The game's structure is mission-based: the player can, for the most part, explore the town, entering some of the buildings, shopping, or participating in various mini-games, such as UFO catcher, batting cage, slot machines, blackjack, and others. Beside plot-advancing missions, the game also features side quests, which can be triggered by interacting with some of the characters roaming the town.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/8500","developer":"Sega","coverName":"Yakuza (USA)","players":"1","publisher":"Sega","esrb":"M - Mature","rating":{"score":4.08,"count":118}},{"id":"mortal-kombat-deception","title":"Mortal Kombat: Deception","year":2004,"genres":["Fighting"],"description":"Twenty-six characters are available to play in the game, with nine making their first appearance in the series. Deception contains several new features in the series, such as chess and puzzle games with the MK characters and an online mode. The Konquest Mode role-playing game (RPG) makes a return from Deadly Alliance, but follows the life of Shujinko, a warrior who is deceived by Onaga to search for artifacts to give Onaga more powers. In November 2006, Midway released Mortal Kombat: Unchained, a port for the PlayStation Portable, which adds new characters to the game.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4817","developer":"Midway Games","coverName":"Mortal Kombat - Deception (USA) (Premium Pack Bonus Disc)","players":"2","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":4.25,"count":118}},{"id":"onimusha-3-demon-siege","title":"Onimusha 3: Demon Siege","year":2004,"genres":["Action"],"description":"Onimusha 3: Demon Siege, released in Japan and Europe as Onimusha 3, is a hack-and-slash action-adventure video game developed and published by Capcom. It is the third game of the Onimusha series and was released for the PlayStation 2 on April 27, 2004. The story focuses on the returning hero, swordsman Hidemitsu Samanosuke Akechi, who is in his quest to defeat his nemesis, Nobunaga Oda, who wishes to conquer Japan with his army of demons known as Genma. However, Samanosuke changes places with a French officer from the future named Jacques Blanc, and both have to adapt to their new worlds to get rid of Genma army and stop Oda Nobunaga's ambitions to conquer the world.\n\nThe game retains elements from previous games in the franchise including the use of multiple special weapons in order to fight enemies and absorb their energy to enhance the weaponry. This time the player primarily controls both Samanosuke and Jacques in separate scenarios. The two are able to exchange items in order to solve puzzles. The development from this game started after the release of the PlayStation 2 which allowed the team to work on a 3D engine to design 3D backgrounds. In order to appeal to the Western market, the team set this game in Paris and chose French actor Jean Reno to portray Jacques.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9767","developer":"Capcom","coverName":"Onimusha 3 - Demon Siege (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.32,"count":117}},{"id":"manhunt","title":"Manhunt","year":2003,"genres":["Action","Horror","Stealth"],"description":"Walk in the shoes of James Earl Cash, a man sentenced to death only to find himself given an unexpected and sinister reprieve. Forced to fight and outwit hordes of bloodthirsty gang members vying for his head on a platter. All orchestrated for pleasure and profit by the voice of an unseen Director. This is a brutal bloodsport.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4815","developer":"Rockstar North","coverName":"Manhunt (USA)","players":"1","publisher":"Rockstar Games","esrb":"M - Mature","rating":{"score":3.92,"count":117}},{"id":"devil-may-cry-3-dante-s-awakening","title":"Devil May Cry 3: Dante's Awakening","year":2005,"genres":["Beat 'em up"],"description":"Raise Hell! Dante's past is revealed as Devil May Cry returns to its roots. Master Dante's multiple fighting styles while battling never before seen demons and new characters as you fight your way towards a brutal confrontation with Dante's mysterious twin brother Vergil. \n\nChoose Dante's Fighting Style - maximize the impact of close-up blade attacks or blow enemies away from a distance with a huge arsenal of weapons including handguns, shotguns, swords and more. Battle against a a horde of demonic enemies that are more ferocious than ever with powerful weapons and the abilities to transform and fly.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/16","developer":"Capcom","coverName":"Devil May Cry 3 - Dante's Awakening (USA) (En,Ja) (Special Edition)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.17,"count":116}},{"id":"need-for-speed-most-wanted","title":"Need for Speed: Most Wanted","year":2005,"genres":["Racing"],"description":"The player arrives in Rockport City, driving a racing version of the BMW M3 GTR (E46). Following Mia Townsend (played by Josie Maran), the player proves his driving prowess as he is pursued by a veteran police officer named Sergeant Cross (played by Dean McKenzie), who vows to take down the player and end street racing in Rockport.\nRaces seem to be in the player's favor until a particular group of racers, led by the game's antagonist, Clarence \"Razor\" Callahan (played by Derek Hamilton), sabotages and win the player's car in a race.\n\nWithout a car to escape in, the player is arrested by Cross, but is later released due to lack of evidence. Mia picks up the player and then informs the player about Razor's new status on the Blacklist, a group of 15 drivers most wanted by the Rockport Police Department. She then helps by assisting the player in acquiring a new car and working his way up the Blacklist. Rivals are defeated one by one, and the player is rewarded with reputation, new rides, and ride improvements with every Blacklist member taken down. \nAs new boroughs are opened up throughout Rockport (Rosewood, Camden Beach, and Downtown Rockport), Mia also sets up safehouses for the player to lie low in, in exchange for placement of \"side bets\" on the player's races.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4814","developer":"Electronic Arts","coverName":"Need for Speed - Most Wanted (USA) (v1.01)","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.3,"count":116}},{"id":"dirge-of-cerberus-final-fantasy-vii","title":"Dirge of Cerberus: Final Fantasy VII","year":2006,"genres":["RPG","Shooter"],"description":"Set after the events of Final Fantasy VII and the Final Fantasy VII: Advent Children movie, Dirge of Cerberus lets players take the role of the mysterious Vincent Valentine.\n\nAfter a new organization arises from the events known as \"Meteorfall\", Vincent is called to the surviving town of Kalm by Reeve Tuesti, an old ally who controlled Cait Sith. Vincent has been invited to the town's celebration, but during the festivities, a group of soldiers attacks the town, killing and capturing the people. It is up to Vincent to protect the innocent once more, and find out why these soldiers are also after him.\n\nWhile set in the world of Final Fantasy VII, Dirge of Cerberus is an action shooter that runs through twelve chapters. The on-screen action can be controlled by the analog controller, or via the Playstation 2's mouse and keyboard accessories, making it more in line with PC-style shooters. Being a character driven shooter, the perspective can be changed from first to third person on the fly to navigate through the multi-level environments.\n\nSeveral items and characters from the series make their return, as well as the Chaos break limits system, which allows Vincent to take the monstrous forms he changed into from Final Fantasy VII to inflict more damage on the enemy. Taking a nod from its RPG-based parent, the game does allow Vincent to find the usual healing items, materia spells and gil from the Final Fantasy universe, in which he can buy and sell for other new items.\n\nThe game also features a weapon customization system, which allows the player to mix and match weapon parts to form more powerful attack items and abilities.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/839","developer":"Square Enix","coverName":"Dirge of Cerberus - Final Fantasy VII (USA)","players":"1","publisher":"Square Enix","esrb":"T - Teen","rating":{"score":3.79,"count":115}},{"id":"sly-3-honor-among-thieves","title":"Sly 3: Honor Among Thieves","year":2005,"genres":["Action","Adventure","Beat 'em up","Platformer"],"description":"Sly and the gang is back in this third outing of Sly Raccoon-series. This time, the story takes the boys (Sly, Bentley and Murray) to the fortress that houses the treasures of Sly's family. Although they are still weary from the adventures in the previous game, they have to get up and face the new threat that could mean the end of Sly's business and the loss of his family heritage. The game itself is a lot like the previous games: Sly sneaks, jumps, and swings himself around the levels, collecting various items, defeating bad guys and ultimately taking on the boss character. The other members of the gang step in on the action once in a while but the Sly centric sections are the main focus of the game. If you like games that had many things to do, this sneak-em-up/platform/action/adventure/puzzle game is for you.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9814","developer":"Sucker Punch Productions","coverName":"Sly 3 - Honor Among Thieves (USA)","players":"1","publisher":"Sony Computer Entertainment","esrb":"E10+ - Everyone 10+","rating":{"score":4.29,"count":115}},{"id":"ace-combat-zero-the-belkan-war","title":"Ace Combat Zero: The Belkan War","year":2006,"genres":["Flight","Shooter"],"description":"This sixth installment in the Ace Combat series is a prequel to Ace Combat 5 that tells about the Belkan War eluded to in Unsung War. The story is told through the eyes of a reporter, 15 years after the altercation, uncovering secrets about the Belkan War of how it led to war, the outcome of the nuclear detonations within their borders and a near disastrous secret that nearly led to the destruction of a nation.\n\nThe main game mode is the story mode, in which the player takes control of an Ustio mercenary pilot, call-sign \"Demon Lord\", taking part of the said war, advancing missions and advancing in the story while doing it. The missions can be anything done airborne, and there'll be escort, assault and defence missions amongst others. Like in the previous games, the game isn't about simulation, but fast paced aerial combat in highly powered aircraft. More like Top Gun, and less like real world.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4422","developer":"Namco Bandai Games","coverName":"Ace Combat Zero - The Belkan War (USA)","players":"2","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.12,"count":114}},{"id":"final-fantasy-x-2","title":"Final Fantasy X-2","year":2003,"genres":["RPG"],"description":"The game's story follows the character Yuna from Final Fantasy X as she seeks to resolve political conflicts in the fictional world of Spira before it leads to war.\n\nThe story begins as Yuna, Rikku and Paine recover Yuna's stolen Garment Grid from the Leblanc Syndicate in the first of several encounters in which they vie for spheres. The game is punctuated by a narration of Yuna addressing Tidus, as though she is recounting the events of the game to him as they occur in a style reminiscent of Tidus' own narration in Final Fantasy X. Although Yuna's quest is to find clues that may lead her to Tidus, much of the storyline of the game follows the clash of the factions that have established themselves in the time since the coming of the Eternal Calm in Final Fantasy X, and the uncovering of hidden legacies from Spira's ancient history. A significant portion of the game's events are unnecessary for the completion of the main storyline, but much of the depth of the story—including characterization and background details—are featured in the optional content, which generally follows how each part of Spira is healing in the time since the passing of Sin.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/19","developer":"Square Enix","coverName":"Final Fantasy X-2 (USA, Canada)","players":"1","publisher":"Square Enix","esrb":"T - Teen","rating":{"score":4.12,"count":114}},{"id":"ape-escape-3","title":"Ape Escape 3","year":2006,"genres":["Action","Platformer"],"description":"Help us stop this primate prime time invasion!\n\nUnder Specter's command, the mischievous monkeys are taking control of your television and airing programming that will cloud the mind of anyone who watches.\n\nSpecter and the monkeys are back and determined to rule the world!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9626","developer":"Japan Studio","coverName":"Ape Escape 3 (USA)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"E10+ - Everyone 10+","rating":{"score":4.27,"count":112}},{"id":"maximo-ghosts-to-glory","title":"Maximo: Ghosts to Glory","year":2002,"genres":["Action","Adventure"],"description":"Oh, what a knight!\n\nSo much glory, so little time... Can't a noble knight go away to war without having all hell break loose back home? Not this time. You control the fate of the gallant Maximo, who returns home to find his kingdom in shambles. Your once trusted advisor, Achille has wrought evil on the land. Not only is the countryside filled with hoards of the roaming undead, but the four wise Sorceresses have been imprisoned at the four corners of the kingdom. To make matters worse, your girlfriend, Princess Sophia, has been forced to marry the scoundrel Achille. Talk about your bad days! Help Maximo rescue the Sorceresses, restore good to the kingdom, whup Achille’s butt, and, while you're at it...get your girl back!\n\nMaximo is reminiscent of many of the old Capcom 2D platform games such as Ghouls n Ghosts, but the concept is revamped for the PS2 and done in crisp 3D graphics. The game is full of dynamic environments and tons of undead soldiers. The classic pick-up-and-play gameplay and stunning graphic sheen powered by the PlayStation 2 make Maximo a hero for the ages.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7358","developer":"Capcom","coverName":"Maximo - Ghosts to Glory (USA)","players":"1","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.07,"count":112}},{"id":"burnout-2-point-of-impact","title":"Burnout 2: Point of Impact","year":2002,"genres":["Racing"],"description":"Burnout is a street racing game focused around speed and crashing. Unlike many games which focus on closed course driving, you get to drive through cities with real traffic and city infrastructure. Designers have built an entire city and surrounding areas, and implement the race courses throughput the countie's streets. As a result, many times certain parts of race-courses interlace with other parts of other races. As well, instead of encouraging strategic driving and safe driving, Burnout strongly encourages offensive driving. Driving on the wrong side of the road, barely missing passing traffic, drifting, and jumps all add to your boost \"burnout\" meter. Speed boosts and jumps aid your attempt to dive past buses, trucks and anything else that gets in the way. The more offensive and dangerous your driving is, the more boost you get!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5908","developer":"Criterion Software","coverName":"Burnout 2 - Point of Impact (USA)","players":"2","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":4.33,"count":111}},{"id":"xenosaga-episode-i-der-wille-zur-macht","title":"Xenosaga Episode I: Der Wille zur Macht","year":2002,"genres":["RPG"],"description":"Xenosaga: Episode I - Der Wille zur Macht, the first chapter of a trilogy, is a Japanese-style sci-fi role-playing game, sharing many common themes and gameplay elements with Xenogears. The battle system is not unlike the one used in Xenogears (combo attacks, AP and EP gauges, etc.), but random encounters are eliminated. Instead, the enemies are now visible and battles can be avoided. During combat the few upcoming ally and enemy turns are shown onscreen, allowing the player to make strategic decisions based on who will act next. A rolling slot moves with each turn as well, conferring a bonus such as added damage or bonus XP for any action on that turn. If the enemy would be in position to take an advantage then the player can expend a character's \"boost\" gauge to cut in and act next, although enemies can boost as well, and enemy boosts always over-ride player boosts. \n\nEach character has a unique tree of Ether spells they can learn by spending Ether points earned in battle, with lower spells requiring spells above them to be purchased first. After a spell is purchased, so long is it does not require a unique talent of that character, the spell can also be purchased and learned by any other character that can afford double its normal cost. The Anti-Gnosis Weapon Systems can be equipped with different weapons and accessories and can be used in combat provided that a character has enough AP on that turn to board their AGWS.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5426","developer":"Monolith Software","coverName":"Xenosaga Episode I - Der Wille zur Macht (USA)","players":"2","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.29,"count":110}},{"id":"shadow-hearts","title":"Shadow Hearts","year":2001,"genres":["RPG"],"description":"The time for judgment has come. \n\nSet in the early 1900s, Shadow Hearts follows story of Yuri, an Harmonixer, someone who can take the forms of other creatures and beasts. The story starts with a mysterious girl named Alice, who is being transported by the Japanese Imperial army to China on a train. Suddenly, a powerful magician named Roger Bacon tries to capture Alice, since she bears the secret to unleash a forbidden incantation, one that could burn the entire world to ashes. Then, Yuri comes to the rescue and saves Alice. Thus, they must embark on an epic journey all across China and Europe, searching for the mysterious man who tried to kidnap Alice and unraveling a devious master plan of apocalyptic proportions. \n\nSomething that makes Shadow Hearts unique from other RPGs, is the use of the Judgment Ring, which is not only rooted to our party's performance on battles, but also other aspects of the game like buying items. Our mastery with this peculiar system is crucial, since depending on what part of the ring we hit, we can deal more physical damage or, if we aren't skillful with the ring, fail to perform attacks or magic at all. \n\nA hero with a mysterious past. A young girl holding the key to world domination. A villain who will stop at nothing to unlock the path to unlimited power. All this and more await you in a world of occultism, dark fantasy, and Gothic horror. Welcome to Shadow Hearts.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12753","developer":"Sacnoth","coverName":"Shadow Hearts (USA)","players":"1","publisher":"Midway Home Entertainment","esrb":"M - Mature","rating":{"score":4.05,"count":110}},{"id":"ratchet-deadlocked","title":"Ratchet: Deadlocked","year":2005,"genres":["Action","Platformer","Shooter"],"description":"Ratchet and Clank are captured and forced to compete on an underground reality combat sport show. The show, which features abducted heroes fighting for their lives against a gruesome gang of deadly Exterminators, is run by a deranged media mogul named Gleeman Vox, who intends to use Ratchet and Clank as his next contestants.\nIt doesn't take Vox long to realize that Ratchet is the most promising contestant the show has ever seen. Vox subjects our hero to a series of deadly battles and elaborate games of death, much to the delight of the show's enormous audience.\nTo keep himself and his friends alive, Ratchet has no choice but to participate in the games and keep driving up the show's ratings with spectacular victories - at least until our heroes can figure out a way to break free from Vox's control and bring the mighty Vox Network crashing down.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9781","developer":"Insomniac Games","coverName":"Ratchet - Deadlocked (USA) (En,Fr,Es)","players":"2","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.15,"count":109}},{"id":"we-love-katamari","title":"We Love Katamari","year":2005,"genres":["Action","Puzzle"],"description":"The quirky gameplay that captivated the world returns to roll up anything and everything that gets in your way! The King of All Cosmos grew to stardom after replacing the stars with the Prince's Katamaris. In response to this new found fame, the King is out to appease his fans with the help of the Prince and his cousins. Now they are tasked with rolling up even more clumps, each larger and more different than the one before. Roll up new objects in different objectives and experience all new levels and environments. All new creative art design, soundtrack, and 2-player co-op mode and expanded battle mode!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/14172","developer":"Namco","coverName":"We Love Katamari (USA)","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.57,"count":109}},{"id":"dragon-ball-z-budokai-tenkaichi-2","title":"Dragon Ball Z: Budokai Tenkaichi 2","year":2006,"genres":["Fighting"],"description":"Tenkaichi 2 is a fighting game with more than 120 playable characters, the biggest amount ever featured in a Dragon Ball game. The main Dragon Adventure mode follows an epic story mode that covers the first Dragon Ball Z saga (Saiyan Saga) right up to the last Dragon Ball GT saga (Dragon Saga), including all of the major battles, making it one of the most comprehensive Dragon Ball Z games.\n\nThe same battle format from the predecessor is taken, but extended with improved mechanics, including the return of the \"Planet Freedom\" feature (last seen in Dragon Ball Z: Budokai 3). There are more combat combos and in-battle transformations, all topped of with a featured encyclopedia, which covers all the most important aspects of the Dragon Ball universe.\n\nAll the characters from the previous version are present, with some new ones (there are more in the Wii version), and up to ten characters can participate in a single battle, with a tag system. The locations include those of the previous game, with some additional ones.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5542","developer":"Spike","coverName":"Dragon Ball Z - Budokai Tenkaichi 2 (USA) (En,Ja)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":4.2,"count":108}},{"id":"fatal-frame-iii-the-tormented","title":"Fatal Frame III: The Tormented","year":2005,"genres":["Adventure","Horror"],"description":"The Fatal Frame series is back. Rei Kurosawa's fiancé, Yuu Asou, dies in an ugly car accident when she is driving. She enters a haunted mansion as part of a reporting assignment. Here she is frightened by images of her dead fiancé. The game incorporates the camera mode from the previous games, used to capture ghosts. You use the camera obscura not only as a weapon to capture ghosts but as a guide by taking pictures of the ghosts and creepy objects in the house in order to solve the mystery and get rid of the curse. You walk around with a strobe light looking for clues to the mystery.\n\nThroughout the course of the game you can play as three women and switch between a dream world and real-life. All in all, it carries over the same Japanese horror theme as the first two.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7252","developer":"Tecmo","coverName":"Fatal Frame III - The Tormented (USA)","players":"1","publisher":"Tecmo","esrb":"M - Mature","rating":{"score":4.39,"count":108}},{"id":"onimusha-2-samurai-s-destiny","title":"Onimusha 2: Samurai's Destiny","year":2002,"genres":["Action"],"description":"Ten years after the lone swordsman, Samanosuke, rose up against an army of demon warriors, Nobunaga's evil campaign continues to wreak havoc across feudal Japan. A young warrior, Jubei, returns home to find his remote and once vibrant village in ruins, destroyed by Nobunaga's minions. With vengeance in his heart, Jubei launches upon an epic and magical quest, which will reveal his ultimate destiny.\n\nLike Samanoske before him, Jubei can absorb the souls of defeated monsters to strengthen his weapons and armor. Monsters can be defeated either by attacking them until their health is depleted, or by striking them at the very instant before they hit Jubei. This will make Jubei preform an Issen attack which destroys in a single blow. Jubei can find or buy treasures in the first half of the game, and give these to companions he meets, befriending them. Based on who Jubei befriends the events of the game will change.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9766","developer":"Capcom Production Studio 2","coverName":"Onimusha 2 - Samurai's Destiny (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.07,"count":108}},{"id":"klonoa-2-lunatea-s-veil","title":"Klonoa 2: Lunatea's Veil","year":2001,"genres":["Action","Platformer"],"description":"Klonoa, our floppy-eared hero, along with his two newly found buddies, Lolo and Popka, have to foil a sinister force which is causing a mire of gloom to plague the land of Lunatea. By ringing the four bells across the land, Klonoa can restore harmony, but the Sky Pirate Leorina is in hot pursuit, after Klonoa's magic ring...\n\nKlonoa 2: Lunatea's Veil is a 3D side-scrolling platformer. The main goal of the game is to get to the end of each level (or 'Vision'), but there are also special goals to achieve. Firstly, each Vision contains six Momett Dolls hidden in each level. Secondly, there are Dream Stones scattered throughout each level - green ones are worth one, while blue ones are worth five. Certain puzzles also contain tricky use of the \"Dream Spirit\", which doubles the value of all collected Dream Stones. New to Klonoa 2 are hoverboard sections, which play at a faster, more action-oriented pace.\n\nBut what makes Klonoa unique is his abilities. Klonoa can shoot a 'wind bullet' into foes, which puffs them up and allows Klonoa to carry them. Klonoa can then launch them straight at foes, or jump with them, giving him an extra boost. If he needs extra length to his jump, holding the jump button will allow him to hover for a little longer, too. Different enemies have different effects - for example, certain foes have propellers on their heads and will rocket you into the sky, while others will act like time bombs and explode after a short while.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7327","developer":"Namco","coverName":"Klonoa 2 - Lunatea's Veil (USA) (Trade Demo)","players":"1","publisher":"Namco","esrb":"E - Everyone","rating":{"score":4.15,"count":107}},{"id":"kingdom-hearts-re-chain-of-memories","title":"Kingdom Hearts Re: Chain of Memories","year":2008,"genres":["RPG"],"description":"Sora, Donald and Goofy travel down a long road that meanders through endless fields, and come to a crossroads. As Sora stands in the crossroads, he gazes up at the night sky and thinks of his lost friends. Just then, a mysterious man approaches from down one of the branching paths. \"Ahead lies something you need,\" he says, \"but to claim it, you must lose something dear.\" The man vanishes before a single path, leading to a castle that eerily resembles a girl's drawing... In the coming journey, what will Sora and his companions gain, and what will they lose? In addition to Sora, players can control Riku in this adventure that bridges the gap between KINGDOM HEARTS and KINGDOM HEARTS II A full 3D remake of the original GBA release, KINGDOM HEARTS Re:Chain of Memories offers a refreshing rendition of the hit title for the PlayStation 2 system. The talented voice cast from the North American releases of KINGDOM HEARTS and KINGDOM HEARTS II, including David Gallagher and Haley Joel Osment, return to breathe new life into the beloved characters. The mini-game catalog has been completely renewed, now with four brand new experiences accompanying the main adventure.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9324","developer":"Square Enix","coverName":"Kingdom Hearts - Re-Chain of Memories (USA)","players":"1","publisher":"Square Enix","esrb":"E - Everyone","rating":{"score":3.82,"count":106}},{"id":"baldur-s-gate-dark-alliance-ii","title":"Baldur's Gate: Dark Alliance II","year":2004,"genres":["RPG"],"description":"The threat of the Onyx Tower has passed for now, but mere moments pass before a new threat to the Sword Coast arises. The heroes of the Onyx Tower have disappeared, so the fate of Baldur's Gate now rests on the shoulders of five wandering adventurers who are only now journeying into the region.\n\nBaldur's Gate: Dark Alliance II can be played solo or cooperatively with one other player, each choosing from 5 playable characters. The gameplay is the same as its previous incarnation: kill monsters and bad guys to collect treasure, items, and experience. By talking to townspeople in Baldur's Gate the player can learn of optional maps filled with more dangerous monsters and additional treasure. Equipment can be enchanted by the player this time, and given various magical effects such as additional fire damage, absorbing mana, or boosting stats.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5899","developer":"Black Isle Studios","coverName":"Baldur's Gate - Dark Alliance II (USA)","players":"2","publisher":"Interplay Entertainment","esrb":"T - Teen","rating":{"score":4.34,"count":106}},{"id":"darkwatch","title":"Darkwatch","year":2005,"genres":["Horror","Shooter"],"description":"Darkwatch is a first-person shooter set in the Wild West with supernatural beings. Fight your way through reapers, undead riflemen, banshees and other creatures using Darkwatch weaponry that doubles as melee weapons, such as a revolver, two-fisted pistols, a crossbow (with dynamite attached to the bolts) and a Rail Rocket. You will also find dynamite along the way to throw at the enemy and to destroy barricades. Along with conventional weapons, Cross will acquire vampire powers of good or evil nature that you must choose in the story. If you decide to be good, then you receive powers such as Silver Bullet that increases your shots with holy fire or Vindicator that calls down chain lightning on your enemies. If you choose to be evil, you will receive Blood Frenzy that makes melee attacks supernaturally powerful and Soul Stealer, which sucks the very souls from distant enemies. Regardless of good or evil, you will always have Blood Shield (protection from losing health), Vampire Jump (for those hard to reach areas) and Blood Vision (causes enemies, weapons and other important objects to glow). With every creature killed, there will be at least one Blood Cloud and sometimes more to replenish your health and restore your Vampire Powers.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7202","developer":"High Moon Studios","coverName":"Darkwatch (USA)","players":"2","publisher":"Capcom","esrb":"M - Mature","rating":{"score":3.92,"count":104}},{"id":"urban-reign","title":"Urban Reign","year":2005,"genres":["Beat 'em up"],"description":"Urban Reign is a Namco-produced 3D brawler, done in the tradition of Double Dragon and Final Fight. The story follows Brad Hawk, a hired thug, as he tries to find a gang member that was captured by a rival group. In each level, you set off against a handful of bruisers from one of Green Harbor's many gangs in search of clues. Make use of different allies, which can be given instructions, with skills in various fighting techniques to accomplish your goals, as you fight your way through 100 levels. There are different combos and special moves, different objects can be picked up and used as a weapon, and incoming attacks can be avoided by dodging.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9836","developer":"Namco","coverName":"Urban Reign (USA)","players":"4","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.32,"count":104}},{"id":"timesplitters-2","title":"TimeSplitters 2","year":2002,"genres":["Shooter"],"description":"In TimeSplitters 2 the evil race of TimeSplitters are travelling back into human history, authoring events that are leading to the enslavement of mankind. Controlling a motley crew of renegade characters, you must hunt them down across environments such as the gangster-filled 1920s, the temples and lush jungles of the Aztecs, Soviet military installations of the Cold War and futuristic robot-factories in space.\n\nTimeSplitters 2 delivers involved single-player and cooperative story modes; it has a complex narrative, multiple objective-based episodes and animated cut-scenes. The game engine has been extensively upgraded to accommodate bigger environments and special graphic effects, and the MapMaker has been enhanced, giving more options to the advanced gamer looking for customisable game scenarios.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3878","developer":"Free Radical Design","coverName":"TimeSplitters 2 (USA)","players":"4","publisher":"Eidos Interactive","esrb":"T - Teen","rating":{"score":4.47,"count":104}},{"id":"the-lord-of-the-rings-the-return-of-the-king","title":"The Lord of the Rings: The Return of the King","year":2003,"genres":["Action","Adventure"],"description":"The Lord of the Rings: Return of the King video game again puts the fate of middle-earth in the hands of the gamer. In the last installment of the movie trilogy, destroy the Ring by casting it into the Crack of Doom, which frees Middle Earth from Dark Lord Sauron.\n\nReturn of the King's third person gameplay allows immersive action set in rich, interactive levels. The new game also features an all new co-op multiplayer mode which lets players form their own Fellowship and eight playable characters like Gandalf, Aragorn, Legolas, Gimil, Sam and Frodo all played out by thier actual actors from the films, battle vicious boss monsters like Shelob and the final showdown with Dark Lord Sauron, all backed up by Academy Award winner Howard Shore.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7455","developer":"Electronic Arts Redwood Shores Studio","coverName":"Lord of the Rings, The - The Return of the King (USA)","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.2,"count":103}},{"id":"the-bouncer","title":"The Bouncer","year":2000,"genres":["Beat 'em up","RPG"],"description":"Play the Action Movie\n\nSion is a bouncer in a Dog Street bar called 'Fate'. An organized kidnapping by the Mikado Group's special forces draws Sion and his friends into an increadible battle beyond the mean street of the future.\n\n* Experience action, adventure, fighting, and RPG elements woven together in ways you've never seen before\n* Play through the game multiple times, controlling different fighters to discover the entire story and unlock new characters\n* Use team attacks and special moves to take on multiple attackers in giant brawls\n* Hone your skills with multiple fighting modes, including 1-4 player versus mode\n* Discover a complex story detailed with spectacular visuals and effects","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5914","developer":"Dream Factory","coverName":"Bouncer, The (USA) (En,Ja)","players":"4","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":3.54,"count":103}},{"id":"silent-hill-shattered-memories","title":"Silent Hill: Shattered Memories","year":2009,"genres":["Adventure","Horror"],"description":"Billed as a re-imagining of the original Silent Hill, Shattered Memories once again casts you as Harry Mason searching across the haunted town for his missing daughter Cheryl. New to the series are a depiction of Silent Hill's demonic alter-dimension as a world of ice, and the removal of weapons from the game - when the monsters come out, Harry must literally run for his life.\n\nBetween scenes, the game will cut to a psychiatrist's office, who asks you personal questions about yourself and your past experiences. The game will then alter itself based on your responses, changing characters and lines of dialog to something intended to be more personally uncomfortable.\n\nAs you search for Cheryl, you will come across objects and recordings that tell some of the history of Silent Hill.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7632","developer":"Climax Studios","coverName":"Silent Hill - Shattered Memories (USA) (En,Fr,Es)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":3.78,"count":102}},{"id":"hack-g-u-vol-2-reminisce","title":".hack//G.U. Vol. 2: Reminisce","year":2007,"genres":["RPG"],"description":"The second release in a series of three, .hack//G.U.: Vol. 2 -- Reminisce takes place in a fictional MMO environment called The World. As in previous releases of .hack, The World features elements of online gaming without the actual connection. Gamers interact with people they might find in a real MMO, take on quests, and adventure across a large environment as they increase their level. \n\nIn this version of The World, gamers find the once-utopian landscape is now a player killer's (PKers) heaven. A bug in the game is blocking the log-off ability to all fictional gamers; effectively locking them into The World. Now, bands of PKers prey on every character in their path hoping that the slaughter knocks them out of the game and back into real life. \n\nGamers take the role of Haseo, a killer of players who is stuck in the game. Haseo must work his way through The World by interacting with other character, defeating enemies in dungeon sprawls, and by completing assigned objectives. Navigation through the game requires the use of Warp points located around the map.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12791","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Namco Bandai","esrb":"T - Teen","rating":{"score":3.54,"count":101}},{"id":"007-everything-or-nothing","title":"007: Everything or Nothing","year":2004,"genres":["Adventure","Shooter"],"description":"The gameplay is a mix of third-person shooting/action sequences and vehicle sequences. In third-person, Bond can move, take cover, aim and shoot with a lock-on system, engage in hand-to-hand combat, use his spy gadgets and perform some context sensitive actions. The lock-on system has a precision aiming dot that can be moved with the right thumb stick to target specific areas of the body. It does not snap to said specific areas making it possible to completely miss your target.\n\nA unique feature, \"Bond sense\", allows you to see the world how Bond does, allowing you to spot things that Bond can interact with. Using Bond sense slows down time so the player may have a chance to spot objects or enemies, but the player cannot move or take action without deactivating Bond sense.\n\nTwo players can play through a co-op campaign that uses some areas from the single player campaign but adds unique scenarios and maps to the mix.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4760","developer":"Electronic Arts Redwood Shores Studio","coverName":"007 - Everything or Nothing (USA)","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.04,"count":101}},{"id":"bloody-roar-4","title":"Bloody Roar 4","year":2003,"genres":["Fighting"],"description":"During the XGC (X-Genome Code) Incident one year ago, riots raged over the earth by beasts that did not show the XCG, and all over the country small earthquakes shook the land. The cause was unknown, but as the Crest Incident came to an end and the rioting and earthquakes subsided, people began to claim that all was due to the influence of the Stone Seal. Although the Stone Seal has been locked away, the rioting and earthquakes have returned. This time, the incidents are on a larger scale than those of a year ago. What could be behind it all?\n\nBloody Roar 4 is the last title in the series, and is once again a full-3D fighting game featuring the series' trademark transformation abilities. Unlike previous titles in the series, the beast gauge now acts as its own health bar; if a character's health gauge is depleted, they will automatically transform. The game features 18 playable fighters and a variety of game modes, including standard arcade, versus, time-attack, training, and survival modes. Of special mention is the career mode, in which fighting battles will earn so-called \"DNA points,\" which can be spent on abilities and equipment to customize a character for use in other modes.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9634","developer":"Hudson Soft","coverName":"Bloody Roar 4 (USA)","players":"2","publisher":"Hudson Soft","esrb":"M - Mature","rating":{"score":4.04,"count":101}},{"id":"r-type-final","title":"R-Type Final","year":2003,"genres":["Shooter"],"description":"In R-Type Final, your enemy is the Bydo, an evil (and living) weapon capable of reproducing itself. Humanity has fought the Bydo four times so far, and each time was victorious. \nHowever, each time the Bydo appears it is stronger than before, and now it's back and you need to destroy it again! Like other games in the R-Type Series, the game is a scrolling shooter where you need to guide a spaceship through various stages and destroy the many enemies (including very large end of level bosses). \nThe game features a large variety of spaceships (over 100!) to choose from, each with varying capabilities. Regardless of which ship you choose, you begin the game with limited firepower; you can fire a basic weapon, or hold down a button to charge up and fire a more powerful burst. Occasionally power ups will appear on the screen; collect these to equip your ship with additional weapons, including a variety of lasers, missiles, and other useful items. In addition to the normal game, an AI VS mode is also included. In this mode, you can set up one of your available fighters to be controlled by the computer and then fight it to see who wins in various battles.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5390","developer":"Irem","coverName":"R-Type Final (USA)","players":"1","publisher":"Eidos Interactive","esrb":"E - Everyone","rating":{"score":4.09,"count":101}},{"id":"ridge-racer-v","title":"Ridge Racer V","year":2000,"genres":["Racing"],"description":"Experience all-new race car excitement on the powerful PlayStation 2 computer entertainment system with Ridge Racer V. Namco delivers its phenomenal racing series with more energy, bigger thrills and superb gameplay.\n\nThe asphalt of Ridge City is once again thundering with high-speed action and palm-sweating competition. The checkered flag is flying and so are the cars. Amazingly detailed visuals, from the glowing of heated brake pads to the smoldering of tires in a power-slide, will have you captivated as the battle for supremacy races on. It's all about speed, power, and control. With Ridge Racer V, your search for unforgiving racing intensity is over.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4795","developer":"Namco","coverName":"Ridge Racer V (USA)","players":"2","publisher":"Namco","esrb":"E - Everyone","rating":{"score":3.84,"count":101}},{"id":"rogue-galaxy","title":"Rogue Galaxy","year":2007,"genres":["RPG"],"description":"At the far edge of the galaxy lies the desert planet of Rosa, home to Jaster, a buccaneering young pirate who dreams of journeying through space. Now, Jaster's dreams are about to come true. One day a huge beast appears in his town on Rosa and begins attacking the locals. Jaster rushes to protect the citizens, but is set upon by further strange creatures. As he fights the beasts, a mysterious man who calls himself Desert Claw appears and aids him in the battle. Unbeknownst to Jaster, two people are watching the fight; Simon and Steve, the subordinates of the Space Pirate Dorgengoa. Simon and Steve are so impressed with Jaster’s skills that they offer him a chance to join Dorgengoa’s band. Jaster accepts their offer and, as he joins the crew of the space galleon Dorgenark, he embarks on a voyage across the solar system. It promises to be a quest to discover new worlds and to solve an epic mystery that holds the key to the greatest treasure in the Galaxy…","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9350","developer":"Level-5","coverName":"Rogue Galaxy (USA)","players":"1","publisher":"Sony Computer Entertainment","esrb":"T - Teen","rating":{"score":4.19,"count":100}},{"id":"haunting-ground","title":"Haunting Ground","year":2005,"genres":["Horror"],"description":"Haunting Ground is a horror game that centers around avoiding combat and escaping from your enemies. Fiona can fight, but usually she is too weak to defeat her foes in combat, so she will have to run away, hide, and use items as distraction until the enemy loses sight of her and she is able to continue exploring. The most important gameplay tool is your dog. You can issue commands to the dog, telling him to scout a room for you, warn you of upcoming enemies, defend you in battle, pick up items, etc. The dog will obey or disobey you depending on how you develop your relationship with him. If you are nice to the dog, pet him and give him food, he will follow your commands more efficiently.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9710","developer":"Capcom","coverName":"Haunting Ground (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":4.08,"count":100}},{"id":"street-fighter-ex3","title":"Street Fighter EX3","year":2000,"genres":["Fighting"],"description":"Capcom's legendary fighting series launches a new generation in Street Fighter EX3\nAwe-inspiring realism and unbelievable graphics bring the world of Street Fighter to life in this amazing tag-team free-for-all\n\n- The legendary fighting series meets the power of the PlayStation 2 computer entertainment system\n\n- Unbelievable tag-team battles with 16 playable characters\n\n- 4 Modes of play - Original, Arena, Character Edit and Training\n\nChoose from 16 characters to play 1-on-1, 2-on-1 and even 1-on-3 battles! Loaded with 4 modes of play and new enhancements like the Critical Parade and Emotional Flow Super Moves, Street Fighter EX3 is the champion of tag-team fighting","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/17304","developer":"Arika","coverName":"Street Fighter EX3 (USA)","players":"2","publisher":"Capcom","esrb":"T - Teen","rating":{"score":3.69,"count":100}},{"id":"shadow-hearts-covenant","title":"Shadow Hearts: Covenant","year":2004,"genres":["RPG"],"description":"Shadow Hearts: Covenant is a role-playing video game developed by Nautilus (Sacnoth) for the PlayStation 2, and is the second entry in the Shadow Hearts series. Published in Japan by Aruze in 2004, the game was released internationally by Midway Games in 2004 (North America) and 2005 (Europe). A director's cut with additional content was released in Japan in 2005.\n\nCovenant takes place in 1915, six months after the events of the first game. At the height of World War I, German Army lieutenant Karin Koenig is drawn into a conflict between original protagonist Yuri Hyuga and the secret society Sapientes Gladio. During gameplay, the player explores various locations through a growing party of characters. Four characters take part in turn-based battles against a variety of enemies, with actions relying on a timing-based system dubbed the Judgement Ring. The game's worldview combines alternate history with elements of Lovecraftian horror.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12758","developer":"Nautilus","coverName":"Shadow Hearts - Covenant (USA) (Disc 1)","players":"1","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":4.22,"count":99}},{"id":"silent-hill-origins","title":"Silent Hill: Origins","year":2008,"genres":["Adventure","Horror"],"description":"Silent Hill: 0rigins is a prequel to the Silent Hill series set in the 1970s. You play as trucker Travis Grady, who attempts to take a shortcut through Silent Hill late one night when running behind on his rounds.\n\nAs in the previous Silent Hill games, you move back and forth between nightmare and real versions of the town, here crawling through mirrors to get between. He must gather items used to solve puzzles and open up new areas. Monsters of various types provide obstacles and, in series tradition, are mostly disturbingly twisted versions of humanity.\n\nTravis can fight with his bare fists or use melee weapons. Unlike previous games in the series, melee weapons break after a time. There are also one-shot items that can be thrown and several guns. Combat is performed through lock-on. There is no HUD, but the edge of the screen turns red when Travis is near death.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12892","developer":"Climax Solent","coverName":"Silent Hill Origins (USA) (En,Fr,De,Es,It)","players":"1","publisher":"Konami Digital Entertainment","esrb":"M - Mature","rating":{"score":3.96,"count":98}},{"id":"max-payne","title":"Max Payne","year":2001,"genres":["Shooter"],"description":"A man with nothing to lose in the violent, cold urban night. A fugitive undercover cop framed for murder, and now hunted by cops and the mob. Max is a man with his back against the wall, fighting a battle he cannot hope to win. Prepare for a new breed of deep action game. Prepare for pain…\n\nThis stylish, urban, revenge-driven action game is set in New York's grimy underground. Max Payne is an original third-person 3D game based on the groundbreaking MAX-FX engine, and uses photo-digitized textures and radiosity lighting, resulting in heart-stopping, photo-realistic visuals and breath taking movie-quality effects as Max Payne fights his way to uncover the truth.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4170","developer":"Remedy Entertainment","coverName":"Max Payne (USA)","players":"1","publisher":"Electronic Arts","esrb":"M - Mature","rating":{"score":4.12,"count":98}},{"id":"mega-man-x8","title":"Mega Man X8","year":2005,"genres":["Platformer","Shooter"],"description":"In the late 22nd century, humans have commenced a construction of an orbital elevator to the Moon. A Reploid named Lumine was put in charge of the project. Lumine belonged to the new generation of Reploids, which were apparently unable to become Mavericks (i.e. turn hostile towards humans). Soon thereafter, Lumine was kidnapped by unknown assailants. The team of Maverick Hunters, composed of X, Axl, and Zero, must pursue the abductors and find what they were truly after. However, they will also have to deal with familiar enemies from the past...\n\nMega Man X8 is similar in visual style to earlier Mega Man X games, moving away from the 3D gameplay elements introduced by its predecessor. As in classic Mega Man games, the player is free to tackle the levels in any order, and must defeat a boss at the end of each. The player is able to control X, Axl, and Zero, which are distinguished by their gameplay style: X is able to equip body parts and armor, Axl specializes in guns and can also hover and glide in the air, while Zero focuses on short-range attacks.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7363","developer":"Capcom","coverName":"Mega Man X8 (USA)","players":"1","publisher":"Capcom","esrb":"E - Everyone","rating":{"score":3.65,"count":97}},{"id":"legacy-of-kain-defiance","title":"Legacy of Kain: Defiance","year":2003,"genres":["Action","Adventure"],"description":"Defiance continues the journey of the Vampire lord Kain and his lieutenant-turned-wraith Raziel. After having Raziel killed to be revived by the Elder God as a wraith during the events of Legacy of Kain: Soul Reaver, Kain travels backwards through time and is followed by Raziel into Nosgoth's past, uncovering the conspiratorial events that led to the land being doomed to an eternity of corruption. After establishing his free will by refusing to kill Kain when prophesied, Raziel discovers that Moebius the Timestreamer had originally manipulated Kain into igniting a genocidal war against Vampires until he was the last of his kind. In manipulating Raziel who has free will and thus whose decisions and actions cannot be foreseen by Moebius, Kain hopes to find a way to undo the consequences of his actions and restore Nosgoth to its former glory.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4837","developer":"Crystal Dynamics","coverName":"Legacy of Kain - Defiance (USA)","players":"1","publisher":"Eidos Interactive","esrb":"M - Mature","rating":{"score":3.99,"count":97}},{"id":"crash-of-the-titans","title":"Crash of the Titans","year":2007,"genres":["Beat 'em up","Platformer"],"description":"This version is different from its DS and GBA versions. The story has Crash's arch-nemeses, Neo and Nina Cortex, creating a device that turns the creatures on Crash's island into monsters, threatening to bring an end to existence on the peaceful island. Crash must stop them by \"hijacking\" these monsters and wield their power against the Cortex's.\n\nThe gameplay has the player explore levels, picking up power-ups to use against enemies as well as for the first time, use fighting combos such as punches and kicks against enemies. Players can also \"hijack\" 15 different enemy monsters to use against the others, each with their own special abilities and powers like fire breathing and earthquakes. Players can also interact with their world, climbing trees and swinging from ropes and even surf and skate throughout the levels. There is also co-op abilities where a friend can pop into the game at any point.\n\nThe games across are almost identical, excluding controls (the Wii utilizes the Wii-remote) and graphics are different depending on the systems graphics capabilities.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5384","developer":"Radical Entertainment","coverName":"Crash of the Titans (USA)","players":"2","publisher":"Sierra Entertainment","esrb":"E10+ - Everyone 10+","rating":{"score":3.84,"count":96}},{"id":"star-ocean-till-the-end-of-time","title":"Star Ocean: Till the End of Time","year":2003,"genres":["Action","RPG"],"description":"An attack from an unknown power in space threatens the peace between humans and aliens. The attack forces Fayt Leingod and his friend Sophia Esteed to separate from Fayt's parents and flee from the planet. Now it's up to you to guide these two characters through a variety of side quests and sub-events to find their loved ones. Dress your characters, equip them with weapons, and then conquer the land. Up to three characters can fight and move together on the battlefields.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7973","developer":"tri-Ace","coverName":"Star Ocean - Till the End of Time (USA) (Disc 1)","players":"2","publisher":"Square Enix","esrb":"T - Teen","rating":{"score":4.17,"count":96}},{"id":"virtua-fighter-4-evolution","title":"Virtua Fighter 4: Evolution","year":2003,"genres":["Fighting"],"description":"Evolution was an updated version of Virtua Fighter 4. The game introduced two new characters and adjusted every other character as well. The two new characters were the Judoka-assassin, Goh Hinogami and the Muay Thai boxer Brad Burns. With the addition of Brad Burns, Vanessa Lewis's alternate Muay Thai style from Virtua Fighter 4 was removed and replaced with a Vale Tudo \"Offensive\" style; making her a solely Vale Tudo brawler.\n\nAll of the stages were adjusted. For example, Lei-Fei's stage in Virtua Fighter 4 previously took place during sunset, in Evolution it takes place during the morning.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5633","developer":"Sega","coverName":"Virtua Fighter 4 - Evolution (USA)","players":"2","publisher":"Sega","esrb":"T - Teen","rating":{"score":4.09,"count":95}},{"id":"yakuza-2","title":"Yakuza 2","year":2006,"genres":["Action","RPG","Sandbox"],"description":"One year has passed since Kazuma Kiryu, \"yakuza with the heart of gold\", defeated his biggest adversary in the previous game. Despite this victory, Kazuma has lost more than he had ever imagined. \n\nBut events from the past continue to haunt him. A man he had admired so much, who was like a father to him, has revealed a terrible secret before he died. It's time for Kazuma to solve the mystery once and for all. Caught in the eternal fight between Kantou and Kansai, the Eastern and the Western organized crime groups of Japan, he soon realizes that there are other powers on the stage, including a mysterious Korean organization that seems to be connected somehow to his past.\n\nThe sequel to Yakuza continues the story from the previous game, featuring many recurrent characters. The main gameplay idea also remains the same - on-foot exploration of urban environments, hand-to-hand fighting, and role-playing elements, somewhat similar to the kind of gameplay that was introduced in Shenmue games. The sequel features some technical improvements, such as the ability to rotate the camera during the fights. It also contains more side missions and mini-games, ranging from playing pool and mahjong to running a club and dating women.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3921","developer":"Sega","coverName":"Yakuza 2 (USA)","players":"1","publisher":"Sega","esrb":"M - Mature","rating":{"score":4.47,"count":94}},{"id":"crash-tag-team-racing","title":"Crash Tag Team Racing","year":2005,"genres":["Racing"],"description":"When Ebeneezer von Clutch, the owner of the famed racetrack amusement park MotorWorld, has the Black Power Gem that maintains his life force stolen, he charges Crash and friends (and foes) to recover the gem and catch the culprit.\n\nSimilar to previous racing games in the Crash Bandicoot series, players are able to choose from a variety of characters from the series, including both notable allies and enemies, along with several notable new characters. In addition, Crash Tag Team Racing introduces the ability to 'clash' with another racer, allowing the two to create a hybrid vehicle to cooperatively destroy their opponents.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9872","developer":"Radical Entertainment","coverName":"Crash Tag Team Racing (USA)","players":"8","publisher":"Sierra Entertainment","esrb":"E10+ - Everyone 10+","rating":{"score":3.94,"count":94}},{"id":"shinobi","title":"Shinobi","year":2002,"genres":["Adventure","Beat 'em up"],"description":"Ignite the fiery vengeance of Hotsuma, the last of the Oboro clan. Scale walls and slash your way through the demon-filled streets of post-apocalyptic Tokyo. But beware, you'll have to keep your bloodthirsty sword satisfied or sufferits deadly curse yourself.\n\nChain attacks together to destroy hordes of enemies\nWall run to explore secret areas\nUnleash devastating Ninja Magic\nStealth dash to confuse enemies with ghost images","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4775","developer":"Overworks","coverName":"Shinobi (USA) (En,Ja)","players":"1","publisher":"Sega","esrb":"M - Mature","rating":{"score":3.89,"count":94}},{"id":"burnout","title":"Burnout","year":2001,"genres":["Racing"],"description":"Burnout is a arcade style racing game in the mold of the Test Drive or Need For Speed series. In this game, you are racing on realistic streets with real traffic to contend with.\n\nThere are 6 courses on which to race, 3 of which are reminiscent of Europe, and 3 from the USA. There are several vehicles to choose from, ranging from compact cars to pickups. However, they are not based on real makes and models.\n\nOne notable feature of Burnout is the \"Burn Meter.\" The Burn Meter is a gauge that is filled by performing reckless stunts, like racing into oncoming traffic, or power-drifting through corners. Once the Burn Meter is filled, your car gets a super speed boost.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9638","developer":"Criterion Software Group","coverName":"Burnout (USA) (Trade Demo)","players":"1","publisher":"Acclaim Entertainment","esrb":"E - Everyone","rating":{"score":3.74,"count":94}},{"id":"champions-of-norrath","title":"Champions of Norrath","year":2004,"genres":["Action","RPG"],"description":"Champions of Norrath is a third-person dungeon crawler based on the EverQuest universe. There are five character classes to choose from (Barbarian Warrior, Wood Elf Ranger, High Elf Cleric, Dark Elf Shadow Knight, Erudite Wizard), each may be male or female. The game spans five acts that cover various randomly-generated locations across the world of Norrath.\n\nUp to four people may play on a single console offline using a multitap, and up to four people online - one per console - via a broadband connection using the Sony Network Adapter.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5923","developer":"Snowblind Studios","coverName":"Champions of Norrath (USA)","players":"4","publisher":"Sony Online Entertainment","esrb":"T - Teen","rating":{"score":4.46,"count":93}},{"id":"maximo-vs-army-of-zin","title":"Maximo vs. Army of Zin","year":2004,"genres":["Action","Adventure","Platformer"],"description":"MAXIMO IS BACK\nAND THIS TIME IT'S WAR!\n\nDriven by the souls of the dead, the Army of Zin declared war on the living.\n\nOnly Maximo can rise against the onslaught of ruthless, clockwork warriors. Travel vast lands, save the Innocent Villagers, battle the Zin with destructive new weapons AND command the invincible power of Grim!\n\nBe A True Hero And Rescue The Innocent Villagers\n\nMaster An Arsenal Of Devastating Combos And Attacks\n\nPower Up And Transform To Unleash The Terrifying Power Of Grim","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/8773","developer":"Capcom Production Studio 8","coverName":"Maximo vs Army of Zin (USA)","players":"1","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.17,"count":93}},{"id":"tenchu-wrath-of-heaven","title":"Tenchu: Wrath of Heaven","year":2003,"genres":["Action","Adventure","Stealth"],"description":"Follow the path of the Ninja. Tenchu 3: Wrath of Heaven, the latest chapter in the Tenchu series, allows you to take on the role of three merciless assassins, with over 20 authentic ninja weapons and tools. Experience the all-new stealth attacks, combos, and enhanced fighting engine as you complete mission objections, including espionage, theft, and assassination. The more stealth kills you get, the more abilities and combos you earn. Can you master the action-packed gameplay and unlock the multiple game endings?","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/13122","developer":"K2 (Japan)","coverName":"Tenchu - Wrath of Heaven (USA) (En,Ja)","players":"2","publisher":"FromSoftware","esrb":"M - Mature","rating":{"score":4.35,"count":93}},{"id":"zone-of-the-enders-the-2nd-runner","title":"Zone of the Enders: The 2nd Runner","year":2003,"genres":["Shooter"],"description":"The game begins with Dingo Egret, the protagonist, working at a mining facility on Callisto. He inadvertently discovers the Orbital Frame, Jehuty, that was hidden there by Leo. When he is attacked by BAHRAM forces who have come to seize it, Dingo climbs into Jehuty and engages the attackers. During the battle, Dingo enters the BAHRAM battleship, seemingly defeating Nephtis, an Orbital Frame controlled by an A.I. program based on Viola's fighting style, but is subdued by Anubis, Jehuty's superior counterpart controlled by Col. Ridley (Nohman) Hardiman, leader of BAHRAM.\n\nAs a prisoner, Dingo is assaulted by Ken Marinaris, a female Orbital Frame runner that Dingo defeated in the previous battle. Nohman arrives moments later and asks Dingo to join him. When Dingo refuses, Nohman shoots him, ordering Ken to dispose of the body. Instead, Ken has Dingo revived and placed inside Jehuty. When he comes to, she explains that Jehuty is acting as a life-support system, and if he leaves Jehuty, he will die. She then tells him that she is a UNSF spy. Dingo escapes with Taper and heads for Mars.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3939","developer":"Konami Computer Entertainment Japan","coverName":"Zone of the Enders - The 2nd Runner (USA)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.13,"count":93}},{"id":"half-life","title":"Half-Life","year":2001,"genres":["Shooter"],"description":"In Half-Life, players assume the role of Dr Gordon Freeman, a recently graduated theoretical physicist who must fight his way out of a secret underground research facility, whose research and experiments into teleportation technology have gone disastrously wrong.\n\nThe Co-Op mode in the game is actually a separate mission pack called the Decay Missions.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3937","developer":"Gearbox Software","coverName":"Half-Life (USA)","players":"2","publisher":"Sierra On-Line","esrb":"M - Mature","rating":{"score":4.1,"count":93}},{"id":"time-crisis-ii","title":"Time Crisis II","year":2001,"genres":["Shooter"],"description":"Play alone or team up with a friend in this traditional light gun shooter.\nChristy Ryan, the agent responsible for uncovering the corporation's hidden agenda, attempts to escape NDI captivity and report the details of the plot to V.S.S.E. HQ, but is captured by Jakov Kinisky and his bodyguards. V.S.S.E. sends agents Keith Martin and Robert Baxter to shut down the Starline Network and rescue Ryan.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4179","developer":"Namco","coverName":"Time Crisis II (USA)","players":"2","publisher":"Namco","esrb":"T - Teen","rating":{"score":4.19,"count":93}},{"id":"naruto-shippuden-ultimate-ninja-5","title":"Naruto Shippuden: Ultimate Ninja 5","year":2009,"genres":["Action","Fighting"],"description":"Naruto Shippuden: Ultimate Ninja 5, known in Japan as \"Naruto Shippuden: Narutimate Accel 2\", features 62 characters and continues the Naruto Shippuden storyline, going up to the end of Sasuke and Sai arc, following the manga (the anime have not done on the arc by then). One of the new gameplay additions is the introduction of assist characters. Assist characters are chosen during character selection, and can be called in during a match to deal extra damage. Certain combinations of characters create unique jutsus in a match; these combinations reflect the associations of those characters in the anime and manga. Many of the character's jutsus from the previous game were updated. There are many updated ultimate jutsus, including the aforementioned assist-specific ones. Summons have been removed from the game. The assist characters cannot be turned off. The game retains the RPG mode from previous game, now allowing the player to control characters other than Naruto (such as Sakura and Kakashi). However, the Hero's History mode that retells the events of the original series have been discarded, though the characters itself remain in the game. It was also the last of the Ultimate Ninja Series for the PlayStation 2. The game was not released in North America.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/18137","developer":"Cyberconnect2","coverName":"Naruto Shippuden - Ultimate Ninja 5 (Europe) (En,Fr,De,Es,It)","players":"2","publisher":"Bandai Namco Games","esrb":"Not Rated","rating":{"score":4.1,"count":92}},{"id":"resident-evil-outbreak-file-2","title":"Resident Evil: Outbreak: File #2","year":2004,"genres":["Action","Horror"],"description":"Raccoon City has been infected by the Umbrella corporations deadly T-Virus. A mutagenic toxin that turns its human victims into flesh eating zombies. The few survivors must try to escape the city before the government deploys its final solution to the problem of Raccoon City...\n\nOnce again you find yourself playing the eight characters of the original Resident Evil: Outbreak in more scenarios set in the ruins of what used to be Raccoon City.\n\nThe new game has several new scenarios and boasts new gameplay developments for the Resident Evil series. Loading times have been reduced and while the previous Outbreak was on-line enabled in the US, this game is the first on-line Resident Evil game in Europe.\n\nThe locals featured in this game include both the familiar (The Raccoon Police Department) and the exotic (A mutated jungle at mid-day) ones. The game boasts a hefty amount of unlockable material such as artworks, notes, trivia, and character costumes. The game is backwards compatible with your save file from Resident Evil: Outbreak, meaning that you can take your unlocked content to this new setting.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3947","developer":"Capcom Production Studio 1","coverName":"Resident Evil - Outbreak - File 2 (USA)","players":"4","publisher":"Capcom","esrb":"M - Mature","rating":{"score":3.97,"count":92}},{"id":"tony-hawk-s-underground-2","title":"Tony Hawk's Underground 2","year":2004,"genres":["Sports"],"description":"The gameplay in Tony Hawk's Underground 2 is similar to that of previous Tony Hawk games: the player skates around in a 3D environment modeled after various cities and attempts to complete various goals. Most goals involve skating on or over various objects or performing combos. Scores are calculated by adding the sum of the point value of each trick strung together in a combo and then multiplying by the number of tricks in the combo","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9309","developer":"Neversoft Entertainment","coverName":"Tony Hawk's Underground 2 (USA)","players":"2","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":4.13,"count":92}},{"id":"call-of-duty-3","title":"Call of Duty 3","year":2006,"genres":["Shooter"],"description":"The single player is modeled after the Normandy breakout, where the British, Canadian, Polish, American and French Resistance forces pushed into the village of Chambois, France, also known as the Falaise Gap. Unlike most other games in the Call of Duty series, the events in Call of Duty 3 are based on a single combined campaign, with the player being switched between the four nations and their respective characters for each leg of the story. There are 14 campaign missions.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5638","developer":"Treyarch","coverName":"Call of Duty 3 (USA)","players":"4","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":3.95,"count":91}},{"id":"killzone","title":"Killzone","year":2004,"genres":["Shooter"],"description":"The game is set in an era of space colonization where the Helghast Empire has recovered from its defeat in the First Helghan War and launched a blitzkrieg against the outer Interplanetary Strategic Alliance (I.S.A.) colony planet Vekta. Vekta's orbital Strategic Defense (S.D.) platforms failed during the initial assault, allowing the Helghast to land swarms of soldiers onto the surface and making it all the more difficult for the outnumbered I.S.A. forces.\nIn the game, the Helghast are a faction of human descendants who colonized the planet Helghan many generations ago. The planet's harsh environment forced the Helghast to adapt and mutate so much that they can no longer be considered human. They are stronger, faster and more resilient than their human cousins, and possess a burning hatred for humanity. Except for a small number of half-breed Helghast and trained troopers, they require a gas mask and air processing tank that creates air similar to that found on the planet Helghan.\nThe player takes control of I.S.A. Captain Jan Templar, who is fighting off the Helghast invasion. Templar and his squad are called back to the base for reassignment, and are promptly sent to find the I.S.A. operative Gregor Hakha and the information in his possession. During the course of the game, the player also takes control of several other characters, such as Shadow Marshal Luger (a female special operations assassin), a heavy weapons specialist Staff Sergeant Rico Velasquez (a Helghast-hating soldier with an itchy trigger finger), and Colonel Hakha, a half-Helghast, half-Human spy.\n\nAs the game progresses the player discovers that General Stuart Adams, a high ranking ISA officer, is a traitor and a servant of Joseph Lente (the commanding General of The Third Helghast Special Forces Army) and was responsible for sabotaging the SD platforms, rendering them unable to defend against the Helghast. The Earth Defense Fleet (EDF) go to assist the Vektan Army, however Adams kills General Voughton and receives his security key, allowing him to reboot the platforms, and prepare an ambush for the EDF relief force.\nJan and the others confront Lente, only to find out that Hakha was a commander in chief for him. Lente says that Hakha's family was ashamed to even be related to him, except his brother who talked of his heroism. Because of this, Lente had Hakha's brother shot down. With anger in his eyes, Hakha shoots Lente dead.\nThe team fly to the central SD platform and confront Adams, who is wounded by Templar. The platform begins to break up and Adams is killed by falling debris while trying to escape. Finally, the team restore the SD platform, allowing the EDF fleet to fight off the Helghast.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/35","developer":"Guerrilla","coverName":"Killzone (USA)","players":"16","publisher":"Sega","esrb":"M - Mature","rating":{"score":3.87,"count":91}},{"id":"dragon-ball-z-budokai-2","title":"Dragon Ball Z: Budokai 2","year":2003,"genres":["Fighting"],"description":"The time has come to go beyond the Dragon Ball Z sagas and experience the full force of the most powerful fighters in the universe. Dragon Ball Z: Budokai 2 will challenge players like no other DBZ game before. Begin with an all-new single player \"Dragon World\" that opens the story to new match-ups, surprising character appearances, and missions that will amaze. You can also battle your friends in multiplayer \"VS.\" and \"Tournament\" modes. If your will and skill prevail, you will come face-to-face with Buu, the most lethal of all DBZ villains. Featuring cell-shaded animation, utterly devastating \"Ki\" energy attacks, and destructible environments, DBZ: Budokai 2 is ready to drop your jaw. Unleash the fury of the most powerful fighters in the universe!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/19743","developer":"Dimps","coverName":"Dragon Ball Z - Budokai 2 (USA)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":3.79,"count":90}},{"id":"nba-street-vol-2","title":"NBA Street Vol. 2","year":2003,"genres":["Sports"],"description":"Basketball returns to the streets in NBA Street Vol. 2, featuring more players, electrifying moves, and online multiplayer battles. Defeat the best players in the game today and even bring legends such as Dr. J, Magic, Bird, Wilt, and Moses out of retirement for some on-court brawling. NBA Street Vol. 2 features all-new spectacular dunks, dribbles, and passes that'll take show-stopping Gamebreakers to the next level. You can take your game against computer opponents or friends, or play with up to three other players online. Are you good enough to rule the streets?","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7416","developer":"Electronic Arts","coverName":"NBA Street Vol. 2 (USA)","players":"2","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":4.5,"count":90}},{"id":"gauntlet-dark-legacy","title":"Gauntlet: Dark Legacy","year":2001,"genres":["Action"],"description":"Gauntlet: Dark Legacy is the follow-up to Gauntlet: Legends and another installment in the long-running Gauntlet series of hack-and-slash action games. As with all the Gauntlet games, you play a medieval fantasy character who, along with allies if you have them, fights his or her way through hordes of evil creatures on the never ending quest for more gold and perhaps even an eventual goal. \n\nThis version contains the characters and levels from Gauntlet: Legends, plus the new characters and levels from the Dark Legacy arcade game, with a few extra levels thrown in.\n\nThere are eight characters to initially choose from: the mighty Warrior, the deadly Valkyrie, the quick-footed Archer, the powerful Wizard, the spellcasting Sorceress, the stalwart Knight, the valiant Dwarf, and the chaotic Jester. Although there are similarities between characters from the two games, each character looks and plays differently. In addition, there are eight alternative-modes for these characters to unlock, plus dozens of secret characters to obtain. With a multi-tap, up to four players can play, with rules governing how much they can hurt each other. Unlike the original Gauntlets, the levels you'll face take place in various terrain from forests to mountains to volcanic plains. Many of the monsters are familiar to old fans of the series, but there are some new blood among the ranks of evil, including some rather large foes.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7274","developer":"Midway Games West","coverName":"Gauntlet - Dark Legacy (USA)","players":"4","publisher":"Midway Home Entertainment","esrb":"T - Teen","rating":{"score":4.18,"count":90}},{"id":"scarface-the-world-is-yours","title":"Scarface: The World Is Yours","year":2006,"genres":["Action"],"description":"The game begins in the film's final scene, with Tony Montana's (Andre Sogliuzzo) mansion being raided by Alejandro Sosa's assassins. But this is the point of divergence from the film. Instead of being killed by the Skull, Tony manages to sense him and shoots him down. He fights through his mansion, with many deaths on both sides. In the ensuing chaos, Tony sneaks to the front of the mansion, barely alive, and manages to escape in his car. Sosa is then informed that Tony's mansion has been seized and his massive drug empire has been reduced to nothing. Hiding in a safehouse located outside of Miami, Tony regrets the decisions he has made but swears revenge on Sosa.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5364","developer":"Radical Entertainment","coverName":"Scarface - The World Is Yours (USA)","players":"1","publisher":"Sierra Entertainment","esrb":"M - Mature","rating":{"score":4.26,"count":89}},{"id":"xenosaga-episode-ii-jenseits-von-gut-und-bose","title":"Xenosaga Episode II: Jenseits von Gut und Böse","year":2005,"genres":["RPG"],"description":"Xenosaga: Episode II - Jenseits von Gut und Böse is a direct sequel to the first episode of the science-fiction RPG Xenosaga series.\n\nThe story takes place thousands of years in the future, when mankind has long left the Earth, which is now called Lost Jerusalem, and founded a star empire. The main threat humanity has to face is the appearance of a super-powerful alien race called the Gnosis. The story picks up just after the concluding events of the first episode. Shion Uzuki, the young engineer who designed the powerful android KOS-MOS, arrives with her friends at the planet Second Miltia. They aim to learn more about the heritage of the late genius scientist Joachim Mizrahi, and foil the schemes of the mysterious antagonists Albedo and Margulis. Jin Uzuki, Shion's brother, who was only mentioned in the first chapter, becomes an important controllable character in the second episode. Much of the plot's content is dedicated to exploring the past and the origins of Jr., as well as his connection to Albedo.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7974","developer":"Monolith Software","coverName":"Xenosaga Episode II - Jenseits von Gut und Bose (Japan) (Disc 1) (Premium Box)","players":"1","publisher":"Sony Computer Entertainment Europe","esrb":"T - Teen","rating":{"score":4.0,"count":88}},{"id":"shin-megami-tensei-iii-nocturne","title":"Shin Megami Tensei III: Nocturne","year":2003,"genres":["RPG"],"description":"Set in post-apocalyptic Tokyo, Japan, Shin Megami Tensei: Nocturne takes you to a world where nearly the entire population is annihilated by a worldwide catastrophe called the Conception. Now the fate of the entire world lies on the shoulders of one boy, who must battle his way through opposing demonic forces, master the powers of Magatama, and persuade demons to join your party. Some demons may evolve into new forms on their own, or can be fused into more powerful monsters.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12344","developer":"Atlus","coverName":"Shin Megami Tensei III - Nocturne (Japan) (Deluxe Pack)","players":"1","publisher":"Atlus","esrb":"M - Mature","rating":{"score":4.31,"count":88}},{"id":"ben-10-protector-of-earth","title":"Ben 10: Protector of Earth","year":2007,"genres":["Beat 'em up","Platformer"],"description":"Ben 10: Protector of Earth is an action game based on the cartoon series Ben 10. The story follows the adventures of Ben Tennyson, who one day finds a watch-like device called the Ominitrix, which give him the ability to transform into different aliens each with its own special ability.\n\nThe aliens in which Ben can transform are: Fourarms, a big brute who excels at close combat, Fireblast, who can torch his enemies with fireballs, XLR8, a superfast speedster, Cannonball, who can turn into a metal ball and lastly Wildvine, who can stretch his limbs to reach new places.\n\nThe player has three kinds of attacks: light, heavy and the special moves as well as a large number of combos. The game features more than 14 levels, visiting locations as the Grand Canyon, San Francisco, Seattle, or Mt. Rushmore.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5905","developer":"High Voltage Software","coverName":"Ben 10 - Protector of Earth (USA)","players":"2","publisher":"D3Publisher","esrb":"E10+ - Everyone 10+","rating":{"score":4.02,"count":87}},{"id":"burnout-dominator","title":"Burnout: Dominator","year":2007,"genres":["Racing"],"description":"Burnout: Dominator is a racing game developed and published by Electronic Arts for the PlayStation 2 and PlayStation Portable. Burnout Dominator is the second spin-off game in the Burnout series and sixth overall. It retains the core gameplay of the series, as players race at top speeds through dozens of World Tour events testing \"reckless skill-based\" driving techniques. The versions for each platform do not interact with each other.\nThis is the only Burnout game that was not developed by Criterion Games, and the first Burnout game in the series since Burnout 2: Point of Impact to not feature the \"Crash Mode\". At the time Dominator was being developed, Criterion was busy working on Burnout Paradise and was waiting to re-introduce the mode in a new form for the latter title. However, Criterion Games are listed as \"the makers of this game\" in the game manual and credited as developer on the official Electronic Arts site.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5910","developer":"Electronic Arts UK","coverName":"Burnout Dominator (USA)","players":"4","publisher":"Electronic Arts","esrb":"E10+ - Everyone 10+","rating":{"score":4.14,"count":87}},{"id":"dragon-ball-z-budokai-tenkaichi","title":"Dragon Ball Z: Budokai Tenkaichi","year":2005,"genres":["Fighting"],"description":"Dragon Ball Z: Budokai Tenkaichi lets you play as more than 60 characters from the Dragon Ball Z TV series. You can battle using authentic special attacks of each character as you run, fly, and swim through fully destructible and free-roaming levels. Design your own character by assigning and upgrading 10 different attributes. Dragon Ball Z: Budokai Tenkaichi has multiple game modes for both one and two players.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/20835","developer":"Spike","coverName":"Dragon Ball Z - Budokai Tenkaichi (USA)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":4.06,"count":87}},{"id":"guitar-hero","title":"Guitar Hero","year":2005,"genres":["Rhythm"],"description":"The game features a guitar-shaped controller (resembling a miniature Gibson SG) that the player uses to simulate playing rock music. The gameplay is similar to GuitarFreaks, in that the player presses buttons on the guitar controller in time with musical notes that scroll on the game screen. The game features covers of 30 popular rock songs spanning five decades of rock, from the 1960s up through 2005, in addition to bonus tracks. Guitar Hero became a surprise hit, earning critical acclaim and winning many awards from major video game publications, and was considered one of the most influential games of the first decade of the 21st century.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7189","developer":"Harmonix Music Systems","coverName":"Guitar Hero (USA)","players":"2","publisher":"RedOctane","esrb":"T - Teen","rating":{"score":4.14,"count":87}},{"id":"the-getaway","title":"The Getaway","year":2002,"genres":["Action","Adventure","Racing","Sandbox"],"description":"Mark Hammond is an ex-gangster who wants to forget his past and live honestly with his wife and little son. Everything goes horribly wrong when London's most vicious criminal, the organized crime boss Charlie Jolson, decides that he needs Mark's services and obtains them in a twisted and cruel way: Mark's wife is murdered, he is framed for this murder, and his child gets kidnapped. \n\nJolson makes it clear: unless Mark does what he orders him to do, the boy dies. Using the helpless man in his plan to bring down other criminal organizations of the city, Jolson sends Mark on suicidal missions during which Mark has three terrible choices: walk away and lose his son, get killed in a battle against overwhelming odds, or single-handedly help Jolson to get rid of his adversaries.\n\nOnce the player completes Mark Hammond's story, a new scenario opens, in which the player controls Frank Carter, a vigilante cop who won't stop until he brings Charlie Jolson to justice. Frank's scenario is parallel to Mark's, shedding more light on events that remain somewhat unexplained during Mark's scenario.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7449","developer":"Team SOHO","coverName":"Getaway, The (USA) (En,Fr,De,Es,It)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":3.94,"count":87}},{"id":"champions-return-to-arms","title":"Champions: Return to Arms","year":2005,"genres":["Action","RPG"],"description":"The sequel to Champions of Norrath, Champions: Return to Arms is an action RPG that puts players in the EverQuest universe. The evil Innoruuk was destroyed and his remains (shards) have been scattered throughout the Planes of Power. The player must find the shards and choose between good or evil: Destroy them to rid of Innoruuk or collect them to restore him.\n\nThe game has seven playable races (two new ones from the original) and more online features. Players can import characters from the first game. It can be played single-player or with up to four players (online or with multitap).","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5924","developer":"Snowblind Studios","coverName":"Champions - Return to Arms (USA) (v1.01)","players":"4","publisher":"Sony Online Entertainment","esrb":"T - Teen","rating":{"score":4.21,"count":86}},{"id":"bloody-roar-3","title":"Bloody Roar 3","year":2001,"genres":["Fighting"],"description":"The gameplay (the controls) had six different buttons and the commands would be; punch, kick, throw, beast form, and side-step left and right with L2 and R2, which can also be done by double tap down or up to side-step. The main feature is still the ability to transform into beasts, which is involved in all of the Bloody Roar games. Once the character transforms, they regain all the health they have lost and become much stronger and powerful than before.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/11912","developer":"Eighting","coverName":"Bloody Roar 3 (USA)","players":"2","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":4.17,"count":86}},{"id":"zone-of-the-enders","title":"Zone of the Enders","year":2001,"genres":["Shooter"],"description":"In the late 22nd century, humans have colonized Mars, and also set up a few colonies in Jupiter's orbit. However, as time passed, the inhabitants of the Earth started to treat the space colonists, whom they called \"Enders\", with suspicion, subjecting them to harsh laws and repercussions. Eventually, some of the colonists founded rebel organizations, armed with particularly powerful mechas called Orbital Frames.\n\nA young colonist from Jupiter, Leo Stenbuck, unexpectedly comes into contact with an Orbital Frame named Jehuty. A terrible power is in his hands - will he use it for good, or for evil?..","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4761","developer":"Konami Computer Entertainment Japan","coverName":"Zone of the Enders (USA)","players":"2","publisher":"Konami","esrb":"M - Mature","rating":{"score":3.94,"count":86}},{"id":"espn-nfl-2k5","title":"ESPN NFL 2K5","year":2004,"genres":["Sports"],"description":"ESPN NFL 2K5 has a ton of new features for the new season.\n\nTo start off, the ESPN presentation has been greatly expanded. Chris Berman, who did voiceover for the half-time show in 2K4, returns for this season. Instead of just voice, there is a virtual Chris Berman, who does an introduction to each game, a half-time report, and a post-game show. To illiustrate certain points, he uses replays from each game. \nOne new feature is the V.I.P. system, which keeps track of how you play the game. If you pass 80% of the time, and run 20% of the time, your V.I.P. profile will reflect this. At a later time, you can play against your V.I.P., and the AI will play as if it were you.\n\nESPN celebrates it's 25th anniversary this year, and as such, a special 25th Anniversary Mode has been added. This mode allows you to play moments from classic football games, including The Heidi Bowl and The Immaculate Reception.\n\nThe Crib has an overhaul this year. Instead of earning specific items by completing tasks, you earn points, which you can use to buy items of your choice. New to the Crib is a dart board, as well as a phone, which you will use to answer calls from celebrities. You may get a call from Steve-O, Carmen Electra, Jamie Kennedy, David Arquette or Funkmaster Flex, challenging you to a game.\n\nFranchise mode also gets an overhaul. New to 2005 is the ability to schedule weekly preps for your team. You can choose to have players work out, play practice games, watch tapes, all in an effort to gear your team up for the next game.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7243","developer":"Visual Concepts Entertainment","coverName":"ESPN NFL 2K5 (USA)","players":"8","publisher":"Sega","esrb":"E - Everyone","rating":{"score":4.48,"count":85}},{"id":"hack-outbreak-part-3","title":".hack//Outbreak: Part 3","year":2003,"genres":["RPG"],"description":"This is a direct sequel to the first two hack games. The story of the hack series evolves around young people playing a massive multiplayer online RPG, called \"The World\". Some player characters in The World are mysteriously falling comatose - your main character Kite has to investigate the matter, aided by companions he meets on his trip through the virtual world.\n\nLike the first two hack games, this is an action RPG - essentially a dungeon crawler. You can pause at any time during the battle to issue commands (such as using items). In \"Outbreak\", you and your opponents start at around level 50 and can reach level 70. You can also import a saved game from the previous game, .hack//MUTATION.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7220","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Bandai America","esrb":"T - Teen","rating":{"score":3.6,"count":85}},{"id":"dragon-ball-z-budokai","title":"Dragon Ball Z: Budokai","year":2002,"genres":["Fighting"],"description":"Join us on a wild ride through the best action cartoon series on TV, Dragonball Z. The story begins after Goku defeats Piccolo at the World Marital Arts Tournament and he comes to visit Master Roshi, when all of a sudden, his brother Raditz appears and kidnaps his son, Gohan, after he saves him he is sent to Other World to train with King Kai for for two more powerful Saiyan arriving one year later. This wild ride story takes you from the Saiyan to the Cell Games Saga.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7222","developer":"Dimps","coverName":"Dragon Ball Z - Budokai (USA)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":3.69,"count":85}},{"id":"dragon-ball-z-infinite-world","title":"Dragon Ball Z: Infinite World","year":2008,"genres":["Fighting"],"description":"The best of the Budokai series! Relive the epic battles of the Dragon Ball Z saga across 25 different stages. Experience 4 different game modes including the new Dragon Mission mode with 114 missions to complete. Featuring over 40 characters, 100 transformations, and music by Mr. DBZ himself, Hironobu Kageyama!","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/20820","developer":"Dimps","coverName":"Dragon Ball Z - Infinite World (USA)","players":"2","publisher":"Atari","esrb":"T - Teen","rating":{"score":3.98,"count":84}},{"id":"50-cent-bulletproof","title":"50 Cent: Bulletproof","year":2005,"genres":["Shooter"],"description":"This game lets you step into the footsteps of 50 Cent himself. As he tries to free the kidnapped K-Dog with his crew in the streets of New York City, 50 gets shot nine times (just like his real-life counterpart) and left for dead. After getting stitched up, he sets out to find those who tried to kill him and uncovers a bigger conspiracy.\n\nThe game is a 3rd-person shooter with all the typical features: You have a wide array of weapons (including akimbo shooting), there are over 25 moves to finish people off at close range, you can find money to buy health packs, armor, and other helpful items. You can grab enemies and use them as human shields and use mobile objects (like dumpsters on wheels) as cover. The game uses the havok physics engine for a more dynamic environment.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5857","developer":"Genuine Games","coverName":"50 Cent - Bulletproof (USA)","players":"1","publisher":"Vivendi Universal Games","esrb":"M - Mature","rating":{"score":3.69,"count":84}},{"id":"the-lord-of-the-rings-the-third-age","title":"The Lord of the Rings: The Third Age","year":2004,"genres":["RPG"],"description":"The Lord of the Rings:The Third Age introduces entirely new characters which aren't mentioned in the books or movies. The game does relate to the movies by including scenes from all three movies, with new background speech by Ian McKellen (Gandalf).\n\nThere are seven playable characters in the game which have been created specifically for it, as well a small appearances by characters such as Gandalf, Aragorn, Eowyn, Faramir, and Gothmog.\n\nThe game covers events in all three movies/books, mostly with references to major events shown through cut scenes, or the scenes from the movies with Ian McKellan's narration.\n\nA classic RPG game, The Lord of the Rings: The Third Age has gameplay elements similar to Final Fantasy, where you have a party of characters, each with a different set of skills and attributes, who gain levels, making them stronger as the game progresses. Battles are turn-based, and let the gamer make different decisions on what they want to do to change the outcome of the battle. The game travels through many areas throughout Tolkien's Middle Earth, including The Pelennor Fields and Moria.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7456","developer":"Electronic Arts Redwood Shores Studio","coverName":"Lord of the Rings, The - The Third Age (USA)","players":"2","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.17,"count":84}},{"id":"beyond-good-evil","title":"Beyond Good & Evil","year":2003,"genres":["Action","Adventure"],"description":"Beyond Good & Evil takes place in the year 2435 on the mining planet of Hillys, located in Sector Four, a remote section of the galaxy. The architecture of the city around which the game takes place was designed with a rustic European style. The world itself combines modern elements, such as e-mail and credit cards, with those of science fiction and fantasy, such as spaceships and anthropomorphic animals coexisting with humans. The once-peaceful planet is under siege by aliens called the DomZ that abduct beings and either drain their life force for power or implant them with spores to convert them into slaves. A military dictatorship called the Alpha Sections takes power, promising to defend the populace. However, the Alpha Sections seem unable to stop the DomZ despite their public assurances. An underground resistance movement, the IRIS Network, fights the Alpha Sections, believing them to be in league with the DomZ.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7920","developer":"Ubisoft Pictures","coverName":"Beyond Good _ Evil (USA) (En,Fr,Es)","players":"1","publisher":"Ubisoft Entertainment","esrb":"T - Teen","rating":{"score":4.17,"count":84}},{"id":"spider-man","title":"Spider-Man","year":2002,"genres":["Action"],"description":"Spider-Man is a level based action game, with the player as Spider-Man. Half the levels are indoors, but the rest of the levels are outside among the sky-scrapers of New York and require him to web-sling from building to building, however Spider Man cannot land on the ground, as he will die if he gets too close. Levels are in \"sections\" with a different enemy for each, each section lasting about 3 levels. Each level, except for the last two, has a bonus screen after it. Generally, there are the bonuses \"Time\" (clear level in a set time), \"Perfect\" (Not take damage/detected) and \"Style\" (use as many combos as possible). Other level-specific ones are \"Secrets\" (Uncover a secret area), \"Combat\" (Defeat all enemies). Players can gain, depending on difficulty, points on completing these tasks.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4777","developer":"Treyarch","coverName":"Spider-Man (USA) (v1.00)","players":"1","publisher":"Activision","esrb":"E - Everyone","rating":{"score":4.01,"count":84}},{"id":"the-punisher","title":"The Punisher","year":2005,"genres":["Action"],"description":"The Punisher is a third person action game that pits the player against the darkest scum of the Marvel Comics' universe. With over a dozen grimy New York locales, this superhero adaptation embraces the feel of the 30 year comic series.\n\nFeaturing loads of weapons, brutal environmental kills and an innovative new interrogation engine where the player controls every last aspect of over 70 torture scenarios, the Punisher provides a rich gaming experience for fans of dark, intense action.\n\nStory written by comics authors Garth Ennis and Jimmy Palmiotti.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5411","developer":"Volition","coverName":"Punisher, The (USA)","players":"1","publisher":"THQ","esrb":"M - Mature","rating":{"score":4.19,"count":83}},{"id":"capcom-fighting-evolution","title":"Capcom Fighting Evolution","year":2004,"genres":["Fighting"],"description":"Legendary fighters from five Capcom arcade classics finally meet in one totally cool, totally old-school game! This all-new game lets you choose from characters spanning Street Fighter II, Street Fighter III, Street Fighter Alpha, Darkstalkers and Red Earth, never before released in the U.S.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/15576","developer":"Capcom","coverName":"Capcom Fighting Evolution (USA)","players":"2","publisher":"Capcom","esrb":"T - Teen","rating":{"score":3.61,"count":83}},{"id":"def-jam-vendetta","title":"Def Jam Vendetta","year":2003,"genres":["Fighting","Sports"],"description":"The unlikely combination of Def Jam recording artists and underground wrestling is the subject of this Electronic Arts release, which features the 3D likenesses of such musicians as Ludacris, Redman, DMX, Scarface, Ghostface Killa, Method Man, and more as playable characters. Developed by AKI Corporation, whose previous experience in the genre includes titles WWF No Mercy and WCW/NWO Revenge, Def Jam Vendetta offers an estimated 1,500 animations for each of the 45 included characters. A total of ten different venues are available, and one of the featured modes offers a storyline complete with soap opera-style drama to go along with the suplexes and body slams. Up to four players can compete in Single, Tag-Team, Handicap, or Battle Royale matches.\n\nEA combines the game-making prowess of Aki and the boisterous characters from hip-hop's Def Jam Records. The result is Def Jam Vendetta, a curious concoction that just might have the goods to attract hardcore and mainstream gamers alike. The game features 12 Def Jam artists including Redman, Method Man, Ludacris, DMX, N.O.R.E., and Scarface. As you make your way through the game, you'll be able to unlock all 45 characters plus aditional venues, girls, and concept art.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7206","developer":"Electronic Arts Canada","coverName":"Def Jam - Vendetta (USA)","players":"4","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":3.97,"count":83}},{"id":"drakengard","title":"Drakengard","year":2004,"genres":["Action","RPG"],"description":"Drakengard follows the story of a kingdomless prince named Caim who fights for the Union against the Empire. Under the Union's protection are the Hierarchs and the Goddess, currently Caim's sister Furiae, who is a human manifestation of one of the four seals that protect the world from being broken. As the game begins, Cain is fatally wounded in a battle with the Empire. Encountering a captured Red Dragon who is also near death, Caim makes a fateful choice. In exchange for both their lives, the Red Dragon and Caim will enter a pact. This pact will forever chain their lives to one another and link their souls, at the cost of something irreplaceable. Recharged with the fires of a Dragon, Caim's vengeance burns over the enemy...\n\nThe player controls Caim on his quest. The game is separated into three distinct modes: Aerial combat, Ground combat and Event Combat. In Aerial Combat, Caim rides dragonback against a variety of airborne foes breathing fireballs (strong single shots and weaker multiple lock-on shots). The Dragon is agile and is able to evade incoming threats, turning around completely in a moment. In Ground combat, the game is shown in 3rd person though usually large, open areas. Controlling Caim, his primary ability is the use of a variety of weapons found on the battlefield. These are leveled up through continued usage, and specifically through the killing of individual enemies. Though magic (determined by weapon choice), timed attacks and evasion, Caim breaks through enemy armies. Characters recruited as allies by Caim can also be summoned during battles, steadily losing health until control is returned to Caim. In ground combat, Caim may also call forth his Dragon to ride and strafe enemies from the air. The Dragon's movements are generally the same as in aerial combat but more limited and less agile. Event combat is similar to Ground combat, but shown isometrically, restricted to a single weapon and without the aid of a dragon. It is used mainly to tell story sequences.\n\nLevels that have been visited before might become \"Expedition Missions\" which are optional and contain new objectives, enemies and weapons. Additionally, any level previously played in the storyline may be revisited at any time. Depending on Caim's choices (and prerequisites for those choices), there are five different endings to Drakengard.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7228","developer":"Cavia","coverName":"Drakengard (USA)","players":"1","publisher":"Square Enix","esrb":"M - Mature","rating":{"score":3.59,"count":82}},{"id":"silent-hill-2-director-s-cut","title":"Silent Hill 2: Director's Cut","year":2002,"genres":["Horror"],"description":"In the sequel to Silent Hill, Silent Hill 2 follows James Sunderland, whose life is shattered when his young wife Mary suffers a tragic death. Three years later, a mysterious letter arrives from Mary, beckoning him to return to their sanctuary of memories, the dark realm of Silent Hill. You must guide James through all-new environments and creepy new areas closed off in the original game. Real-time weather effects, fog, morphing, and shadows set the stage for heart-stopping frights. Be brave as you journey to uncover the truth.\n\nDirector's Cut is an updated version of Silent Hill 2. It contains all of the content of the original version and adds several pieces of new content. The most significant is a new short scenario called Born from a Wish, where players take control of Maria from her first moments right up to where she first appears in the main game. Also included is a sixth ending to the main scenario and a minor feature that allows the player to turn off the graphical effect, which makes the game look like it was shot on cheap film stock.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/123210","developer":"Team Silent","coverName":"Silent Hill 2 - Director's Cut (Europe) (En,Fr,De,Es,It)","players":"1","publisher":"Konami","esrb":"M - Mature","rating":{"score":4.68,"count":82}},{"id":"shadow-the-hedgehog","title":"Shadow the Hedgehog","year":2005,"genres":["Action","Adventure","Platformer"],"description":"Shadow the Hedgehog is a platforming game developed by Sega Studio USA (the former US division of Sonic Team) and published by Sega. The game is the first to feature Shadow the Hedgehog from Sega's Sonic the Hedgehog series as the main character.\n\nAfter the events of Sonic Adventure 2, Shadow suffers from amnesia, being unable to remember anything but his name and memory involving a young girl named Maria. As he ponders about his past, the World is suddenly attacked by aliens. Their leader, Black Doom, approaches Shadow and asks him to bring the Chaos Emeralds \"as promised\". Surprised that Black Doom knew him, Shadow decides that the Emeralds are the key to unlocking his past and purpose and sets off.\n\nhttps://crappygames.miraheze.org/wiki/Shadow_the_Hedgehog\n\nThe game includes 10 endings based on what path the player takes, along with the Last Story, which is unlocked after getting all other endings.\n\nThe world is in peril as forces, both good and evil, make a play for the powerful Chaos Emeralds. In Shadow the Hedgehog, you can control Shadow and choose which side to fight for. This 3D platformer lets you use weapons, vehicles, environmental objects, and time and space manipulation to combat your foes.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12375","developer":"Sonic Team","coverName":"Shadow the Hedgehog (USA) (En,Ja,Fr,De,Es,It)","players":"2","publisher":"Sega","esrb":"E10+ - Everyone 10+","rating":{"score":3.75,"count":81}},{"id":"timesplitters-future-perfect","title":"TimeSplitters: Future Perfect","year":2005,"genres":["Shooter"],"description":"In the year 2401, the space marine Sergeant Cortez returns with a cargo of time crystals from the space station he destroyed at the end of TimeSplitters 2. Using these to power a time machine, The General and Anya send Cortez on a mission to stop the TimeSplitters from coming into existence.\n\nThe third game in the TimeSplitters series, Future Perfect is a first-person shooter in the same vein as its predecessors. The main campaign can be played through in single-player mode or cooperatively by two players, and multiplayer modes can be played by up to four players in split-screen mode or with up to eight players via LAN or the internet.\n\nThe story campaign consists of thirteen missions spanning six different time periods, and in each period Cortez meets and teams up with a contemporary character. The single-player mode sees these companions controlled by the AI, while co-op mode assigns them to player two. Each time period features its own arsenal meaning that players typically use era-appropriate weaponry throughout the campaign, and several missions include vehicle or turret sequences.\n\nIn addition to the main campaign, there are several other game modes available. There's Arcade, available both as a single-player \"League\" against NPC opponents and as a multiplayer mode (which can also be played with NPC opponents if desired). Arcade mode allows players to choose from the 150 playable characters, and includes genre standbys like Deathmatch, Team Deathmatch, and Capture the Flag (or \"Capture the Bag\" in this instance), as well as more distinctive offerings such as Escort, Shrink, and Monkey Assistant. Beyond that there's also a Challenge mode, in which the missions are more focused in scope - for instance, the \"Behead the Undead\" set of challenges is all about dismembering zombies.\n\nThe game also includes a level editor, allowing players to create custom maps for use in Arcade play.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9231","developer":"Free Radical Design","coverName":"TimeSplitters - Future Perfect (USA)","players":"4","publisher":"Electronic Arts","esrb":"M - Mature","rating":{"score":4.57,"count":81}},{"id":"hack-mutation-part-2","title":".hack//Mutation: Part 2","year":2003,"genres":["Adventure","RPG"],"description":".hack//Mutation is the second in a four part game series. It's a single player adventure / rpg that \"simulates\" an MMORPG (EverQuest, Ultima On-line) that has you playing the character Kite. You can get member addresses of other character and attempt to call them to in game to see if they are on-line to join you in a quest. Like standard MMORPG games, it has a LOT of side quests, lots of weapons and armor, a trading system for equipment among other character and the ability to move between different servers. You also have message boards and e-mail to communicate with other \"players\". This version improves the original by better AI control of other character's, additional items, more characters, access to more servers / areas, and a lot more.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7219","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Bandai","esrb":"T - Teen","rating":{"score":3.42,"count":81}},{"id":"resident-evil-dead-aim","title":"Resident Evil: Dead Aim","year":2003,"genres":["Horror","Shooter"],"description":"In a combination of a horror game and light-gun game, Resident Evil: Dead Aim puts you on a cruise ship infested with zombies. You start off as Bruce McGivern, a US government agent sent to stop Morpheus D. Duvall from spreading the zombie T-virus any further. Along the way you'll run into Fongling, a Chinese government agent who is aboard the cruise ship for the same reason, and you'll also end up playing as her. All you really need to know is that there are zombies and you have to kill them.\n\nYou'll pick up several different guns through the course of the game, including a magnum, a shotgun, and an assault rifle, but like in other Resident Evil games, zombies are difficult to put down permanently, and ammo can be very scarce.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/3945","developer":"Cavia","coverName":"Resident Evil - Dead Aim (USA)","players":"1","publisher":"Capcom","esrb":"M - Mature","rating":{"score":3.75,"count":81}},{"id":"the-lord-of-the-rings-the-two-towers","title":"The Lord of the Rings: The Two Towers","year":2002,"genres":["Adventure","Beat 'em up"],"description":"Electronic Arts' first game based on the Lord of the Rings movies is an action game with classic beat'em up-style gameplay. Despite the title, it covers events from both the first and the second film in the trilogy.\n\nPlayers, choosing to control Aragorn, Legolas or Gimli, must battle the evil forces of the Dark Lord Sauron in order to protect the Ring of Power and restore peace to Middle-earth. \n\nThe player character moves through the levels, fighting hordes of Orcs, Goblins and other creatures with various attack and parrying moves. The more varied the attacks are and the less the player is hit, the more points are awarded for each kill. At the end of each level, kill points are accumulated and can be used to gain new abilities. Most of these are new attack moves, unleashed through various button combinations. Others increase health or upgrade the strength or speed of existing attacks. Each of the three characters has unique upgrades and moves.\n\nSeveral levels feature boss battles with the likes of the Watcher of Moria or Lurtz, leader of the Uruk-hai. Each boss requires a unique strategy to defeat.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7457","developer":"Stormfront Studios","coverName":"Lord of the Rings, The - The Two Towers (USA)","players":"1","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.25,"count":81}},{"id":"soul-reaver-2","title":"Soul Reaver 2","year":2001,"genres":["Action","Adventure"],"description":"The game begins by retelling the final battle with Kain in the original Soul Reaver: Raziel confronts Kain in the Chronoplast time machine, and the two enter a portal through time to emerge thirty years before the events of Blood Omen. Moebius the Timestreamer tells Raziel that Kain is at the Pillars of Nosgoth, and Raziel goes and confronts him. Kain reveals he has plans to transform history to avert the consequences of his decision, when his past self refused to sacrifice himself to restore Nosgoth and doomed the land to eternal decay. Kain vanishes, and Raziel continues northward and finds the vampire Vorador, who hints at a profound secret that the deceased vampire Janos Audron once knew. Deciding to speak with Janos, Raziel returns to the Sarafan stronghold where he again meets Kain, who tells Raziel the Soul Reaver is the only way history can be changed, as he did so when battling William the Just with a future incarnation of the Reaver in Blood Omen. Kain hands Raziel the material Soul Reaver, and the spectral Soul Reaver Raziel has coils around it. Raziel is faced with a dilemma: kill Kain and submit to fate, or establish his free will by refusing. Raziel avoids dealing the death blow, changing time again before Kain vanishes. Raziel finds Moebius in his timestreaming chamber and forces him to send him to the past before the vampire purge of the Sarafan Order, but Moebius tricks him.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4787","developer":"Crystal Dynamics","coverName":"Soul Reaver 2 (Asia)","players":"1","publisher":"Eidos Interactive","esrb":"M - Mature","rating":{"score":4.33,"count":81}},{"id":"rule-of-rose","title":"Rule of Rose","year":2006,"genres":["Action","Adventure","Horror","Puzzle"],"description":"The player explores the game environments looking for restorative items, furthering the plot by accomplishing tasks and experiencing cut-scenes while sporadically encountering enemies and bosses. Early in the game, the player encounters and rescues Brown, Jennifer's pet Labrador Retriever.Brown accompanies Jennifer throughout the game and will respond to the player's commands. Brown can be ordered to track items by scent, be commanded to 'stay' and be called to Jennifer's side. Brown cannot attack enemies, but will growl, which distracts some imps and bosses, allowing Jennifer to retreat or land a few blows without fear of retaliation. He can be injured to the point of collapse, however, causing him to stop distracting enemies or tracking an item.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12684","developer":"Punchline","coverName":"Rule of Rose (USA)","players":"1","publisher":"Sony Computer Entertainment","esrb":"M - Mature","rating":{"score":3.84,"count":80}},{"id":"street-fighter-alpha-anthology","title":"Street Fighter Alpha Anthology","year":2006,"genres":["Fighting"],"description":"The original Street Fighter Alpha, as well as Alpha 2, Alpha 3 and Super Gem Fighter Mini Mix are ported from their original arcade releases, while Alpha 2 Gold is a remixed version that combines elements from the previous console version and the Japanese arcade release Street Fighter Zero 2 Alpha. The version of Alpha 2 Gold allows player to select Cammy in all the game modes, including the single-player Arcade Mode (in which she is given her own storyline and ending), not just Versus and Training.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/5361","developer":"Capcom","coverName":"Street Fighter Alpha Anthology (USA)","players":"2","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.36,"count":80}},{"id":"suikoden-v","title":"Suikoden V","year":2006,"genres":["RPG"],"description":"Suikoden V, like its predecessors, features unparalleled in-depth gameplay, a riveting storyline as well as the series' trademark 108 Stars of Destiny. Thrust into a time of unbalance and unrest, a dynamic drama unfolds revolving around one of the 27 True Runes, the Sun Rune. Players are tasked to explore the lands of Falena, gather allies and become stronger to ultimately bring back peace and prosperity. While on their quest through rich 3D environments, exciting new secrets of the Suikoden world will be revealed. The game features significant enhancements from all the previous installments of the series, including 6-member battle parties, multiple mini-games and the homebase system, where all of your allies gather together along with new features to create a unique gameplay experience like no other.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12394","developer":"Hudson Soft","coverName":"Suikoden V (USA)","players":"1","publisher":"Konami","esrb":"T - Teen","rating":{"score":4.27,"count":80}},{"id":"star-wars-episode-iii-revenge-of-the-sith","title":"Star Wars: Episode III: Revenge of the Sith","year":2005,"genres":["Action"],"description":"The player controls Anakin Skywalker and Obi-Wan Kenobi in the single player mode, reliving various scenes from the film through the game's missions. There are 17 levels, interlaced with over 12 minutes of footage from the movie. Enemies include droids, clone soldiers and Neimodian forces. The game's combat system is heavily concentrated on lightsaber combat. Each of the playable characters (with the exception of the IG-100 Magnaguard) is equipped with at least one lightsaber. There are three basic attacks: Fast attacks which do the least amount of damage, Strong Attacks which do more damage but are slower to execute, and the slowest but strongest Critical Attacks. These attacks can be mixed to create combination attacks. Attacks can also be charged up for greater strength. One feature of the game is called a Saber Lock - a sequence in which the player's character clashes swords with an opponent. Other offensive maneuvers are also available, including grapples, jumps and flying kicks.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4786","developer":"The Collective","coverName":"Star Wars - Episode III - Revenge of the Sith (USA)","players":"2","publisher":"LucasArts","esrb":"T - Teen","rating":{"score":4.28,"count":80}},{"id":"rumble-roses","title":"Rumble Roses","year":2004,"genres":["Fighting","Sports"],"description":"A wrestling game featuring a large and varied number of attractive women. The playable characters run the gamut: nurses, schoolgirls, cowgirls, ninjas, and many more. Each combatant has her own repository of clothes to choose from before each match, from a wide selection of standard wrestling outfits, to a series of bikinis, used mainly for the Mud Wrestling mode in the game.\n\nA great deal of the game revolves around the personalities of the fighters and the usage of the reputation system. Several matches will require that the player be sworn not to use dirty tactics such as using weapons found around the ring or even to humiliate the opponent. These oaths can be broken by the player, but the consequences are the loss of fan popularity and for the player's chosen character to develop a dark side to their persona.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9793","developer":"Yuke's","coverName":"Rumble Roses (USA)","players":"2","publisher":"Konami","esrb":"M - Mature","rating":{"score":3.91,"count":80}},{"id":"spongebob-squarepants-battle-for-bikini-bottom","title":"SpongeBob SquarePants: Battle for Bikini Bottom","year":2003,"genres":["Platformer"],"description":"SpongeBob SquarePants: Battle for Bikini Bottom is a 2003 video game based on the animated series of the same name. Developed by Heavy Iron Studios, AWE Games and Vicarious Visions and published by THQ. The game was released for the PlayStation 2, Game Boy Advance, Xbox,and Nintendo GameCube consoles as well as for Microsoft Windows. The player attempts to defend Bikini Bottom from an invasion of robots created by Plankton with a machine called the Duplicatotron 3000. The playable characters are SpongeBob, Patrick, and Sandy. The game was released on October 31, 2003 in North America and in Europe on November 28, 2003.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/22580","developer":"Heavy Iron Studios","coverName":"","players":"1","publisher":"Activision","esrb":"E - Everyone","rating":{"score":4.05,"count":80}},{"id":"medal-of-honor-frontline","title":"Medal of Honor: Frontline","year":2002,"genres":["Shooter"],"description":"In Frontline, the player takes on a first person view and fights as an American OSS operative in D-Day. There are six missions in Frontline, each made up of several smaller levels. Briefings take place at the start of each mission, which advance the plot and introduce new characters. The smaller missions take place in a linear path, with the player fighting through towns and countryside, killing enemies and completing objectives. Objectives are explained to the character in a smaller briefing before each level, which prepares the player for that particular mission. The \"War Room\" serves as the game's main menu, and is reminiscent of Britain's secret underground intelligence bunkers during WWII.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4268","developer":"Electronic Arts Los Angeles","coverName":"Medal of Honor - Frontline (USA)","players":"1","publisher":"Electronic Arts","esrb":"T - Teen","rating":{"score":4.09,"count":80}},{"id":"rayman-2-revolution","title":"Rayman 2: Revolution","year":2001,"genres":["Action","Platformer"],"description":"Ubisoft's personable and popular cartoon hero is back and more ambitious than ever in the PlayStation 2-exclusive re-imagining, Rayman 2: Revolution. Now in full 3D and blending humor, suspense, and blinding speed, Rayman must escape an intergalactic zoo by using the powers of his still-imprisoned friends to open the door to an even greater power to free them. Unique to the PS2 version of the game are a number of brand new stages, a harder difficulty level, and a progressive upgrade system that gives Rayman a number of abilities not found in other iterations.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12905","developer":"Ubi Soft Entertainment Software","coverName":"Rayman 2 - Revolution (USA) (En,Fr,De,Es,It)","players":"1","publisher":"Ubi Soft Entertainment Software","esrb":"E - Everyone","rating":{"score":3.93,"count":80}},{"id":"guitar-hero-ii","title":"Guitar Hero II","year":2006,"genres":["Rhythm"],"description":"Guitar Hero II, the follow-up to the PS2-only game Guitar Hero, expands upon the gameplay and features of the original game. As a wannabe rockstar, you need to play songs by pressing combinations of five fret buttons on a guitar-shaped controller, while working the strum bar, along with an optional whammy bar for distortion. The sequel contains 64 songs, of which 40 have been licensed. One of the tracks was discovered through a contest at beaguitarhero.com, where unlicensed bands could send in a demo to be included in the game. Most of the tracks have been covered in-studio, but a few use original recordings.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7187","developer":"Harmonix Music Systems","coverName":"Guitar Hero II (USA)","players":"2","publisher":"Activision","esrb":"T - Teen","rating":{"score":4.36,"count":79}},{"id":"marvel-ultimate-alliance","title":"Marvel: Ultimate Alliance","year":2006,"genres":["Action","RPG"],"description":"Dr. Doom has united supervillains as the Masters of Evil. Now for the first time ever, over 20 Marvel superheroes including Spider-Man, Captain America, Wolverine, Ghost Rider, Blade and Silver Surfer have come together to stop Doom. Mix and match your choice of Marvel superheroes, in teams of four as you travel across the Marvel Universe to stop this threat. Certain teams such as The Fantastic Four and The New Avengers provide additional bonuses.\n\nSome heroes must be unlocked first. The game also features RPG elements, such as leveling up. When a hero gains a level, they earn points you can use to upgrade their skills. You also collect Shield Coins, which can be spent on boosts for your hero team. \n\nYou explore various legendary Marvel locales, from Asgard, to Prince Namor's Atlantis, where you take on foes with punches, kicks and super powers. Super powers drain energy, however, so use them wisely. Combos can be achieved by combining super powers. Energy is restored by collecting blue orbs from fallen foes. \n\nBoss battles are like the comics themselves: titanic battles that often not only test brawn but your brain as well. With over 20 playable heroes plus all the cameos, there are over 100 heroes and villains.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7356","developer":"Raven Software","coverName":"Marvel - Ultimate Alliance (USA)","players":"4","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":4.2,"count":79}},{"id":"ultimate-spider-man","title":"Ultimate Spider-Man","year":2005,"genres":["Action","Fighting"],"description":"The game begins with a recap of Spider-Man's (Peter Parker) first fight with Venom (Eddie Brock) before he disappeared. Spider-Man fights Venom on the high school football field on a rainy night, before spanning to the middle of a street where Venom was believed to be killed by a downed, live power line. Three months later, Parker has resumed his normal life and has forgotten about Venom. After stopping Shocker, Spider-Man ends up in a race against Human Torch. Meanwhile, Eddie, who is actually alive, has been feeding on people randomly in a nearby park and proves his strength in a fight with Wolverine into a bar and then into a next-door building.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/4770","developer":"Treyarch","coverName":"Ultimate Spider-Man (USA) (Limited Edition)","players":"1","publisher":"Activision","esrb":"T - Teen","rating":{"score":4.02,"count":79}},{"id":"mega-man-x7","title":"Mega Man X7","year":2003,"genres":["Platformer","Shooter"],"description":"The plot of Mega Man X7 takes place in the 22nd century during an age when humans coexist with humanoid robots called \"Reploids\". As some Reploids participate in violent and destructive crime, a police organization called the \"Maverick Hunters\" was established to stamp out this activity. As the Reploid conflicts proceed after the Nightmare phenomena event of Mega Man X6, the world is slowly recovering. But as always, Maverick crime is rising in newly constructed cities. As this new crime wave hits, X finds himself trying to answer moral questions that have plagued him since he joined the Maverick Hunters: \"Are we doing the right thing to solve this matter?\", leading him to the decision of \"I've had enough of this violence.\" Unable to assuage his conscience, he drops from the battle frontlines and assumes a more strategic support role at headquarters. With X's retirement, a massive power vacuum ensues and many independent groups develop, trying to fill the void left by the hunter. Prominent among these groups is the \"Red Alert Syndicate\", growing large enough to become a dominant force. The Red Alert is a new group of Reploids, similar to the Repliforce, but consisting of vigilantes. They claim to hunt Mavericks, but apparently do more than that. One of their members, Axl, decides he's had enough of their \"murdering\" and tries to leave the group. Red, the group's leader, is angered by Axl deserting, and goes on a rampage to get Axl back.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7362","developer":"Capcom","coverName":"Mega Man X7 (USA)","players":"1","publisher":"Capcom","esrb":"E - Everyone","rating":{"score":3.09,"count":79}},{"id":"auto-modellista","title":"Auto Modellista","year":2002,"genres":["Racing"],"description":"Auto Modellista is a cel-shaded racing game featuring many high-performance cars from different manufacturers, including Mazda, Honda, Toyota, and Subaru, as well as some Japanese concept cars.\n\nThe game has a few modes: garage life, two-player split-screen, time trial, and arcade. Garage life is the main mode in the game. Here the player will race with any of the cars they have unlocked over seven levels, each with a different number of races. The player will need to finish first in some or all of the races to move to the next level. Winning these races unlocks new parts, items, and cars. In the garage, the player may customize the appearance of their car with stickers and body parts previously won. It's also possible to tune the car by adjusting brakes, suspension, tires, etc.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/33334","developer":"Capcom Production Studio 1","coverName":"Auto Modellista (USA)","players":"2","publisher":"Capcom","esrb":"E - Everyone","rating":{"score":4.29,"count":79}},{"id":"odin-sphere","title":"Odin Sphere","year":2007,"genres":["Action","RPG"],"description":"The nations of Erion had always held an uneasy peace, as the various kings and queens watched each other for any signs of weakness. When the country of Valentine is obliterated by the power of an ancient artifact, it sparks a bloody war between the fairies of Ringford and the warriors of Ragnanival. Little do they know that they are acting out an almost-forgotten prophecy: one that, if fulfilled, will lead to the destruction of the entire world. Take control of the warrior princess Gwendolyn, daughter of Odin, and follow the threads of an intricately woven story as you uncover the truth behind the prophecy - and how to bring it to an end. Five playable characters in all; each one's fate is intertwined with the others'. A robust cooking and alchemy system that can be used to create powerful attack and recovery items.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9326","developer":"VanillaWare","coverName":"Odin Sphere (USA)","players":"1","publisher":"Atlus","esrb":"T - Teen","rating":{"score":4.14,"count":78}},{"id":"valkyrie-profile-2-silmeria","title":"Valkyrie Profile 2: Silmeria","year":2006,"genres":["RPG"],"description":"Hundreds of years before Lenneth's tale, another saga lies concealed by the gods. The valkyrie Silmeria once served Odin loyally, but after an incident ignited a conflict between them, Odin forcefully reincarnated her as a human. The human soul that would carry her spirit was that of Alicia, Princess of Dipan. Ordinarily, Silmeria-s consciousness would have been sealed, her spirit dormant until she was next summoned... However, the forced transmigration causes Silmeria's spirit to awaken within Alicia, leaving two souls to inhabit a single body. The spirit that should have been sealed has awakened-a situation Odin will not ignore for long. This installment introduces the new Photon Action System to the classic side-scrolling action format found in the original. Projecting photons grants players more freedom to explore and expands the action, resulting in challenging puzzles with clever solutions. Add to that \"sealstones\" that affect the laws of nature in dungeons, launching strategy to new heights. The unique battle system of the previous game has evolved into the Advanced Tactical Combination Battle System.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9330","developer":"tri-Ace","coverName":"Valkyrie Profile 2 - Silmeria (USA)","players":"1","publisher":"Square Enix","esrb":"T - Teen","rating":{"score":4.37,"count":78}},{"id":"hack-quarantine-part-4","title":".hack//Quarantine: Part 4","year":2004,"genres":["RPG"],"description":"This is the last chapter of the .hack series for Playstation 2. The series tells a story of a future society where it is possible to play massive multiplayer online RPGs in a virtual reality. But something strange happens to the characters of this virtual world, and a young player named Kite decides to investigate the mystery. He can have contact to fellow players in the real world, and - as a player character - also have a party within virtual reality. The gameplay on the series is heavy on dungeon crawling, and the combat is action based. The fourth chapter closes the saga, finishes the story, and allows the player to reach the highest levels of character development and acquire ultimate weapons and accessories.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7221","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Bandai America","esrb":"T - Teen","rating":{"score":3.77,"count":78}},{"id":"blood-will-tell-tezuka-osamu-s-dororo","title":"Blood Will Tell: Tezuka Osamu's Dororo","year":2004,"genres":["Action"],"description":"In this combat adventure, players take the role of a hero whose hands and feet are lethal weapons -- quite literally. Hyakkimaru is missing several of his natural body parts, which have been replaced by blades, guns, and other weaponry. His natural limbs were taken by demons, and he is on a quest to take them back. The fast-paced hack-and-slash action is strung together on a fairly thick storyline, which is told through extensive pre-rendered cut scenes. A two-player mode is also included, which puts the second gamer in control of Hyakkimaru's companion Dororo, a small girl with some big attack moves. Blood Will Tell is based on the manga series by Osamu Tezuka, the influential Japanese artist who may be best known to Western audiences as the creator of Astro Boy.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12794","developer":"Red Entertainment","coverName":"Blood Will Tell - Tezuka Osamu's Dororo (USA)","players":"2","publisher":"Sega","esrb":"M - Mature","rating":{"score":3.92,"count":78}},{"id":"neo-contra","title":"Neo Contra","year":2004,"genres":["Shooter"],"description":"The ultimate run'n'gun shooter! Take on the role of tough-as-nails hero Bill Rizer and his partner, the mysterious samurai Jaguar to stop a maniacal organization from taking over the world! Intense firefights, incredibly wicked boss enemies and legendary gameplay brings the Contra series to a whole new dimension. \n\nAwesome weaponry to choose from including spread shot, lock-on missiles and flamethrowers. Unlockable levels and extras. Selectable difficulties for beginners and experts. Two player simultaneous action.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7427","developer":"Konami Computer Entertainment Tokyo","coverName":"Neo Contra (USA)","players":"2","publisher":"Konami","esrb":"M - Mature","rating":{"score":3.9,"count":78}},{"id":"crash-mind-over-mutant","title":"Crash: Mind over Mutant","year":2008,"genres":["Action","Adventure","Platformer"],"description":"Crash: Mind over Mutant continues the storyline of its predecessor, Crash of the Titans. \n\nThe Titans from the previous game has broken free from Dr. Cortex' control and has settled down on various places on the Wumpa Islands. But Cortex has teamed up with Nitrus Brio to develop a device which can control both the bandicoots and the Titans. Now Crash and his friends must find out where Cortex is hiding and stop him before he can act out his devious plan. \n\nCrash can use a light-powered attack to defeat smaller enemies, but for bigger enemies, a more high-powered attack is needed. Crash can also block and dodge attacks. Just like in Crash of the Titans, Crash can take control of the Titans which he encounters. But this time he can take the Titans with him and use them when he needs it. As Crash defeats more and more enemies, he can upgrade both his own attacks and the attacks of the Titans in his possession.\n\nThe Co-Op Experience:\nYour co-op partner is Crash's sister, Coco, playable for the first time in the cooperative mode. Not only does Coco make the game more inviting to pick up and play, she also brings with her a new tactile \"treasure hunt\" ability where one co-op partner can \"jack\" on the other and ride as gunner, using different ammo.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/18930","developer":"Radical Entertainment","coverName":"Crash - Mind over Mutant (USA)","players":"2","publisher":"Activision","esrb":"E10+ - Everyone 10+","rating":{"score":3.62,"count":77}},{"id":"hack-g-u-vol-3-redemption","title":".hack//G.U. Vol. 3: Redemption","year":2007,"genres":["RPG"],"description":"It is 2017 and the dangers found in .hack//G.U.: Vol. 3 Redemption are filtering out of the game. The evil entity terrorizing players in \"The World\" is free and wreaking havoc in real-life. Players once again take the role of Haseo, a young adventurer who is the only hope for restoring peace in \"The World.\" \n\nGamers lead Haseo through many recognizable environments and into such new root towns as Breg Epona and the Net Slum. The steam bike makes a return and players can now upgrade their bikes and speed through five riding missions. Toward the end of the game, players may access a 100 floor dungeon and work through each level with their most powerful party members. \n\nHaseo has earned a few upgrades via a mysterious hacker who broke into his account and added a new set of powers. These powers, called the \"Xth\" form, allow Haseo to use a pair of pistols with blades on the barrel. With these weapons Haseo can deal greater damage and perform a \"double trigger\" attack by invoking a special ability. \n\nThe level cap is increased to 150, and gamers can add up to 22 additional avatars to their party. In the heat of battle, if players find themselves at the losing end, they can access the \"avatar awakening\" power and drain the virus cores from the enemy. Additionally, there are new cards for the \"Crimson Versus\" game and a new arena battle.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/12768","developer":"Cyberconnect2","coverName":"","players":"1","publisher":"Namco Bandai Games America","esrb":"T - Teen","rating":{"score":3.51,"count":77}},{"id":"shin-megami-tensei-devil-summoner-raidou-kuzunoha-vs-the-soulless-army","title":"Shin Megami Tensei: Devil Summoner: Raidou Kuzunoha vs. The Soulless Army","year":2006,"genres":["RPG"],"description":"Shin Megami Tensei: Devil Summoner: Raidou Kuzunoha vs the Soulless Army is a role-playing game on Playstation 2. You play as Raidou Kuzunoha, a young detective who will discover over time that a vast conspiracy organized by men and demons eager to power is being formed. Face your opponents during the different quests of the game over a dozen episodes in total.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/13111","developer":"Atlus","coverName":"Shin Megami Tensei - Devil Summoner - Raidou Kuzunoha vs. The Soulless Army (USA)","players":"1","publisher":"Atlus","esrb":"M - Mature","rating":{"score":4.32,"count":77}},{"id":"tales-of-the-abyss","title":"Tales of the Abyss","year":2006,"genres":["Action","RPG"],"description":"A TALE OF HONOR AND SACRIFICE, OR DUTY AND CHOICE, OF WHAT IS WRITTEN AND WHAT WILL BE.\nLuke fon fabre, sole heir to a family of aristocrats, has led a sheltered life within the family's residence, learning little of the world beyond the palace walls. Suddenly thrust into the outside world, Luke is caught in the workings of the Order of Lorelei, keepers of the prophecy known as the Score. Finding himself in a confusing and often hostile world, he has not yet noticed the evil that is drawing close to him.\n\nUse Fields of Fonons to transform strikes and spells into devastating displays of power.\nThe most realistic character models to date in the series, with characters designed by renowned artist Kosuke Fujishima.\nDetailed expressions and innovative camera angles immerse players into the story like never before.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/13119","developer":"Namco Tales Studio","coverName":"Tales of the Abyss (USA)","players":"1","publisher":"Namco Bandai Games","esrb":"T - Teen","rating":{"score":4.26,"count":77}},{"id":"monster-hunter","title":"Monster Hunter","year":2004,"genres":["Action","RPG"],"description":"Monster Hunter places the player in the role of an up-and-coming hunter who must accomplish various quests to achieve glory. Armors, weapons, and other items are created from the remains of slain monsters by carving off their horns, scales and bones, as well as from mining for ores in the field. Monster Hunter plays in a similar fashion to Phantasy Star Online allowing the player to team up with up to three other hunters online to take down stronger monsters.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/13102","developer":"Capcom Production Studio 1","coverName":"Monster Hunter (USA)","players":"1","publisher":"Capcom","esrb":"T - Teen","rating":{"score":4.05,"count":77}},{"id":"harry-potter-and-the-chamber-of-secrets","title":"Harry Potter and the Chamber of Secrets","year":2002,"genres":["Action","Adventure"],"description":"In this Harry Potter game, join him during his second term at Hogwarts School of Witchcraft and Wizardry.\n\nA dark plot against his \"Mudblood\" classmates has Harry befuddled as more and more students are strangely petrified. Harry must learn new spells and cast them without mistake to uncover the secrets and solve the mysteries.\n\nInteract with familiar characters from the movie: Ron, Hermoine and, of course, Gilderoy Lockhart. Additionally, there are multiple mini-games and side quests.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/7184","developer":"Electronic Arts UK","coverName":"Harry Potter and the Chamber of Secrets (USA)","players":"1","publisher":"Electronic Arts","esrb":"E - Everyone","rating":{"score":3.97,"count":77}},{"id":"timesplitters","title":"TimeSplitters","year":2000,"genres":["Shooter"],"description":"The TimeSplitters are an evil race dwelling outside of time and space. Roused from an ancient sleep, they cross the threshold from their shadowy dimension, ripping through the fabric of time itself to make humanity history. Can we unite against a common enemy? Or will we be condemned forever to a realm ruled under the shadow of the TimeSplitters. In the 1-player game you travel from time to time to collect different artifacts before the Timesplitters can. The multiplayer game is 4-player Deathmatch with the option of adding several bots.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/9232","developer":"Free Radical Design","coverName":"TimeSplitters (USA) (v1.10)","players":"4","publisher":"Eidos Interactive","esrb":"T - Teen","rating":{"score":4.03,"count":77}},{"id":"007-quantum-of-solace","title":"007: Quantum of Solace","year":2008,"genres":["Shooter"],"description":"Players take the role of the darker, grittier James Bond in Quantum of Solace, the first 007 game from publisher Activision. Following Daniel Craig's portrayal of a violent, driven Bond, the young MI6 agent's methods may be messy, but he is ultimately effective. Gameplay features plenty of gun-fighting and hand-to-hand combat, as well as surveillance and stealth sequences. The game is built on Infinity Ward's Call of Duty 4 game engine, and features similar graphical quality, third-person cut-aways, and enemy AI.","descriptionSource":"https://gamesdb.launchbox-app.com/games/details/18837","developer":"Eurocom Developments","coverName":"007 - Quantum of Solace (USA)","players":"1","publisher":"Activision Publishing","esrb":"T - Teen","rating":{"score":3.82,"count":76}}];
